  str_dispatch_book_bookname_5000 = "Receita Rediesel",
  str_dispatch_book_bookname_6000 = "Geografia de Northland",
  str_dispatch_book_bookname_7000 = "Crônicas do Juízo Final",
  str_dispatch_book_bookname_8000 = "Tomos Antigos Ocultos",
  str_dispatch_book_bookname_9000 = "Uma Viagem Aventureira",
  str_dispatch_book_bookname_10000 = "Guia Social de Illumina",
  str_dispatch_book_bookname_11000 = "Ada e a Colossus",
  str_dispatch_book_bookname_12000 = "Raiar da Jornada",
  str_dispatch_book_bookname_13000 = "Balada Nevada",
  str_dispatch_book_bookname_14000 = "Correspondente de Rosa e M&M",
  str_dispatch_book_bookname_15000 = "Sra. Mercúrio Verm.",
  str_dispatch_book_bookdes_1000 = "Um tomo que supostamente era guardado no Templo de Lumópolis. Devido a seus conteúdos obscuros e esotéricos, nunca foi liberado para o público ler. Depois de reaparecer, após uma ausência misteriosa de um século, ele foi transcrito e distribuído em massa e se tornou um título conhecido por todos.",
  str_dispatch_book_bookdes_2000 = "O livro narra parte da história da terra natal dos semi-humanos, o Território Secreto, incluindo sua fundação, sua queda devido à incursão Eclipsita, e sua ocupação final pelos mesmos Eclipsitas. Por meio desse livro, podemos ter um entendimento geral da tragédia que ocorreu há centenas de anos, assim como aprofundar nosso entendimento sobre as atuais estruturas de poder do nosso mundo.",
  str_dispatch_book_bookdes_3000 = "O registro de um mercenário sem-nome, de sua carreira como lutador de aluguel, assim como de seus esforços para estabelecer uma equipe pessoal de mercenários. Não se sabe o ano em que o diário foi escrito, mas parece ser bem moderno. Somente os meses foram incluídos no título de cada entrada. A letra é bela e fácil de entender, e podemos enxergar um certo otimismo nas entrelinhas.",
  str_dispatch_book_bookdes_4000 = "Um tipo de sonho, um tipo de uivo, um tipo de desespero. Cheio de brigas mal resolvidas de tempos antigos, assim como ansiedades bizarras sobre o futuro... Mas o que de fato torna tudo chato e sem sentido, é que esse livro não passa de uma imitação inferior. Apesar de nossos mais profundo esforços para entendê-lo, nada chega perto de realmente descrever a grande, antiga e adormecida Verdade.\n... Será mesmo?",
  str_dispatch_book_bookdes_5000 = "Viajante do tempo em meio período e amante de comida em tempo integral, Master Chef do Deserto Rediesel e expert em carne Eclipsita – esse sou eu! Se estiver perdido no deserto, você tem muita coragem ou muita burrice, mas não se preocupe, enquanto carregar o livro de receitas do Tio Johnny, sua última refeição não será de areia! Seria bem difícil digerir! Hahaha! Que boboca!",
  str_dispatch_book_bookdes_6000 = "Nem todo mundo sabe que, além de ser a Guia de Lumópolis, Srta. Blanc também é uma viajante ávida e guia de turismo talentosa (porém seus tours guiados são somente para seus convidados mais íntimos e respeitados). Tivemos o prazer de entrevistar a Srta. Blanc e esse livro é uma compilação dos assuntos discutidos.\nClientes que comprarem o livro em pré-venda, em uma de nossas livrarias parceiras, vão receber um cartão postal especial da Srta. Blanc, e dez compradores sortudos receberão um cartão postal autografado de brinde.",
  str_dispatch_book_bookdes_7000 = "As Crônicas do Juízo Final são uma compilação de registros escritos, supostamente de civilizações antigas que habitavam a periferia de Northland. Depois de ser originalmente descoberto, pesquisadores concluíram que o dano extenso aos registros foi proposital, e não resultado da passagem do tempo. Felizmente, várias passagens do tomo estavam em condições relativamente completas. As passagens fragmentadas parecem profetizar uma catástrofe apocalíptica...",
  str_dispatch_book_bookdes_8000 = "Acredita-se que os Tomos Antigos Ocultos foram escritos pelo primeiro Líder de Ciência e Tecnologia de Illumina. Eram uma compilação de anos de pesquisa científica e tecnológica sobre a civilização antiga, e inúmeros registros experimentais, que agora se perderam no tempo. Com a saída desse Líder, os Tomos Antigos Ocultos também desapareceram. Atualmente, só uma fração do conhecimento encontrado nos tomos está em circulação, porém sua autenticidade é geralmente questionada.",
  str_dispatch_book_bookdes_9000 = "“Uma Viagem Aventureira” é uma aventura ficcional escrita por um novelista nascido em Umbraton. Conta a história de um jovem que vai para o mar com a marinha de seu reino, encontrando toda sorte de monstros e mistérios e, por fim, descobrindo um tesouro lendário e defendendo seu reino de um monstro das profundezas. Há muitos capítulos na história, mas só os seguintes restaram no primeiro volume.",
  str_dispatch_book_bookdes_10000 = "A Federação Illumina de Astra, conhecida popularmente como Illumina, cuja capital está localizada na Cidade Gannon. Escrito pelo Escritório de Administração Federal de Illumina, em parceria com os consultores do Conselho Federal de Illumina, as forças armadas da Federação de Illumina e o Centro de Pesquisa de Illumina, esse livro tem o propósito de fornecer diretrizes apropriadas para todos os cidadãos recém-integrados de Illumina.",
  str_dispatch_book_bookdes_11000 = "Ada e a Colossus, escrito por Hayden, é um conto de fadas popular em Eraveil e uma inspiração para os Celestitas. O livro conta a história de uma garota Celestita chamada Ada, que estabelece uma ligação mental com Kaz, a Colossus mais fraca, e deixa Eraveil para explorar o mundo. Por meio de suas aventuras, o autor explica conceitos como Eoria, o dia sem-fim e a noite sem-fim, Aurorians, Eclipsitas, entre outros.",
  str_dispatch_book_bookdes_12000 = "Mina é uma famosa viajante, cujos diários são amplamente lidos pelos Aurorians de Astra. Em um de seus diários de viagem, Mina descreve o remorso que guardou no coração desde que era uma garotinha. Enquanto crescia em uma vila, às margens do Rio Áureo, ela formou uma profunda amizade com um Cavaleiro de Lumópolis chamado Sheriozha. Mas, no fim, eles seguiram seus próprios caminhos. Nesta história, intitulada Raiar da Jornada, os véus que cobrem os Cavaleiros Lumo e a Luminática serão levantados um por um.",
  str_dispatch_book_bookdes_13000 = "Essa é uma história que circula em Northland, embora ninguém saiba se é verdade, mas um menestrel vagando por Northland coletou-a em uma antologia... Dois Aurorians órfãos de cabelo loiro de partes desconhecidas se encontraram em uma vila de Northland e formaram um vínculo através de ajuda mútua e aceitação. Além disso, também teremos um vislumbre da vida cotidiana dos Aurorians de Northland na história.",
  str_dispatch_book_bookdes_14000 = "Esta é uma pilha de correspondência entre uma técnica, Rosa, em Rediesel Desert e a loja de peças em segunda mão M&M em Umbraton. Para obter peças baratas para seus projetos de modificação, Rosa procurou a loja de peças M&M em Umbraton que tinha exatamente o que ela precisava. A cooperação deles durou mais de uma década até que Rosa faleceu. Poderíamos dar uma espiada na vida cotidiana em Rediesel Desert e Umbraton através dessas cartas.",
  str_dispatch_book_bookdes_15000 = "Yvonne era uma romancista famosa. Suas obras são conhecidas por mesclar eventos da vida real e pessoas com ficção. Mrs. Red Mercury foi um de seus contos mais famosos. Era sobre a lendária história da Sra. Red Mercury, a líder da Umbraton's Guild. A história foi reimpressa muitas vezes. O editor responsável pela segunda edição se engajou na pesquisa textual de pessoas e eventos da história. Foi então gravado no posfácio para compartilhar com todos os leitores. Os leitores puderam então vislumbrar como era décadas atrás em Umbraton.",
  str_dispatch_book_ce = "{1} Volume(s)",
