  str_dispatch_book_chaptername_15000_9 = "Assassinato",
  str_dispatch_book_chaptername_15000_10 = "O fim",
  str_dispatch_book_chaptername_15000_11 = "Posfácio do Editor (Parte 1)",
  str_dispatch_book_chaptername_15000_12 = "Posfácio do Editor (Parte 2)",
  str_dispatch_book_chapterdes_1000_1 = "Os fiéis conhecerão a Revelação. Prostra-te e escuta, com temor e compaixão em teu coração.\nOs infiéis nunca conhecerão a Revelação. Condenados estão a viver ofuscados em ignorância e desordem.\nOs que conhecerem a Revelação conhecerão a guerra, mas também escaparão da destruição.\nOs que não conhecerem a Revelação escaparão da guerra, mas viverão como pessoas destruídas.",
  str_dispatch_book_chapterdes_1000_2 = "“O Deus da Luz lutará por todos, então todos devem se manter parados e em silêncio.\nO Deus da Luz abre os mares e quebra as montanhas, então todos devem se manter parados e em silêncio.”",
  str_dispatch_book_chapterdes_1000_3 = "“Entre as duas criações, deve ser feito um julgamento, para que todos conheçam os caminhos do nosso Deus da Luz.\nAqueles que O adoram, e aqueles que não acreditam, devem todos responder por suas vidas, sem indulto.”",
  str_dispatch_book_chapterdes_1000_4 = "“Todos os seus pedidos serão concedidos,\nE todos os seus votos recompensados,\nLembrem-se de minhas palavras pela eternidade, e da promessa que foi feita.\nA Revelação será eterna.”",
  str_dispatch_book_chapterdes_2000_1 = "Por meio das maquinações do destino, os semi-humanos descobriram a maior caverna feita pelo homem da história. Ambiciosos, porém ingênuos por natureza, eles iniciaram a tarefa de criar sua própria “Terra Prometida” com o fervor de mover montanhas e abrir os mares.",
  str_dispatch_book_chapterdes_2000_2 = "Há mais de mil anos, os semi-humanos descobriram o Território Secreto. Após centenas de anos, inúmeros semi-humanos haviam nascido, crescido e morrido ali. Semi-humanos acreditam, então, que o Território Secreto foi a herança valiosa deixada por seus ancestrais e o lar sagrado supremo de sua raça. Somente após a invasão da horda Eclipsita, os semi-humanos finalmente perderam o controle do Território Secreto...",
  str_dispatch_book_chapterdes_2000_3 = "O Território Secreto era o lar físico e espiritual de todos os semi-humanos. Durante a incursão Eclipsita, os semi-humanos que habitavam as cavernas não foram os únicos que lutaram até a morte. Semi-humanos de todas as camadas sociais, de todos os cantos do mundo, voltaram para lutar com seu povo. Foi essa devoção inabalável, quase obsessiva à sua terra que causou, por fim, sua destruição.",
  str_dispatch_book_chapterdes_2000_4 = "A completa erradicação dos semi-humanos foi um choque para os Aurorians. Para averiguar a causa de sua destruição, a Federação Illumina enviou a corajosa Equipe de Expedição ao Território Secreto infestado de Eclipsitas. Nessa época, o Território Secreto já havia se tornado um local de morte e perigo sem iguais, fazendo com que até mesmo os soldados mais leais a Illumina tremessem de medo.",
  str_dispatch_book_chapterdes_3000_1 = "O relato do mercenário sem-nome sobre os eventos seguintes à finalização de uma missão. Para preservar o segredo, parece que o mercenário apagou ou riscou os nomes de quaisquer locais mencionados no registro, deixando para o leitor especular as locações.",
  str_dispatch_book_chapterdes_3000_2 = "Outro registro do mercenário sem-nome, parece que a compensação pelo trabalho anterior não foi o que imaginava. Além disso, também teve dificuldades na missão seguinte.",
  str_dispatch_book_chapterdes_3000_3 = "Após ter um enorme contratempo financeiro, e não conseguir terminar uma missão difícil, o mercenário sem-nome procurou um trabalho fora de sua área de conhecimento normal. Lendo essa entrada, podemos sentir um vago teor de felicidade e contentamento nas palavras do autor.",
  str_dispatch_book_chapterdes_3000_4 = "Na última entrada do diário do mercenário sem-nome, ele relembra o trabalho de sua vida como mercenário, e descreve os planos para uma nova vida. O leitor se enche de um forte senso de esperança.",
  str_dispatch_book_chapterdes_4000_1 = "A Verdade não pode ser vista;\nAprendiz, você foi visto;\nChame-a, e conheça seu lugar;\nEla não será negada.",
  str_dispatch_book_chapterdes_4000_2 = "Aparentemente, ela existe em todo lugar;\nA dor, ela incha num instante.\nE em todo lugar, deveria existir;\nAs flores, desabrocham num mar do próprio sangue.",
  str_dispatch_book_chapterdes_4000_3 = "A lama é a face da Verdade;\nA lama é o gosto da Verdade;\nEngoli-la é obter a Verdade;\nSentir seu gosto é conhecer a Verdade.",
  str_dispatch_book_chapterdes_4000_4 = "Esse dia, nunca chegará;\nAcredite, a queda é uma mentira.\nA morte já chegou e se foi;\nMas o prazer jamais desaparecerá.",
  str_dispatch_book_chapterdes_5000_1 = "Se vier ao Deserto Rediesel, tem que comer alguma coisa que não vai achar em nenhum outro lugar! Se está procurando a cozinha esnobe, de nariz em pé, faça um favor a si mesmo e volte por onde veio. Aqui, em nosso pitoresco Deserto Rediesel, espere se deliciar com bife de verme de areia, grilos fritos, camelo no vapor e cacto Rediesel!",
  str_dispatch_book_chapterdes_5000_2 = "A essas horas você deve estar pensando: “esses caras do deserto devem mesmo beber rediesel pra serem loucos de comer isso!” Mas errou feio! Quando os meninos estão com sede, vamos à lanchonete favorita do Tio Johnny, a Verme de Areia Contorcido, para bons sucos e boas experiências! Hein? Não pode beber açúcar? Hahaha, também servem leite de camelo!",
  str_dispatch_book_chapterdes_5000_3 = "Como assim? Você é vegetariano? Por favor, isso não é desculpa para não aceitar carne de camelo! É só fingir que é fruta ou algo assim! Eu não conto se você não contar, ok? Só experimente, prometo que vai adorar depois da primeira mordida!",
  str_dispatch_book_chapterdes_5000_4 = "Tempero! Calor! Essas são as verdadeiras marcas do Deserto Rediesel. Pimenta que faz você cuspir fumaça e fogo por ouvidos e boca! O calor vai explodir o tampo da sua cabeça! Se não aguenta comida apimentada, de jeito nenhum vai aguentar as dificuldades do Deserto Rediesel, simples assim! Há um antigo ditado que diz: \"Os únicos bons lutadores são os que comem comida apimentada!\"",
  str_dispatch_book_chapterdes_5000_5 = "Sempre ouço os jovens falando em ver o mundo e experimentar comidas diferentes, então por que eles hesitam quando chegam ao Deserto Rediesel? Fala sério, ninguém vai te obrigar a comer areia, seus idiotas! Se bem que eu sei que arroz de arenito é um prato de verdade na Ilha Sharkfang.",
  str_dispatch_book_chapterdes_6000_1 = "As pessoas costumam dizer que lagos são piscinas de lágrimas derramadas pelos próprios deuses, e o Lago Espelho não é exceção. É o lago mais antigo e possivelmente o mais bonito do continente, uma grande tragédia deve ter atingido os deuses para criarem um lugar assim.",
  str_dispatch_book_chapterdes_6000_2 = "Apesar de ficar nas fronteiras sul de Northland, a Floresta Barlavento não tem o mesmo clima frio e cortante que é geralmente associado a esse reino coberto de neve. Tem o clima quente e agradável quase o ano todo, e dizem que a flora e a fauna dessa floresta se aproveitam de uma vida próspera, abrigadas do vento.",
  str_dispatch_book_chapterdes_6000_3 = "À primeira vista pode parecer uma vasta colina, mas de acordo com as lendas locais, a real aparência da Pinha de Northland é conhecida como o “Cristal Despedaçado”.",
  str_dispatch_book_chapterdes_6000_4 = "O Palácio Invernal, localizado no centro da Espinha do Mundo, é um palácio construído inteiramente de gelo. É o lar da Rainha Bethlehem e base do governo Northland.",
  str_dispatch_book_chapterdes_7000_1 = "Um fragmento do livro, chamado “Antes da Escuridão Cair”. As partes faltantes da passagem mostram sinais claros de terem sido apagadas.",
  str_dispatch_book_chapterdes_7000_2 = "Pesquisadores concordam que essa passagem não foi escrita pelos mesmos autores antigos que o resto das passagens, mas por um autor de tempos mais recentes. Até hoje, apesar de ser parte das Crônicas do Juízo Final, ainda não se consegue relacioná-la com o fim dos dias.",
  str_dispatch_book_chapterdes_7000_3 = "O fragmento está sem uma parte da primeira metade. Pesquisadores especulam que os \"eles\" mencionados na passagem são os que viveram antes da guerra, e o \"nós\" faz referência aos que deixaram esses registros.",
  str_dispatch_book_chapterdes_8000_1 = "Um arquivo experimental sobre o codinome “Valquíria”, descoberto nas ruínas da antiga civilização nas profundezas das montanhas Northland. Um grande esconderijo de arquivos e dados experimentais também foi encontrado na área, mas a maioria deles havia sido destruída ou deixada ininteligível por causas desconhecidas.",
  str_dispatch_book_chapterdes_8000_2 = "Parte do manuscrito de um cientista, descoberto nas ruínas próximas à cidade de Baas. A leitura revela que ele usou a própria filha como cobaia em experimentos grotescos.",
  str_dispatch_book_chapterdes_8000_3 = "Uma coleção fragmentada de páginas de uma fonte antiga, encontrada em circulação pelos assentamentos que rodeiam o Deserto Rediesel. Parece ser um registro de combate, porém desconhece-se a data, local e identidade dos combatentes. O que se sabe, ao ler as páginas, no entanto, é o conhecimento avançado sobre a tecnologia das civilizações antigas.",
  str_dispatch_book_chapterdes_8000_4 = "Acredita-se que essa passagem rasgada foi encontrada próxima às ruínas da Cidade Velha. Parece ser um capítulo de um romance, ou um tipo de registro, sobre a lenda de uma figura conhecida como \"Drácula\".",
  str_dispatch_book_chapterdes_9000_1 = "O reino convoca seus campeões para explorar novas ilhas no mar. O terceiro capítulo, de título “A Tempestade”, conta a história do encontro da marinha real com uma tempestade terrível, e como o jovem Colin ganha o respeito dos colegas por causa de sua bravura.",
  str_dispatch_book_chapterdes_9000_2 = "Os heróis do reino começam a explorar as ilhas em busca de tesouros. “As Sete Ilhas”, segundo capítulo da história, conta a experiência angustiante da equipe com um dragão na segunda ilha. No entanto, ao bater em retirada para a primeira ilha, descobrem que ela desapareceu completamente...",
  str_dispatch_book_chapterdes_9000_3 = "O Grande Papagaio e sua equipe caem em uma emboscada do enorme monstro marinho e seus tentáculos, e são arrastados para as profundezas salgadas. “O Reino Submerso”, quarto capítulo da história, conta como Colin e os outros acordam depois do ataque e se encontram em um reino submarino misterioso.",
  str_dispatch_book_chapterdes_9000_4 = "Os heróis do reino buscam uma forma de derrotar a besta colossal, que surgiu das profundezas do mar. “O Monstro das Profundezas”, sexto capítulo da história, conta a história de Colin, o Valente, e seus colegas ao chegarem na ilha em que a última parte do tesouro está escondida. É aqui que o monstro das profundezas finalmente revela sua verdadeira forma para os guerreiros...",
  str_dispatch_book_chapterdes_10000_1 = "Uma seção do guia social da vida de Illumina, que fala principalmente das crenças mais importantes do povo de Illumina.",
  str_dispatch_book_chapterdes_10000_2 = "Uma seção do guia social da vida de Illumina, que fala principalmente das disciplinas importantes observadas pelo povo de Illumina.",
  str_dispatch_book_chapterdes_10000_3 = "Uma seção do guia social da vida de Illumina, que cobre principalmente o conhecimento cultural que todos os cidadãos de Illumina devem entender.",
  str_dispatch_book_chapterdes_10000_4 = "Uma parte do guia de interações sociais e convívio de Illumina. Essa seção fala sobre o código de conduta que todos em Illumina devem conhecer.",
  str_dispatch_book_chapterdes_10000_5 = "Uma parte do guia de interações sociais e convívio de Illumina. Essa seção fala sobre todas as normas que cada um em Illumina deve seguir.",
  str_dispatch_book_chapterdes_11000_1 = "Naquele dia, Ava e Kaz, a Colossus mais fraca, levantaram voo para a noite estrelada, longe de Eraveil, o único lugar em que já viveram. O mundo lá fora lentamente se desdobra como uma pintura. A Aurora ilumina o céu no primeiro capítulo de sua aventura fantástica.",
  str_dispatch_book_chapterdes_11000_2 = "Os estranhos animaizinhos que se intitularam “semi-humanos” têm pelo bagunçado no corpo todo e são felpudos. Nem uma Colossus consegue resistir! Tire um gostoso dia de preguiça sob o sol, para fazer carinho nessas criaturas fofinhas.",
  str_dispatch_book_chapterdes_11000_3 = "A Colossus coberta de flores chegou ao fim da vida. Ela está longe de Eraveil há muito tempo. Assim como Ada e Kaz, ela também ficou fascinada com o mundo exterior, junto do navegador. Mas será que ir lá fora é a escolha certa? Se você caminhar para longe demais, pode ser que não encontre o caminho de casa.",
  str_dispatch_book_chapterdes_11000_4 = "A nave viajando pelo deserto para na frente de Ada e Kaz. Ela leva um grupo de misteriosos viajantes Aurorians. O vento faz a areia fina subir do chão. A nave não está navegando nas dunas, mas seguindo a trilha das estrelas.",
  str_dispatch_book_chapterdes_11000_5 = "Ada e Kaz deixam pegadas pelo mundo todo, exceto em um lugar: o Eraveil. Talvez seja hora de voltar aonde tudo começou.",
  str_dispatch_book_chapterdes_12000_1 = "Para Mina, os dias confinada nas margens do Rio Áureo durante a adolescência foram inesquecíveis. No passado, sua vida não possuía qualquer emoção ou significado, forçando-a a suportar uma existência banal. Mas tudo mudou com o aparecimento da caravana.",
  str_dispatch_book_chapterdes_12000_2 = "Para Mina, os dias confinada nas margens do Rio Áureo durante a adolescência foram inesquecíveis. No passado, sua vida não possuía qualquer emoção ou significado, forçando-a a suportar uma existência banal. Mas tudo mudou com o aparecimento da caravana.",
  str_dispatch_book_chapterdes_12000_3 = "Quando a caravana recusou o pedido de Mina para negociar produtos, ela sentiu-se perdida e envergonhada. Foi quando um homem vestindo uma armadura branca salvou-a de sua infelicidade. Mina então descobriu seu nome: Sheriozha.",
  str_dispatch_book_chapterdes_12000_4 = "Quando a caravana recusou o pedido de Mina para negociar produtos, ela sentiu-se perdida e envergonhada. Foi quando um homem vestindo uma armadura branca salvou-a de sua infelicidade. Mina então descobriu seu nome: Sheriozha.",
  str_dispatch_book_chapterdes_12000_5 = "Após Sheriozha partir da vila, ele enviou regularmente cartas para Mina. Ela fantasiava incessantemente sobre o mundo exterior, tanto que um dia decidiu fugir da vila para explorar seus mistérios.",
  str_dispatch_book_chapterdes_12000_6 = "Após Sheriozha partir da vila, ele enviou regularmente cartas para Mina. Ela fantasiava incessantemente sobre o mundo exterior, tanto que um dia decidiu fugir da vila para explorar seus mistérios.",
  str_dispatch_book_chapterdes_12000_7 = "Mina tentou entrar para a União Mensageira, mas sua solicitação foi negada. Enquanto esperava pela próxima carta de Sheriozha, ela começou a perder as esperanças, até decidir deixar o local onde havia se reinventado para ver o mundo exterior com os próprios olhos. Sua primeira parada foi Lumópolis.",
  str_dispatch_book_chapterdes_12000_8 = "Mina tentou entrar para a União Mensageira, mas sua solicitação foi negada. Enquanto esperava pela próxima carta de Sheriozha, ela começou a perder as esperanças, até decidir deixar o local onde havia se reinventado para ver o mundo exterior com os próprios olhos. Sua primeira parada foi Lumópolis.",
  str_dispatch_book_chapterdes_12000_9 = "Após ter sua entrada em Lumópolis negada, por sorte Mina conseguiu uma segunda chance, e ainda por cima sem custos. Ao entrar na cidade, ela perguntou sobre a residência de Sheriozha, mas não foi capaz de reunir informações confiáveis.",
  str_dispatch_book_chapterdes_12000_10 = "Após ter sua entrada em Lumópolis negada, por sorte Mina conseguiu uma segunda chance, e ainda por cima sem custos. Ao entrar na cidade, ela perguntou sobre a residência de Sheriozha, mas não foi capaz de reunir informações confiáveis.",
  str_dispatch_book_chapterdes_12000_11 = "Enquanto tentava descobrir o endereço de Sheriozha, ela deparou-se com uma enxurrada de informações incríveis. No fim, Mina conseguiu encontrar seu ídolo Sheriozha, mas as coisas não saíram como ela esperava.",
  str_dispatch_book_chapterdes_12000_12 = "Enquanto tentava descobrir o endereço de Sheriozha, ela deparou-se com uma enxurrada de informações incríveis. No fim, Mina conseguiu encontrar seu ídolo Sheriozha, mas as coisas não saíram como ela esperava.",
  str_dispatch_book_chapterdes_13000_1 = "Dorothy e seu irmão viveram em um vila de Northland. Seus pais morreram cedo, então eles passaram a fazer bicos para se sustentar. O ancião esperava que eles pudessem entrar em uma nova família, mas se deparou com a recusa total da menina.",
  str_dispatch_book_chapterdes_13000_2 = "No caminho para casa, os irmãos ajudaram uma Aurorian que caiu na neve. A Aurorian ficou na vila, mas no meio da noite, uma nevasca caiu em sua casa, a forçando a pedir ajuda aos irmãos novamente.",
  str_dispatch_book_chapterdes_13000_3 = "Com a ajuda do ancião, a loira recém-chegada, Martha, foi morar com Dorothy e seu irmão mais novo. Com o tempo, o trio construiu uma relação próxima.",
  str_dispatch_book_chapterdes_13000_4 = "Martha adorava cozinhar e, para isso, até descobriu como obter sal. Após ouvir as explicações de Martha, Dorothy pensou em tentar ela mesma.",
  str_dispatch_book_chapterdes_13000_5 = "Martha fez um jantar para os irmãos e, ao conversar com o irmão mais novo, Cruz, ela descobriu o distanciamento de Dorothy. Mas essa não é a questão. A questão é, estava escuro e Dorothy ainda não havia retornado.",
  str_dispatch_book_chapterdes_13000_6 = "Dorothy havia seguido as orientações de Martha até o lago de água salgada, mas uma nevasca impediu que ela voltasse para casa. Enquanto procurava abrigo, ela infelizmente encontrou lobos vorazes.",
  str_dispatch_book_chapterdes_13000_7 = "Dorothy usou Luminática para repelir o ataque deles, mas o bando era numeroso e ela não conseguiu se proteger. Quando tudo parecia perdido, alguém congelou os lobos raivosos e a salvou do perigo.",
  str_dispatch_book_chapterdes_13000_8 = "O Ano-Novo havia chegado em Northland. Martha, Dorothy e seu irmão estavam juntos. O laço se fortaleceu na celebração de reunião da vila.",
  str_dispatch_book_chapterdes_13000_9 = "Outro recém-chegado apareceu na aldeia, e o comportamento incomum de Martha deixou claro para Dorothy que o visitante veio especificamente por Martha. Martha, porém, se recusou a contar a verdade a Dorothy.",
  str_dispatch_book_chapterdes_13000_10 = "O ancião formou um grupo de busca e, quando Dorothy tentou se juntar às escondidas, Martha a impediu. Durante o confronto, Dorothy disse algo doloroso.",
  str_dispatch_book_chapterdes_13000_11 = "Martha ficou sabendo da causa da morte dos pais dos irmãos, o que a compeliu tomar a decisão de deixar Northland. Ela não poderia suportar a culpa.",
  str_dispatch_book_chapterdes_13000_12 = "Martha partiu, mas foi parada por Dorothy. Dorothy disse que não se importava com o passado de Martha, mas também não iria impedi-la de partir. Ela esperava, no entanto, que Martha voltasse para Northland um dia.",
  str_dispatch_book_chapterdes_14000_1 = "A técnica Rosa ficou bastante chateada com a falta de peças no Deserto Rediesel. Ela viu a loja de peças em segunda mão M&M em um folheto, anunciando ter uma grande coleção de peças a preços justos. Ela fez seu primeiro pedido por meio de uma carta e ficou muito satisfeita com a resposta.",
  str_dispatch_book_chapterdes_14000_2 = "Levou algumas voltas e mais voltas antes que as peças encomendadas finalmente chegassem a Rosa. Ela decidiu usar o Courier Union para suas cartas de pedido a partir de então. A resposta da M&M foi escrita por Minny, filha do dono da loja.",
  str_dispatch_book_chapterdes_14000_3 = "Para se adaptar ao ambiente geográfico especial e ao clima do Deserto Rediesel, Rosa teve que remodelar seu hovercar. Ela revelou sua verdadeira identidade nesta carta como membro de uma equipe de expedição que fugiu da Illumina.",
  str_dispatch_book_chapterdes_14000_4 = "O dono da loja Max concordou com a compra de Rosa a pedido de crédito. Minny mostrou grande interesse nos desenhos de modificação anexos para um hovercar. Ela até fez um motor seguindo os desenhos de Rosa.",
  str_dispatch_book_chapterdes_14000_5 = "A frota de Rosa entrou em uma luta feroz com uma gangue de ladrões. Ela fez uma fortuna com isso e pagou suas dívidas anteriores. Na mesma época, ela acolheu uma jovem chamada Summer, que a levou a muitos objetos criados com tecnologia antiga.",
  str_dispatch_book_chapterdes_14000_6 = "Rosa esperava que a loja de peças pudesse encontrar para ela algumas ferramentas para desmantelar tecnologia antiga, o que certamente não era uma tarefa fácil para a loja familiar. Minny parecia não se importar nem um pouco com o problema do pai. Ela participou da festa de aniversário de Lumopolis e enviou muitos presentes para Rosa.",
  str_dispatch_book_chapterdes_14000_7 = "Rosa planejava modificar uma guitarra para um companheiro de equipe apaixonado por música. Ela agradeceu a Minny por todos os lanches que estava enviando. A comida no Deserto Rediesel estava lhe dando trabalho.",
  str_dispatch_book_chapterdes_14000_8 = "Sua frota roubou um corpo de transporte de Illumina. As coisas saíram do controle e muitas vidas foram perdidas em ambos os lados. Rosa perdeu as pernas, mas o que mais doeu foi atirar em seus antigos companheiros.",
  str_dispatch_book_chapterdes_14000_9 = "Minny enviou a Rosa um convite para seu próximo casamento. Ela não mostrou nenhuma fantasia irreal sobre a vida de casada na carta, mas expressou seu tédio nessa longa e monótona jornada de autocrescimento.",
  str_dispatch_book_chapterdes_14000_10 = "Rosa não pôde comparecer ao casamento de Minny por motivos de saúde, mas fez um buquê de rosas de aço para a noiva, junto com seus melhores votos.",
  str_dispatch_book_chapterdes_14000_11 = "Esta carta foi escrita por Summer. A garotinha que uma vez levou Rosa a procurar objetos criados por tecnologia antiga tornou-se assistente pessoal de Rosa. Summer revelou uma triste notícia para Max e sua filha.",
  str_dispatch_book_chapterdes_14000_12 = "Minny olhou para a correspondência entre Rosa e sua família. Ela considerou Rosa a pessoa mais incrível e única que ela já conheceu e estendeu a mão para a frota, pedindo permissão para uma viagem ao deserto de Rediesel para se despedir de sua amiga.",
  str_dispatch_book_chapterdes_15000_1 = "Meu amigo e eu estávamos assistindo a uma luta no Pit em Umbraton. Os dois lados pareciam incompatíveis, e o lado mais fraco era na verdade um membro de uma guilda. Eu estava extremamente confuso, pois não havia como o líder não fazer nada quando um membro da guilda estava lutando até a morte.",
  str_dispatch_book_chapterdes_15000_2 = "Sem surpresa, o pequeno continuou perdendo. Assim que os espectadores começaram a se preocupar com ele, soou o apito para o intervalo e ele sobreviveu, o que o impediu de ser morto. Só então, uma confusão de preocupação veio de um canto escuro na platéia onde a Sra. Red Mercury estava sentada.",
  str_dispatch_book_chapterdes_15000_3 = "Os cativos na platéia pareciam ter motivado o pequeno o suficiente para ele vencer o combate. No entanto, ainda era incerto o que a Sra. Red Mercury faria com ele.",
  str_dispatch_book_chapterdes_15000_4 = "Depois da viagem ao Poço, eu estava ansioso para perguntar aos meus amigos sobre a Sra. Red Mercury. Havia muitos rumores sobre ela, e apenas alguns deles eram verdadeiros. Mas mesmo assim, suas origens e sua decisão sobre seu casamento foram suficientes para torná-la uma lenda.",
  str_dispatch_book_chapterdes_15000_5 = "Tive a chance de entrar em Lumopolis e, enquanto esperava a aprovação do passe em uma pousada na zona de trânsito, conheci uma pessoa inesperadamente.",
  str_dispatch_book_chapterdes_15000_6 = "Eu tinha medo da Sra. Red Mercury, mas a curiosidade me venceu. Por fim, tive uma excelente oportunidade de me aproximar dela, fingindo não saber quem ela era.",
  str_dispatch_book_chapterdes_15000_7 = "Eu finalmente consegui iniciar uma conversa com a Sra. Red Mercury. Ela mencionou como chegou à zona de trânsito durante nossa conversa. Tinha algo a ver com seus sonhos e com a falta de seus bons amigos.",
  str_dispatch_book_chapterdes_15000_8 = "No dia seguinte, acordei e descobri que a Sra. Red Mercury tinha ido embora. De acordo com o estalajadeiro, um dirigível de Lumopolis veio para levá-la embora. Voltei para o meu quarto sentindo-me melancólica, mas uma surpresa me esperava.",
  str_dispatch_book_chapterdes_15000_9 = "Eu estava muito ansioso com a demora na aprovação para entrar na cidade, então perguntei sobre o que estava acontecendo em Lumopolis. Um disse que um terrível assassinato aconteceu lá, então eu mal podia esperar para saber mais sobre os detalhes depois de entrar.",
  str_dispatch_book_chapterdes_15000_10 = "Quando conheci a ex-funcionária da Sra. Red Mercury em Umbraton, não pude deixar de pedir notícias sobre ela. Em vez de más notícias sobre ela, algo diferente do que eu pensei que aconteceu.",
  str_dispatch_book_chapterdes_15000_11 = "O editor da segunda edição de Mrs. Red Mercury realizou uma pesquisa textual sobre a guilda que contrabandeava armas em Umbraton e um caso de assassinato em Lumopolis. Os detalhes foram compartilhados com os leitores no posfácio.",
  str_dispatch_book_chapterdes_15000_12 = "O editor também compartilhou alguns pensamentos pessoais sobre o personagem da Sra. Red Mercury no posfácio. Ele acreditava que os leitores não precisam tentar encontrar o arquétipo da Sra. Red Mercury, pois esse não é o propósito da escrita da Sra. Yvonne.",
  str_dispatch_book_chaptercont_1000_1 = "A Revelação do Deus da Luz é conceder vida e esperança a todos os Aurorians, instruí-los sobre tudo que for necessário e enviar mensageiros para espalhar a fé entre todos os Aurorians. Os caminhos do Deus da Luz, bem como o testamento da Noite Branca, são revelados aos Aurorians por tudo que eles veem. Aqueles que seguem as profecias e as escrituras desse tomo são fiéis, e serão abençoados pelo Deus da Luz.\n Os sete templos na Noite Branca acima, os santos do passado, presente e futuro e todos que servirem como testemunhas honestas da glória do Deus da Luz serão acolhidos. Sobreviverão ao ciclo eterno do dia e da noite e vencerão todas as catástrofes naturais, adversários demoníacos e os pecados dos antepassados.\n A terra verá um demônio na Noite Branca (acima). À medida que ele descer ao mundo, a terra se tornará amarga, derramando lágrimas de sangue, e tudo conhecerá a verdade.(O que significa \"acima\"?)\n O Deus da Luz proclamará: “Sou a raiz, o mistério e o mundano. Sou o criador e o destruidor de civilizações passadas. Sou o deus de todos os Aurorians, e irmão deles também. Permaneço com todos Aurorians nesse reino de sofrimento, para que possamos sofrer e resistir unidos, e para que eles presenciem meu caminho e o testemunho de meus santos.”\n Nesse fatídico dia, as massas ficaram comovidas pelo testemunho dos santos e ouviram um mensageiro do Deus da Luz chamá-los a distância e dizer: “Tudo o que viram e ouviram hoje vocês escreverão em um livro que será enviado aos sete templos de Lakhbim, Salus, Dâmocles, Grandi, Sardinia, Gannon e Troy.”\n O Deus da Luz apareceu no céu, falando com os santos. Quando os Aurorians diante deles se viraram para olhar, viram sete candelabros de ouro. No meio havia uma figura parecida com um Aurorian. Vestido em mantos longos, com um cinto dourado em volta do torso, cabelos e barba brancos como a mais pura neve. Os olhos dele queimavam feito fogo, e os pés brilhavam como cobre cintilante forjado na mais quente fornalha. O rosto dele brilhava como o sol, e a voz ressoava como o quebrar das ondas. Na mão direita, ele levava um pacote de luz pura. Na esquerda, uma grande e terrível espada de dois gumes.\n Os Aurorians caíram no chão diante dessa visão resplandecente, como se agonizassem na morte. O homem radiante pousou a mão direita sobre a cabeça dos Aurorians e lhes falou gentilmente: “Não temam, pois sou o primeiro e o último. Sou quem viveu e morreu, e agora vive para todo o sempre. Concederei a vocês as chaves do inferno e da morte, para que escrevam o que viram hoje, o que acontece agora e o que acontecerá no futuro.”\n A guerra virá para todos.",
  str_dispatch_book_chaptercont_1000_2 = "Quando chegou a Revelação, um mensageiro rompeu o primeiro selo. Ele viu um Aurorian montado em um cavalo branco no céu, usando uma coroa cor de sangue e disparando flechas na terra. \nQuando o segundo selo foi rompido, um Aurorian montado em um cavalo vermelho surgiu. O demônio ofereceu uma espada para o Aurorian, e assim roubou a paz da terra, fazendo as pessoas matarem umas às outras. \nQuando o terceiro selo foi rompido, um cavalo negro apareceu, seu cavaleiro segurando uma balança, e disse: “Um pecado, uma boa ação, uma vida e um julgamento.” \nQuando o quarto selo foi rompido, um Aurorian morto montado em um cavalo cinza surgiu, liderando habitantes do inferno, que causaram caos na terra. Assim o cavaleiro Aurorian morto espalhou guerra, fome, praga e a ameaça dos Eclipsitas sobre as pessoas do mundo. \nQuando o quinto selo foi rompido, incontáveis pessoas vestidas de branco testemunharam a destruição, e registraram os nomes dos caídos. \nQuando o sexto selo foi rompido, a terra tremeu, o sol ficou preto como o abismo e uma lua cheia pairou no céu, vermelha como sangue. As estrelas no céu começaram a cair como frutas verdes de uma árvore sacudida pela tempestade. O céu se enrolou em si mesmo como um pergaminho. Todas as pessoas, reis ou cidadãos, mercadores ou ministros, escravos ou mestres, abrigaram-se em cavernas e sob pedras. No precipício travava-se a batalha final entre o Deus da Luz e o demônio, e ninguém suportava ficar na presença deles. \nPouco tempo depois, levantou-se um Aurorian da terra em que o sol nascia. Segurando o selo do Deus da Luz, ele proclamou: (“O céu, a terra, o mar e as árvores: ninguém vai ferir os servos do Deus da Luz, enquanto portarem o sinal na testa.”)\nQuando o mensageiro rompeu o sétimo selo, o mundo ficou em silêncio. O mensageiro evocou um Aurorian e colocou sete chifres na cabeça dele. O Aurorian soou a trombeta, uma vez depois da outra. \nNa primeira vez que ele soou a trombeta, caiu uma tempestade de fogo e sangue do céu, e todo o verde do mundo murchou e queimou. \nNa segunda vez que ele soou a trombeta, uma montanha de chamas colidiu com o mar, matando todas as criaturas nele e transformando-o em uma devastação sangrenta e enlameada. \nNa terceira vez que ele soou a trombeta, um meteoro em chamas caiu como uma tocha do céu, secando todos os rios e nascentes no mundo. \nNa quarta vez que ele soou a trombeta, o sol, a lua e as estrelas foram tiradas do céu, cobrindo o mundo em escuridão perpétua. \nNa quinta vez que ele soou a trombeta, um abismo sem-fim apareceu no chão, fumaça e fogo irromperam dele. Incontáveis gafanhotos revestidos de ferro emergiram do abismo, atacando aqueles que não usavam a marca do Deus da Luz. \nNa sexta vez que ele soou a trombeta, uma voz ecoou dizendo: “Liberem as almas aprisionadas do passado.” Um exército de 300 milhões de cavaleiros apareceu, montados em cavalos com armaduras, os corpos queimando com chamas púrpuras e exalando o fedor de enxofre. As cabeças dos cavalos pareciam-se com de leões, com fogo, fumaça e enxofre jorrando da boca. “Avancem e matem os que cometeram assassinatos, feitiçaria, traição e roubo, sem o menor arrependimento.“ \nNa sétima vez que a trombeta soou, um Aurorian apareceu. Sua cabeça era como o sol e seus pés, como pilares em chamas. Ele ficou com o pé direito sobre o mar e o pé esquerdo sobre a terra, e urrou com mais ferocidade que um leão. Quando o rugido cessou, o mensageiro declarou que tudo estava completo e que trazia boas novas para todos os servos do Deus da Luz. \n“Quem portar o selo do nosso deus viverá por toda a eternidade, não importa seu destino na vida. Mas dê falso testemunho sobre outrem, enquanto portar o selo, e será também arrastado para o flagelo da guerra. Os que portarem o selo e passarem desse limite serão testados pelo fogo e pela espada.” \nO julgamento virá para todos.",
  str_dispatch_book_chaptercont_1000_3 = "Guerras e conflitos continuaram atormentando o mundo, mas aqueles com o selo do Deus da Luz conseguiam ver o mensageiro, que declarou: “A hora do julgamento chegou. Quem portar o selo deve adorar aquele que criou os céus, a terra, o mar e toda a vida.“ \nOuviu-se um alto barulho a distância, e a cidade em que as pessoas cediam aos seus pecados desmoronava. \nHouve outro grito. Um grupo de pessoas, que adoravam feras selvagens e portavam suas marcas nas mãos e testa, tentou cruzar o limite, mas foram desprezadas pelo mensageiro do Deus da Luz. “Adoradores de ídolos conhecerão apenas o sofrimento em fogo e enxofre!” Assim, eles foram amaldiçoados por toda a eternidade no inferno. \nOutra voz no céu proclamou: “A partir de hoje, será escrito que todos que portarem o selo do nosso Deus serão abençoados, mesmo após a morte. Nossos seguidores colherão o fruto do próprio trabalho após terminarem-no.” \nUm Aurorian apareceu em cima de uma nuvem no céu, usando uma coroa de ouro e empunhando uma foice afiada nas mãos. Gritando, ele disse: “A colheita está próxima, pois a safra da terra e os frutos das árvores já estão maduros.” \nAssim, em um dia, todo tipo de desastre caiu sobre a terra, em excesso. Morte, dor, fome, praga e guerra cercaram todas as criaturas vivas, pois os pecados delas também estavam maduros. \nO rei vigente da terra chorou e lamentou ao ver a fumaça e o fogo que o consumiriam. Aqueles que satisfaziam-no e a seus próprios desejos choraram, pois compartilhavam do mesmo destino. \nOs mercadores também choraram e se desesperaram, pois não havia ninguém para comprar seus bens. Ouro, prata, joias e sedas; incenso, especiarias e todo tipo de pomadas; madeira, leite, vinho e farinha; gado, ovelhas, carroças e cavalos. Servos e mestres foram todos afetados. Os mercadores choraram e gemeram, sabendo que seus tesouros não significavam nada e suas riquezas eram inúteis. \nO povo tocou seus instrumentos e dançou, mas não podiam mais ouvir ou ver, e assim, sua alegria era insensata. A luz perdeu o brilho, a alegria perdeu o riso, a sabedoria perdeu o encanto, e tudo o que restou foi o nada. \nE aqueles que portavam o selo disseram dos céus: “Salvação, glória e poder ao Deus da Luz, pois o julgamento dele é justo, e também sua punição. Louvem-no e atravessem o limite do agora para o final.” \nA eternidade virá para todos.",
  str_dispatch_book_chaptercont_1000_4 = "A fumaça, o pecado e o mal do mundo não podiam cruzar o limite. Uma voz no portão disse: “O reino da terra é o reino do Deus da Luz, agora e para sempre.” \n Aqueles que portavam o selo ouviram a voz do mensageiro dizer: “Louvado seja o Deus da Luz, pois ele é nosso governante.” \n Assim, aqueles que portavam o selo alegraram-se, pois a glória dele foi concedida a todos eles. Eles vestiram roupas do mais puro branco, um símbolo da virtude deles. \n O mensageiro falou: “Que seja escrito: abençoados são aqueles que portam o selo dele na testa. Essa é a palavra verdadeira do nosso deus.” \n Os fiéis caíram diante dos pés do mensageiro, louvando-o, mas a isso ele respondeu: “Parem com isso, pois somos todos servos dele. Adorem apenas o Deus da Luz, testemunhem o esplendor dele, como quer sua profecia.” \n “Um Aurorian descerá do céu, segurando uma grande corrente e a chave para o abismo sem-fim. Ele juntará todos os demônios, prendendo-os em correntes e mandando-os para o abismo sem-fim. Com a chave, ele os selará, e assim eles não causarão mais o mal. Só quando os que portarem o selo começarem a se desviar do caminho, os demônios poderão retornar, brevemente, ao mundo de novo.” \n O mensageiro, exercendo mais uma vez sua autoridade como um agente do Deus da Luz, evocou as almas daqueles que foram executados injustamente, daqueles que não adoravam a imagem de feras e nem portavam suas marcas, e trouxe-os de volta à vida para regozijarem-se com os outros. Essa foi a primeira ressurreição. Aqueles que não fizeram parte dela tiveram de esperar um milhão de anos. \n Aqueles que fizeram parte da primeira ressurreição eram abençoados, puros e felizes. Nunca sentiriam a morte de novo, e atuariam como sacerdotes e mensageiros do Deus da Luz por um milhão de anos. \n Depois de um milhão de anos, os demônios emergirão do abismo para confundir as pessoas na terra e chamarem-nas à batalha. Os seguidores deles serão tão numerosos como os grãos de areia no deserto, e cobrirão a terra cercando os povoados daqueles que portam o selo. O Deus da Luz então fará chover fogo dos céus para queimá-los. Os demônios serão mandados para um lago de fogo e enxofre com as feras, para sofrer e queimarem por toda eternidade. \n Perante um trono branco, os mortos ficarão em fila, sem exceção. A história de cada homem, mulher e criança será exposta e todos serão julgados pelo que estiver escrito em seus registros. Assim a terra, o mar e todo o inferno ofereceram seus mortos para o julgamento, e foram jogados no lago de fogo. Essa foi a segunda morte. \n Um novo céu e terra podia ser visto, pois havia passado o tempo dos antepassados. Uma cidade nova e resplandecente foi preparada e enviada do céu. Uma voz soou, e disse: “Veja! Nosso deus agora vive e reina na terra, pois ele deseja viver entre nós como nosso vizinho e salvador.” \n “O Deus da Luz deseja limpar as lágrimas dos nossos olhos, e acabar com a morte, tristeza, dor e sofrimento, pois tudo isso agora é coisa do passado.” \n “Vejam agora, tudo foi renovado. Que seja escrito: essas coisas são verdade, e minhas palavras são verdade.” \n “Tudo está completo. Somos o começo e o fim, e os vitoriosos herdarão tudo isso. A glória de nosso Deus brilha na cidade, mais brilhante do que a joia mais valiosa, e mais transparente que vidro. Os portões da cidade nunca se fecharão, pois a noite não virá mais. Os que são impuros, que mentem e cometem atrocidades, nunca entrarão nesse lugar.” \n “Pela cidade serpenteia o Rio da Vida, brilhante como cristal. Ele nutre as árvores em suas margens e, em troca, os frutos delas nutrem as pessoas e curam-nas do sofrimento e da aflição.” \n Assim falou o mensageiro: “Não ocultem as profecias desse livro, pois esses dias estão quase sobre nós.” \n A revelação virá para todos.",
  str_dispatch_book_chaptercont_2000_1 = "Há mais de mil anos, os semi-humanos nômades descobriram essa singular caverna durante suas viagens por Astra. O que eles não perceberam na época era que a caverna, presumivelmente apenas um lugar para descansar por um tempo, viria a se tornar o berço da renascença dos semi-humanos.\nApós décadas de exploração, os semi-humanos descobriram os resquícios tecnológicos de uma civilização ancestral. Aos poucos, eles chegaram à suposição que as pessoas dessa civilização ancestral usaram a enorme caverna para experimentos. Ao mesmo tempo, os semi-humanos que habitavam a caverna perceberam que seus corpos tornaram-se muito mais fortes se comparado àqueles que continuavam nômades. A sensibilidade deles à Lúmina também aumentou consideravelmente. Esse fenômeno, por mais estranho que fosse, parecia acontecer exclusivamente com os semi-humanos. Nenhuma mudança foi percebida nos Aurorians ou Celestitas que visitavam a caverna. A única coisa que as outras raças sentiam era que o ecossistema da caverna era peculiar, em especial, que não se alterava com o passar das estações. O clima na caverna era sempre agradavelmente quente e confortável. O resultado dessa descoberta foi que os semi-humanos declararam a caverna sua Terra Prometida, enviada pelo céu. A gigante cidade que eles construíram lá ficou conhecida como Território Secreto.\nDepois de mais de dez gerações de trabalho duro, os semi-humanos criaram para si uma civilização gloriosa e independente, uma que não apenas usava a tecnologia ancestral da caverna, mas construía e melhorava a partir dela. A gloriosa pátria dos semi-humanos foi um centro de evolução tecnológica e industrial por centenas de anos, bem como de prosperidade agrícola... Isso é, até ser invadida e dominada pela ameaça dos Eclipsitas.",
  str_dispatch_book_chaptercont_2000_2 = "“Os sistemas de ventilação e iluminação sofreram danos irreparáveis no começo da invasão. O cheiro de pólvora não saia de jeito nenhum, mas também não ajudava em nada para disfarçar o mau cheiro do sangue no ar. Os cruéis Eclipsitas, cujos corpos giravam e se contorciam na fumaça, matavam indiscriminadamente sem hesitação nem remorso. Não faziam prisioneiros e matavam todos os habitantes que capturavam sem exceção, como feras famintas.\nAlguns de nós tentaram lutar contra eles e tiraram uma criança das garras de um bando de Eclipsitas... Apenas para caírem na fuga e serem vítimas de uma enxurrada de garras e uivos de monstros. Perdemos contato com as linhas de frente poucas horas antes... Temíamos que o pior tivesse acontecido a eles. Nossa única esperança... eram aqueles que tinham fugido pelos caminhos subterrâneos. Nós oramos para que o destino mantivesse a criança em segurança... Nunca vou esquecer o que vi aquele dia: nosso povo caído nas ruas ou esmagado sob ruínas, a luz de seus olhos apagada há muito tempo... Montanhas de corpos em um cenário marcado por fumaça, fogo e gritos de agonia...\nNossa linda pátria foi transformada em um inferno vivo. Esses Eclipsitas imundos e assassinos... Vão pagar pelos pecados que cometeram!”\nTrecho extraído de um diário encontrado no Território Secreto, pela Equipe de Expedição da Illumina.",
  str_dispatch_book_chaptercont_2000_3 = "“De acordo com os anciãos, devemos ser a última onda de guerreiros a entrar na caverna. Eu os chamo de “anciãos”, mas são apenas um grupo de semi-humanos jovens. Os verdadeiros anciãos, que viveram vidas longas, há muito tempo se foram na luta contra a ameaça dos Eclipsitas.\nNós preparamos nossos corações para o pior depois de receber o chamado de emergência dos nossos amigos, mas quando vimos nossa grande caverna reduzida a uma pilha de escombros e ruínas... quando vimos as montanhas de corpos dos nossos camaradas semi-humanos... Nesse cenário infernal, nós perdemos a vontade de lutar. Felizmente, as palavras boas e reconfortantes dos anciãos nos levantaram de novo. Embora eles pareçam apenas alguns anos mais jovens que nós, eu...\nMalditos Eclipsitas, vão pagar pelo mal que causaram! Cem cabeças deles para cada semi-humano caído! Nenhum de nós jamais esquecerá os rostos dos nossos camaradas que tiveram as vidas roubadas... Nós perdemos nossas casas, nossas vidas... O que mais podem tirar de nós? Não existe outro refúgio para nós, semi-humanos, nesta terra? Não seria melhor enfrentarmos nossos invasores uma última vez e morrermos como nossos compatriotas, empilhados um em cima do outro, não importa a idade ou posição? Eles pagaram o preço final pela defesa do nosso lar, então agora é nossa vez de fazer o mesmo. Que o sangue e os corpos dos Eclipsitas sejam a terra que cobre nossos túmulos! Vamos lutar pela nossa casa, até que o último de nós caia...”\nTrecho do diário de um Aurorian metade semi-humano sem-nome.",
  str_dispatch_book_chaptercont_2000_4 = "Quando penso nos ossos secos que atulhavam as ruínas... Ou naqueles corajosos soldados Illumina que nunca soltaram as armas, nem quando seus olhos perdiam a luz da vida... Na época, a única coisa que eu pensava era abandonar aquela expedição maldita. \nA extinção dos semi-humanos aconteceu há centenas de anos, e os Eclipsitas tornaram-se os mestres da caverna. Esse fato não muda, não importa como nós, forasteiros, o chamemos. Mais do que isso, os ataques dos Eclipsitas a todos os outros assentamentos pararam depois que invadiram a pátria dos semi-humanos. Parece que estão satisfeitos em viver e serem deixados em paz nas profundezas do Território Secreto. Nenhum de nós realmente sabe o que eles fazem lá... \nPor isso que coube a nós descobrir. \nNo começo, as Equipes de Expedição de Illumina irradiavam coragem e otimismo, na esperança de que seriam eles quem dariam um golpe fatal nos Eclipsitas. Eles pensavam em proteger aqueles que amavam e a Federação Illumina... Mas a realidade logo mostrou para todos que o otimismo era tolice. Com o tempo, incontáveis membros das Equipes de Expedição ou foram mortos pelos Eclipsitas da caverna ou se perderam nas profundezas do Território Secreto. Em alguns casos, equipes inteiras desapareciam e nunca mais eram vistas. Com o tempo, as expedições começaram a ser contestadas. Todavia, os líderes da Illumina insistiam nas expedições, a fim de “descobrir a verdade”. Essa motivação simples, nascida da crença da Illumina, resultou na perda de incontáveis soldados corajosos, bem como em uma vida de tristeza para as famílias e amados deles. \nEventualmente, tornou-se comum haver desertores nas linhas de frente, e nós estávamos entre eles. Abandonamos nossos companheiros caídos, ignoramos nossas ordens e fugimos do Território Secreto intactos. Presumivelmente, nós fomos classificados como “Desaparecidos em combate” nos registros públicos de Illumina, mas nossos registros militares muito provavelmente nos listam como desertores. O que aconteceu com nossos parentes? Eles foram punidos pela nossa covardia? Receio que nunca saberemos, porque não podemos retornar para a Federação. Não temos escolha senão passar o resto da vida nesse deserto. \nEmbora eu sinta falta da minha família e da minha cidade natal de vez em quando, minha vontade de sobreviver é mais forte que minha saudade de casa. No fim do dia, ainda estamos vivos, e temos um deserto inteiro para chamar de lar agora. De certo modo, acho que saber quando desistir é um tipo de sabedoria em si. Se fôssemos tão devotos à nossa pátria quanto os semi-humanos foram antigamente, só teríamos duas opções: explorar o Território Secreto e sermos mortos pelos Eclipsitas, ou violarmos ordens e retornarmos para casa, sermos julgados e executados. De qualquer jeito, a morte era o único resultado. \nNão tivemos nenhuma notícia da exploração do Território Secreto pela Federação Illumina recentemente. Muito provavelmente eles desistiram, já que as outras cidades-Estado também não deram sinal de que continuariam com seus esforços. Parece que o mundo todo enfim reconheceu o Território Secreto como uma causa perdida, um lugar sob o controle dos Eclipsitas e ninguém mais. E isso é uma coisa boa pra caramba, eu acho. O Território Secreto e a Illumina, os semi-humanos e os Eclipsitas. Estamos cansados deles todos. \nRelato em primeira mão de um membro da Rediesel Wrench da primeira geração, que quer ser mantido em anonimato.",
  str_dispatch_book_chaptercont_3000_1 = "Minha próxima missão era ir para _____, e acabar com os traidores que estavam entrincheirados lá. O pagamento era incrível, e eu tentei economizar o máximo que pude dele, mas calcular a alimentação e outras despesas era um saco... Mas se eu não fizesse umas horas extras, nunca teria minha própria equipe de mercenários, né? Continuaríamos lutando pelas migalhas dos peixes maiores pelo resto da vida, como eu estava fazendo na época... Então disse a mim mesmo para continuar economizando! Eu ainda não tinha pensado num nome pra minha equipe na época, mas não tinha pressa pra isso. \nO cenário de _____ era muito mais complicado do que eu pensei. De acordo com as mensagens, tínhamos que seguir outra equipe de mercenários por um caminho subterrâneo na surdina... Mas não sabíamos como era esse caminho, e como era uma operação furtiva não podíamos usar armas. Fiquei um pouco preocupado com a missão. Se qualquer armadilha ou emboscada estivesse nos esperando naquela passagem, estaríamos ferrados. Felizmente, conseguimos atravessar sem problemas. Eu até vi um lagarto rastejando perto do meu pé. \nDepois que atravessamos a passagem, chegamos ao interior de _____. Aquela passagem deserta nos levou direto ao esconderijo do inimigo. O lugar era uma bagunça completa, não muito diferente de qualquer campo de batalha. Nós presumimos que ou o inimigo não teve tempo para limpar ou não quis. O chão era uma pilha de lixo, roupas sujas e restos de comida. Pareciam completamente despreparados para um ataque. \nNós acabamos com eles, rápido e fácil, tudo de acordo com o plano... Mas acho que gastamos mais munição do que precisávamos. Usamos quatro ou cinco pacotes de explosivos, tudo do nosso próprio estoque, mas meus rapazes me garantiram que podíamos comprar explosivos de verdade, de qualidade militar, com nosso pagamento, se fizéssemos o trabalho direito. Estavam sendo otimistas, claro, mas eu queria mesmo fazer mais grana. \nOh, e por fim eu escolhi um nome para minha equipe. Eu nos chamei de Esquadrão Bombástico, porque atacamos que nem dinamite, e a explosão é sempre maior que o esperado!",
  str_dispatch_book_chaptercont_3000_2 = "O pagamento que recebemos pelo último trabalho foi uma MIXARIA se comparado ao que esperávamos... Mas não podíamos fazer nada. Quando fomos até o empregador receber o pagamento, fomos emboscados por um bando de Eclipsitas, e o empregador foi devorado. Só pudemos nos esconder até os Eclipsitas irem embora, depois procurar no que restou dele pelo nosso pagamento, bem como nas ruínas. Achamos uns trocados nos bolsos, mas foi só isso. Não dava nem pra negociar com o empregador no estado atual dele, entende? \nEntão, nós sentamos pra discutir qual trabalho pegar em seguida. Pode imaginar isso? Agora nós tínhamos opções! Havia dois trabalhos para pegarmos, um era de _____, e era para matar o membro de _____. O outro era de _____, e também era um trabalho para matar um membro de _____. Achamos engraçado que _____ e _____ por coincidência entraram em contato com a gente na mesma hora com esse tipo de trabalho. Então, tínhamos que escolher: matar _____ ou _____? \nPensei em matarmos _____ para _____, já que eu não suporto _____. Eles só sabem tagarelar sobre igualdade e a lei, mas vendem a vida do próprio povo na surdina. Se eram tão justos assim, por que nós não pudemos ir para o subterrâneo como refugiados? Onde eles conseguem os recursos, que não podem dividir nada conosco? E então tem o chefe deles... Se todo mundo é igual perante a lei, por que ele não usa as mesmas roupas que os soldados normais, ou usa as mesmas armas, ou dorme no mesmo lugar? \nMas um dos meus rapazes acha que matar _____ para _____ seria difícil demais. Afinal, as defesas de _____ são quase impenetráveis. Seja como for, sob uma perspectiva de dificuldade, não seria mais fácil matar _____ para _____? Quer dizer, _____ está em _____, de todos os lugares! \n“Tanto faz”, eu disse. “Escolha um logo, não importa, contanto que paguem, não é?” Eu só tenho que continuar trabalhando duro se quiser estabelecer meu próprio esquadrão de mercenários... Mas eu não sou muito fã da ideia de arriscar meu pescoço por _____, aquele fanático pomposo.",
  str_dispatch_book_chaptercont_3000_3 = "Fosse matar _____ para _____, ou matar _____ para _____, no fim escolhemos não fazer nenhum. Depois de conversar com os outros, decidimos que as defesas que cercavam tanto _____ quanto _____ eram fortes demais para serem rompidas. Íamos precisar de uma marreta do tamanho de uma cidade ou de uma perfuradora gigante, se quiséssemos fazer o trabalho. Estávamos falidos a ponto de passar fome. Onde íamos conseguir a munição para um ataque desses, quando mal tínhamos espadas para dividir entre a gente? Era uma causa perdida para nossa equipe, e ver nosso dinheiro sumir por nada seria pior... \nBem, ao recusar dois trabalhos grandes desses, nossos fundos começaram a ficar escassos, pra dizer o mínimo. Esqueça isso de estabelecer minha equipe. Estávamos sofrendo só pra comprar comida o bastante pra não passar fome. Felizmente, conseguimos uns trabalhos domésticos que ajudaram a sobreviver. Quem pode dizer não a três refeições por dia e um teto pra dormir? O único problema era que meus rapazes não estavam muito animados em limpar a casa e o jardim de outras pessoas. A vergonha fez muito mal para o moral. Eu, por outro lado, achei que isso era MUITO melhor do que ser um mercenário assassino maluco! Isso quer dizer que não sirvo pra ser um soldado do destino, então? \nEu estava limpando um quarto enquanto o inquilino não estava. Dava pra notar que era o quarto de alguma garotinha fofa. A cama era macia como uma nuvem, tinha um grande cobertor rosa e um ursinho de pelúcia em cima. Uma das orelhas do ursinho estava rasgada, então eu imaginei que podia consertar pra ela quando terminasse de limpar, já que não tinha mais nada pra fazer. Ao ver como eu era ágil e hábil com a linha e a agulha, eu me senti menos como um mercenário do que eu já havia sentido antes. \nMas todo mundo na minha equipe era bom com costura. Nossas roupas geralmente se rasgavam nas missões e não podíamos comprar novas, então ficamos bons com costura pra manter as roupas inteiras. Bem, se não prestávamos como mercenários, podíamos começar um negócio de costura. Podíamos fazer muito dinheiro assim, e era mais seguro. \nDezembro",
  str_dispatch_book_chaptercont_3000_4 = "Não escrevo no meu diário desde que desisti de ser mercenário. Abri-lo de novo me faz sentir nostalgia. \nMesmo assim, fico feliz por ter saído daquela vida. No final, eu não nasci pra lutar ou proteger armas e munições, então, naturalmente, eu nunca conseguiria terminar aquelas missões perigosas de antes. Eu queria estabelecer minha própria equipe de mercenários, mas nunca fiz dinheiro o bastante pra isso, e no final... nós fomos todos para _____, limpar casas e ganhar dinheiro, em vez disso. Era a coisa mais vergonhosa no mundo, pra gente. \nPor mais vergonhoso que fosse, descobrimos logo que ter um trabalho que garantia comida e abrigo não era tão ruim, afinal de contas. Eu até mesmo costurei o ursinho de pelúcia de uma menina uma vez, e descobri que tinha jeito com costura. Eu disse para _____ que minha equipe e eu tínhamos muito talento com linha e agulha. Naquela época, eu senti mais orgulho de mim e da minha equipe do que como mercenários. \nDepois, uma coisa incrível aconteceu! _____ achou tão incrível as nossas habilidades com costura, que ganhamos permissão para abrir nossa própria alfaiataria! Nessa hora, paramos de ser um bando de mercenários nômades e nos tornamos orgulhosos membros da alfaiataria de alta qualidade de _____! Até mesmo o nome dela é ótimo: Uniformes Bombásticos. Íamos usar um nome parecido para nossa equipe de mercenários, mas fica melhor ainda na loja. \nO negócio dos Uniformes Bombásticos estava... bombando, por assim dizer. As pessoas de _____ e _____ nos procuram sempre que precisam de alguma coisa com as roupas. Eu ainda não gosto muito de _____, então sempre costuro os botões apertados, pra deixar desconfortável. No final, eles gostam assim, dizem que ajuda a manter a barriga dos soldados alinhadas. Eu só digo que, se seu povo se preocupa tanto com justiça e igualdade, como seus soldados terminam tão gordos? \nSeja como for, a vida de alfaiate é muito melhor que a de mercenário, e meus companheiros concordam. Um deles está economizando pra casar com o amor da sua vida, e eu também estou pensando em começar uma família. Também estamos pensando em começar nossa marca de aparatos militares: Fardas Bombásticas. Algum dia, tanto _____ quanto _____ vão implorar pra vestir os soldados com a nossa marca! \nCerto, já é o bastante por hoje. Escrevo mais quando tiver tempo. A loja está com pedidos até o teto, mas mais trabalho quer dizer mais dinheiro! Haha!",
  str_dispatch_book_chaptercont_4000_1 = "Escritura: \nE ela disse: “A Verdade não pode ser vista com nossos olhos, mas a Verdade pode me ver com os próprios olhos dela. Quando a Verdade olha para mim, ouço o chamado dela e sei onde ela está.” \n“Não, eu rejeito a Verdade dela. Ela é o mal encarnado: o sorriso dela é mais sinistro que o encarar de um Eclipsita, a beleza dela é mais terrível do que as tragédias do mundo.” \nEla disse: “Não posso negá-la, pois não posso negar a Verdade.” Ela se virou, e o vestido vermelho dela dançou consigo. Aquele vestido era especial. Ele se movia como a água fluindo. Ela se virou de novo, e o vestido virou com ela, envolvendo-a, envolvendo-me. \n“Não, eu rejeito a Verdade dela mais uma vez.” O vestido vermelho se moveu como se estivesse vivo, varrendo o chão, prendendo-se na minha pele. Ela girou num círculo, o vestido dela se espalhando como neve ao vento: caindo no chão, caindo em mim, caindo nos meus lábios. Um estranho aroma soprou no meu nariz, como o sangue fluindo nas minhas veias. \nEla disse: “Assim eu lhe dou as boas-vindas. Espero que goste.” Os cílios dela pendiam como cortinas, a voz dela era como o som da natureza. Ela olhou para mim. \n“Não, eu rejeito a Verdade dela novamente.” O sangue fluiu do corpo dela: ele formou as peças íntimas dela, depois o vestido, depois o carpete vermelho sob os pés dela. Na cabeça, formou uma coroa de cor vermelha como sangue. \nO olhar dela ainda estava sobre mim, todos os olhos dela focados em mim: os olhos no corpo dela me encaravam, os olhos nas mãos dela me encaravam, os olhos no busto dela me encaravam, os olhos nos joelhos dela me encaravam, os olhos nas costas dela me encaravam, os olhos no topo da cabeça dela me encaravam. Ela me viu. Eu fui visto por ela. Examinado por ela. Examinado pela Verdade. \n“Não, eu rejeito a Verdade dela pela quarta vez.” Mas minha negação não significava nada. Ela usou os olhos no corpo dela para me ver, e os olhos que apareceram no meu corpo me viram também. Os olhos nas minhas mãos me encaravam, os olhos nas minhas costas me encaravam, os olhos no topo da minha cabeça me encaravam. A Verdade fez olhos aparecerem no meu corpo, e a partir daquele momento, não importa onde eu estivesse ou o que fizesse... a Verdade estava sempre observando. \n“A Verdade apareceu em seu corpo, e ela estará sempre te observando.” \nFoi o que ela me disse.",
  str_dispatch_book_chaptercont_4000_2 = "A Verdade é tudo ao nosso redor: em cada rio que corre, em cada planície verde, nos céus escuros e nas noites sem-fim. \nNos brotos e galhos de cada árvore e em cada semente, flor e fruto. Em cada caminho enlameado e do lado de toda cachoeira seca. \nEstá no ar e diante de nossos olhos, em volta de nossa pele e debaixo de nossos pés. Está em toda respiração que entra nos nossos pulmões e em todos os raios de sol que entram nas nossas retinas. Ela anda atrás de nós o tempo todo, pincelando levemente nossos corpos. \nEstá nos nossos lábios, dentes, boca, garganta e estômago. Ela é digerida, absorvida pelo nosso corpo e flui pelo nosso sangue. \nEla é transmitida pelos nossos nervos para cada canto dos nossos corpos: para o fígado, a vesícula, o intestino grosso e delgado, o pâncreas, o baço e os rins. Ela flui pelos nossos ossos: pelos fêmures, pelas tíbias e fíbulas, pelos calcanhares e dedos. \nA dor é como chutar com um dedo no pé de uma mesa. \nEla é transmitida pelos nervos para o centro dos nossos corpos: para o coração, a traqueia, a base da língua, as cavidades nasais, os nervos ópticos, o tronco encefálico e o cérebro. Do crânio, ela passa pela coluna cervical, para as omoplatas, os cotovelos, os pulsos e os dedos. \nA dor é como ter uma unha arrancada. \nEla é transmitida pelos nervos até o recesso mais profundo dos nossos corpos: pela medula óssea, o cordão umbilical, a cavidade abdominal, até o crânio da criança no ventre. Uma semente cresce na mente do bebê, nutrida pelos pensamentos dele, e floresce em uma linda flor, suas pétalas pingando cores divinas. \nPensamentos do divino se despedaçam em incontáveis pedaços, e o bebê entra no mundo encharcado de divindade. O mundo que ele encontra é um deserto vasto e desolado. Cada choro seu produz um novo broto de flor, e cada lágrima que derrama colore o mundo em volta com sua divindade. Enquanto a criança continua chorando, os céus também derramam lágrimas de divindade. As flores crescem ao redor do corpo da criança, e o deserto se torna um mar sagrado de flores. \nA Verdade é tudo ao nosso redor.",
  str_dispatch_book_chaptercont_4000_3 = "Como posso descrever esta sensação? \nÉ viscosa, lamacenta e toda misturada. Eu coloco minha mão nela. Ela parece escorregadia e lisa, com matéria sólida suspensa dela. Eu consigo apertar, consigo amassar e consigo misturar. Não consigo me misturar com ela, mas ela se mantém firmemente presa em mim. Seu calor se espalha até meus ombros. \nÉ uma criatura viva. \nÉ carne e ossos e tendões, cheia de nutrientes, e pode ser preparada de muitas maneiras: pode ser frita, assada, grelhada, cozida e ensopada. Quando comprei, o pacote dizia que o sabor ficava melhor se cozida viva. \nMas como cortar a carne? A cada corte, a massa viscosa e pegajosa desvia da lâmina com esperteza, deslizando pelas laterais. Eu a seguro, miro na parte mais grossa e deslizo a lâmina nela. A substância mucosa na superfície se fecha na lâmina como uma boca gigante, recusando-se a me deixar cortá-la. \nA água está fervendo; eu já perdi muito tempo. Então a coloco na panela, inteira. Ela desliza devagar pela lateral da panela, até a água borbulhante. Estou imaginando coisas? A carne parece estar rindo para mim, torcendo seu corpo e trincando seus dentes recortados conforme suas membranas viscosas se dissolvem na água instantaneamente. \nEla faz um barulho, com certeza está rindo. Rindo de mim de dentro da panela fervente, olhando para mim de dentro da panela fervente. Ela cozinha e solta vapor, e enche o cômodo com um fedor. Um fedor pútrido como de peixe que gruda nas minhas narinas e queima dentro do meu cérebro. O fedor esmagador, de fazer se encolher, arranha o interior do meu crânio, como unhas em uma lousa. \nRaspando e rindo, o tempo todo. De repente, ela fala comigo: “Coma-me. Devore-me, um pedaço de cada vez. Saboreie-me. Saboreie meu ser viscoso e pegajoso. Saboreie-me, que eu desmancho na sua boca. Sinta-me deslizar pela sua garganta até seu estômago. Deixe meu sabor se espalhar pelo seu corpo todo. Permita-nos ser um só sabor, uma matéria, uma existência. \nSaboreie a Verdade, e depois se torne a Verdade. \nQue mais e mais pessoas nos saboreiem, que eles conheçam a Verdade também.",
  str_dispatch_book_chaptercont_4000_4 = "O dia da queda nunca virá. Então não se preocupe. Fique do lado dela e aproveite as belezas da vida à vontade. \nRia às gargalhadas, observe seu amor e o sorriso dela, que nunca se desbota. Segure-a, dance e gire com ela, cada segundo de cada dia. Coma uns doces e corra no sol, e veja ele descer pelo ar. Imagine seu futuro, imagine a criança que ela vai dar para você. \nChore de alegria, chore na chuva, e deixe suas lágrimas se misturarem com as do céu. O dia que você teme nunca chegará, e suas lágrimas algum dia vão secar. E quando secarem, o sorriso dela vai brilhar mais uma vez. A chuva vai voltar para o mar e o céu, e vai ficar onde é o lugar dela. \nO dia da queda nunca virá. \nCorra e siga ela enquanto seu coração mandar, deixe-se levar pela alegria, e cante. Segure-a nos braços e cavalgue na direção do pôr do sol, e veja o que o amor trará. Sem ninguém esperando e nenhum objetivo a seguir, você cavalga no seu próprio ritmo. Galope a toda velocidade e aproveite a sensação do vento correndo pelo seu rosto. Corra até os fins do mundo sem parar. Nada pode impedir o ritmo dos seus passos. O sol sempre nasce de novo, e o amanhã sempre chega. \nO dia da queda nunca virá. \nE na escuridão, sob a suave luz da lua, os olhos dela brilham mais luzentes que a luz das estrelas. Conte-as no céu, observe a lua derreter e diminuir, e aproveite a tranquilidade da noite. A graciosidade dela sob a luz da lua deixa os corpos celestes acima encabulados. O sorriso crescente dela, os olhos brilhantes dela, brilham com o calor do amor. Com cabelos negros como a noite e voz como um rouxinol, ela sussurra no seu ouvido: “Eu ficarei sempre com você, então fique do meu lado para sempre, meu amor.” \nO dia da queda nunca virá. Definitivamente nunca virá. \nEla sorri com uma beleza nunca vista nesse mundo, seu olhar brilhante e profundo. \n“Esse dia nunca virá,” ela diz “pois eu ficarei sempre do seu lado.”",
  str_dispatch_book_chaptercont_5000_1 = "Certo, crianças, hoje vamos aprender como preparar vermes de areia, já que dá pra achar esses verminhos em todo o Deserto Rediesel. Mas não pensem que será fácil só porque eles estão por toda parte! Primeiro de tudo, precisamos dos vermes de tamanho certo: 20 cm é o número mágico! Menos que isso e é melhor jogar eles de volta e deixar comerem mais areia pra engordar. Pois bem, para preparar um verme de areia, você o segura firme pelo meio, segura a cabeça e a puxa junto com a bolsa de lama. Não precisa de faca nem tesoura! Depois, pegue um palito (ou use o dedo), e o enfie onde a cabeça ficava. A lama que ficava dentro dele vai ser espremida pra fora (pule esta etapa se você quiser a experiência do verme de areia DE VERDADE!). \nIsso é tudo que precisa para preparar um verme de areia (ou quaisquer outros vermes de areia ressecados), simples assim! Se você estiver com muita fome, pode assar ele como for, mas tente achar um palito em vez de usar seu dedo. Oh, o número de cartas que recebi dizendo coisas como “Tio Johnny, eu segui suas instruções, mas acidentalmente assei meu dedo também! O que eu faço?!” Bem, carne é carne, não é? Seu dedo já está assado, seu cabeça de vento. Aproveite!\nAgora, se você tiver sorte de ter uma panela, não apenas você é mais sortudo que 90% dos residentes do Deserto Rediesel, mas provavelmente come bem também! Aqueça um pouco de óleo na redondinha, jogue os vermes de areia limpos nela e frite-os com um pouco de sal até ficarem amarelos e exalarem a fragrância distinta deles. Jogue algumas pimentas picantes defumadas, um punhado de grilos bem fritos, uma colher de sopa de molho picante, um quarto de colher de pó de alho, orégano e cinco colheres de creme azedo, NESSA ORDEM! Depois, coloque água e deixe ferver por cerca de 20 minutos. Sirva quente, cubra com cebolinha e salsinha e BÚM! A sopa rápida e gostosa de vermes de areia do Tio Johnny! Se você não tiver algum ingrediente, não se preocupe! Adicione o que tiver em mãos pra dar seu toque!\nNa próxima aula, o Tio Johnny vai ensinar a assar um CAMELO INTEIRO! Lembrem-se de ter uma panela grande o bastante pra caber um camelo parado. Não sabe onde encontrar uma? Tem um monte de malucos pelo deserto, que assam pessoas para o jantar. Pergunte pra eles!",
  str_dispatch_book_chaptercont_5000_2 = "Se você pôr os pés nesse deserto, não tem como evitar essa lanchonete. Dizem que o dono é próximo de Sinsa, então sugiro que você fique de cabeça baixa se estiver aqui. Não vá agindo como se fosse durão perto desses caras. Mesmo sem a Rediesel Wrench por perto, as torretas de segurança podem te deixar mais furado que uma peneira, antes de você conseguir pedir desculpas. Ora essa, uma ou duas semanas antes de começar a escrever este livro, eu vi um grupo de marginais cabeças quentes tentarem causar problemas lá. O que aconteceu? Todos eles foram atingidos por balas, todas no alvo em menos de dois minutos! Seja educado, se não tiver coragem de arrumar uma briga de verdade.\nAgora, o suco que eles fazem aqui é realmente único. Nos outros lugares, eles misturam agave com cacto, jogam umas folhas e deixam apodrecendo num barril. O produto final é 70% desse líquido, 20% de extrato de Rediesel (dizem que é o único jeito de bebê-lo!) e 10% de areia. Isso é suco de urina, não importa como você chame! Mas esses caras... eles são incríveis. Usam agave azul DE VERDADE (vai saber onde eles conseguem) e mais nada, e o processo é legítimo! Eles deixam ferver num forno por mais de cinco dias a 370° C para soltar o caldo natural, depois usam uma chave inglesa ou martelo para quebrar a planta e a trituram num triturador de pedra. Depois disso, deixam em barris de carvalho para envelhecer (me pergunto: como será a aparência de um carvalho?). Quando você despeja no copo, ele fica dourado ou vermelho acastanhado, um colírio para os olhos! Coloque uma pitada de sal do Mar do Norte, tome um pouco e você vai sentir que engoliu o sol inteiro! Não consigo recomendar isso o bastante! O Anejo é o que você mais quer!\nAlém disso, parece que eles colocaram um outro suco novo no menu recentemente. É feito com limão, gengibre, um pouco de amor e muito gelo! Acho que se chama “mula” ou coisa assim. Seja como for, faça um favor a si mesmo e experimente se estiver na área!",
  str_dispatch_book_chaptercont_5000_3 = "Quando o Tio Johnny era só um rapazinho, eu tive a brilhante ideia de cruzar o deserto todo a pé (uma ideia idiota, eu sei, mas o que eu posso fazer se caí de cabeça uma ou duas vezes quando era criança?). Foi por causa desse ato impensado que eu quase morri lá. Não fosse a Caravana do Camelo Itinerante, que passou na hora e me desenterrou da areia, eu teria acabado frito no sol! Não só isso, mas eu acabei provando uma das melhores carnes de camelo do mundo, então, no final, tudo acabou bem! O camelo foi preparado pelo próprio líder da caravana, e eu estava com fome o bastante pra comer tudo. Como podia recusar? \nEle me serviu uma fatia de carne que tinha acabado de assar em um prato. Estava perfeitamente ao ponto por fora, e ainda dava pra ouvir a gordura do camelo estalar e estourar. Parecia mais grossa e fibrosa do que bife, mas adivinha só: a fatia derretia na minha boca que nem manteiga! No segundo que você morde um pedaço de carne, ela praticamente desliza pela sua garganta. E o aroma? Vou lhe contar, me pegou que nem um coice de camelo na cara! A melhor parte? Esse tipo de carne pura e de alta qualidade não precisava de tempero nenhum. Eles me serviram PURA! Ela era boa o bastante pra te fazer querer sair correndo, pelado, pelo deserto por mais (mas acho que as outras pessoas do deserto não viriam isso com bons olhos...). \nO camelo que comemos foi escolhido por ninguém mais, ninguém menos que o excelentíssimo líder da caravana. Todos os camelos que tinham eram gordos e fortes, então demorou para escolhermos o perfeito. “Oh, aquele com a capa bonita come demais, vamos escolhê-lo!” “Oh, aquele anda engraçado por causa das pernas compridas, vamos ficar com ele!” “Ei, esse é só carne e osso! Não deve ter muito tempo de vida, aposto!” \nNo fim, escolhemos o camelo mais gordo da cáfila. O líder da caravana nos disse que o calor seria demais pra ele, então ele achou que podíamos usá-lo antes dele ir dessa pra melhor. Eu não vi nenhum problema de saúde no camelo, mas a caravana me garantiu que estava tudo bem e que o camelo estava perfeitamente bom para comer. \nPassamos a noite toda comendo o camelo todo. Para a experiência completa, combinamos com queijo feito de leite de camela e um pouco de areia. Foi a melhor refeição que eu comi em muito tempo, e isso não é pouca coisa! Depois de algumas bebidas, perguntei para o líder da caravana: “Você não se sente mal, às vezes, por matar um camelo bom desses?” Ele respondeu: “Por que me sentiria mal? Não dá pra conseguir camelos novos se você não se livrar dos velhos! Além disso...” Ele tomou um longo gole de leite de camela “essa caravana é do meu irmão, e os camelos também! Coma à vontade e pare de se preocupar!” \nSeja como for, vegetariano ou não, você não quer deixar de provar esse “fruto” do deserto! Realmente, pense que é uma fruta, se precisar, e experimente! Você não vai se arrepender!",
  str_dispatch_book_chaptercont_5000_4 = "Todo mundo sabe como fazer Lámen Infernal, não sabe? \nFerva o macarrão e separe-o. Despeje quatro tigelas de água na panela, adicione caldo de costela de porco e molho extra picante, depois coloque os ovos ou qualquer acompanhamento que você quiser. Pronto! (Não precisam mais consultar a receita do Tio Johnny!) \nMas, hoje, quero falar de um prato que vai muito além dessa simples receita. O lámen mais picante, ardente, queimante, derretedor de cérebro que já comi na vida: a versão do Lámen Infernal do Restaurante de Lámen Esbugalha Olho! \nO Lámen Infernal deles vem com um copo de água e uma garrafa pequena de leite. Isso já diz tudo, né? Quando você pedir, coloque um pouco de macarrão e carne na colher, junto de um pouco de caldo e coma. Algumas pessoas disseram que tiveram febre e alucinações depois de só um bocado pequeno disso! \nA primeira coisa que percebi depois da primeira mordida foi uma secura extrema na boca, junto de dores mais intensas. De repente, achei que um deserto estava aparecendo diante dos meus olhos! Senti como se fosse abandonado no lugar mais quente e seco do planeta. A terra era rachada e árida, e o sol ficava cada vez maior. Não sobrou uma gota de umidade no meu corpo e minha pele começou a lascar e soltar dos meus ossos. Minha garganta ficou totalmente ressecada e eu quase cedi ao desejo de rasgar meu próprio pescoço, então virei desesperadamente o copo de água que me deram. \nO choque repentino da água no meu sistema me deixou tão tonto que eu quase desmaiei, mas a cena na minha frente mudou de novo! Dessa vez, eu vi um oásis verdejante cercado por uma cortina de névoa, com lindos homens e mulheres brincando e nadando dentro dele (se minha boca e garganta não estivessem me matando, eu teria assobiado para eles!). Mesmo assim, eles me viram, me puxaram para o fresco oásis e, bem quando eu estava me aconchegando... a líder do grupo me agarrou e me jogou de volta na areia! Infelizmente, o copo de água não deu certo e a ardência de antes voltou com força. A areia embaixo de mim virou lava, e eu afundava cada vez mais nela, até que a única coisa que sobrou foram meus restos carbonizados, e então... Nada. \nEssa foi toda a magnitude do poder do lámen. Eu bebi o copo de leite depois e, como mágica, meu corpo carbonizado se tornou carne e sangue de novo, e o vazio desapareceu da frente dos meus olhos. O calor relaxante que eu senti naquela hora não foi muito diferente de um mergulho demorado em águas termais (que será o tema do nosso próximo registro). \nEssa foi minha experiência com o Lámen Infernal do Restaurante de Lámen Esbugalha Olho! \nCuriosamente, eu perguntei para o chefe sobre o método de preparação, e a resposta foi simples e chocante: foi feito exatamente do jeito que eu descrevi no começo! Quanto ao motivo de estar tão picante, o chefe disse que esse efeito foi conseguido com um tempero muito especial. \nQual tempero, você pergunta? É segredo deles, como eu vou saber?!",
  str_dispatch_book_chaptercont_5000_5 = "Localizado nas margens do Lago Esmeralda, no Deserto Rediesel, está um lugarzinho chamado Aldeia da Colheita, onde deliciosas receitas e pratos de todo o mundo são reunidos, e a cada três anos acontece um festival chamado de “Extravagância da Comilança Infinita”. Os pratos e ingredientes da maior qualidade de Lumópolis, Illumina, Northland e até mesmo do Oriente podem ser encontrados aqui durante os festivais. Arroz de arenito, guisado de carneiro e rolinhos de ovos são apenas alguns dos deleites que você encontra nesse paraíso da culinária! Acho que todo mundo deveria vir a este evento ao menos uma vez na vida. Diabos, eu tinha só três anos de idade quando vim pela primeira vez e tive que roubar e trapacear só para experimentar todas as delícias do lugar! Então, você acha que eu devia ter sido responsável e merecido minha comida como um homem de verdade? Que parte de “eu tinha só três anos de idade” você não entendeu?! \n\nLembro daquele ano como se fosse ontem: eu estava segurando uma lagarta assada em uma mão, um Petisco Crocante na outra e mastigando uns doces crocantes quando, de repente, senti esse aroma leve e misterioso. Eu o segui até uma barraca caindo de velha. O proprietário era um homem jovem de um braço só. Não lembro exatamente da aparência dele, mas lembro que parecia muito jovem. O que eu nunca vou esquecer, no entanto, era da comida que ele estava vendendo: tendões de caranguejo real. \n\nA carne de caranguejo era clara como gelo, com um risco vermelho correndo de um lado a outro.  Parecia meio crua, pelo jeito que foi servida! Mas quando eu mordi, uma sensação estranha e turbulenta tomou conta de mim. Foi como se uma doce e salgada onda do oceano caísse sobre mim. Foi uma sensação que eu, em toda minha sabedoria, nunca tinha experimentado antes: o mar. \n\nO dono da barraca virou pra mim e disse: “Essa é a receita da minha vida.” \n\nCerto, crianças, hora do Tio Johnny compartilhar um pouco de sabedoria do mundo real com seus leitores mais jovens. Existem profissionais no mundo que atendem pelo nome de “caçadores de comida”. Esses caras perseguem o ápice da culinária por toda a vida, caçando e esquadrinhando o mundo todo pelos ingredientes mais raros, só para preencher o que chamam de “receita da vida” deles. Esse cara não era exceção. Ele passou um ano todo sozinho no mar só para pegar o caranguejo rei perfeito, depois o cozinhou em água do mar que pegou na fossa mais profunda do oceano e temperou com o sal marinho mais puro. Isso foi o que tornou os tendões de caranguejo real dele tão deliciosos! \n\nEu nunca mais vi aquele homem de um braço só. Talvez ele esteja procurando algo nas profundezas das florestas ou talvez na montanha mais alta, tentando capturar outro animal raro? Pessoalmente, não acho que um caçador de comida se satisfaça com apenas uma receita da vida. Uma dúzia ou duas deve bastar, certo? \n\nO quê? Vocês querem saber se o Tio Johnny tem uma receita da vida? \n\nClaro que tenho, e é muito simples: ovos cozidos de verme de areia! Pegue alguns na areia e jogue-os na água fervente por exatos três minutos. Você terá os ovos de vermes de areia mais macios, brancos e saborosos que já provou! Simples, barato e conveniente pra caramba, já que dá pra achar os ovos dos bichos por toda parte!",
  str_dispatch_book_chaptercont_6000_1 = "“Srta. Blanc, pode nos contar mais sobre o Lago Espelho, a ‘Lágrima de Northland’?” \n“Claro! O Lago Espelho, conhecido como ‘Lágrima de Northland’, deve ser o lugar que mais representa Northland.”\n“Northland pode ter temperaturas congelantes ou quase isso o ano todo, mas a composição especial do Lago Espelho evita que ele congele. Assim, ele mantém sua linda aparência de espelho o tempo todo, com sua superfície sem ondas cor de jade colorindo a paisagem surreal de inverno de Northland.”\n“Quanto a sua criação, uma lenda diz que, há muitos anos, a família real de Northland viajou para lá. Inspirados pela beleza e pelo romance, eles pintaram em suas próprias mentes uma paisagem de beleza natural arrebatadora. Então, por meios mágicos que só eles conhecem, fizeram esse lago cristalino e as montanhas do entorno virarem realidade... Mas acho que a maioria das pessoas concorda que é só um lago de erosão glacial natural.”\nNa margem oeste, existe um campo de narcisos brancos, outra característica do esplendor natural do Lago Espelho. Porém, tenho que avisar que ninguém deve colocar os pés lá, porque foi a Senhora Nikinis, conhecida como O Espelho Geminos de Northland, quem plantou pessoalmente as flores, e ela gosta tanto delas como se fossem suas filhas. Em uma ocasião, alguns convidados desrespeitaram os avisos e foram colher umas flores como lembranças, mas acabaram sendo jogados nas águas congelantes do Lago Espelho pela própria Senhora Nikinis. *Risadinhas* Não é nada fácil pescar pessoas naquele lago, sabia?”\n“Então, para evitar ferimentos desnecessários, fiquem longe do campo de flores quando visitarem o Lago Espelho!”",
  str_dispatch_book_chaptercont_6000_2 = "A Floresta Barlavento é relativamente úmida o ano todo, com dias confortavelmente quentes e noites agradavelmente frescas. A floresta é cheia de vida e atividade, e é lar de uma infinidade de vida selvagem rara, bem como de árvores antigas lindas. Dizem que Monarca de Barlavento, o cedro mais famoso da floresta, vive há milhares de anos. \n\nEspere ser recebido por uma brisa agradável, ar fresco e animais amigos dos humanos que vivem na Floresta Cata-vento. Ela é uma área de férias ótima para todas as idades.\n\nOh, e se você escolher viajar para cá, lembre-se de se apresentar para Sylva, o guardião da floresta. Mas como ele passa a maior parte do tempo patrulhando o arvoredo e ajudando as criaturas, você pode falar com Leah, a representante dele na cidade vizinha, Holleton. A mesma cidade é lar de um restaurante famoso pelos guisados. Para mais informações, consulte o capítulo chamado “Recomendações de gourmet”, nesse livro.",
  str_dispatch_book_chaptercont_6000_3 = "Depois de atravessar os campos cobertos de neve de Northland, você pode encontrar descanso e conforto nas colinas da Pinha de Northland. Viajantes congelados e exaustos são recebidos com cabanas quentes, camas macias e sopa borbulhando. Por estar longe de ser plano, esse terreno único bloqueia os ventos glaciais do norte com muita eficiência. O clima é geralmente quente, até mesmo úmido, o que originou inúmeras aldeias dentro de suas colinas. \n\nNo passado distante, os primeiros colonos dessas colinas encontraram incontáveis cristais verdes no solo, brilhantes como esmeraldas. Depois de uma investigação mais profunda, descobriram que a área era rica desses cristais, e que alguns eram tão grandes quanto pessoas adultas! Eventualmente, eles fizeram uma descoberta ainda maior: as colinas eram, na verdade, cristais gigantes! Os anciãos entre os colonos chegaram à conclusão de que as colinas de cristais já foram parte de um cristal colossal, e que os deuses despedaçaram-no para formar essas terras maravilhosas. \n\nHoje em dia, os viajantes podem ver esses lindos cristais naturais pontilhando a paisagem em toda parte. No entanto, por respeito às crenças e tradições locais, minerar os cristais é estritamente proibido. Naturalmente, os visitantes também são proibidos de levar até mesmo um cristal do tamanho de um grão de areia. Por favor, respeite a tradição durante suas viagens!",
  str_dispatch_book_chaptercont_6000_4 = "No extremo norte do continente de Astra, as gigantescas cordilheiras Espinha do Mundo impedem todas as tentativas de exploração além de seus picos cobertos de neve. Por outro lado, algumas pessoas dizem que essas montanhas mantêm nossas terras seguras contra ameaças naturais e sobrenaturais da Terra da Noite Eterna e da Terra do Dia Eterno.\n\nEstas cordilheiras glaciais raramente recebem visitantes e, segundo a lenda, é o lugar em que nasceram os Aurorians. De fato, alguns Aurorians são céticos do status dela como a suposta origem da sua espécie. Entretanto, ao verem o palácio construído inteiramente de gelo no interior das montanhas, muitos céticos não têm escolha senão reconhecê-lo como uma obra-prima dos seus ancestrais do norte. \n\nSe tiver sorte o bastante de ser convocado pela Rainha do Norte, você vai subir a longa e congelante escadaria até a entrada, e depois será recebido não por mais frio, mas por um calor primaveril inexplicável. Essa característica única explica por que o Palácio Invernal é famoso em Astra: a combinação de gelo, neve e calor só pode ser descrita como mística. \n\nSeja dia ou seja noite, o Palácio Invernal irradia um charme onírico. A luz do sol, da lua e das estrelas infiltra-se pelas paredes cristalinas do palácio, refletindo e refratando infinitamente, produzindo todo tipo de cores brilhantes em seus salões. O mais fascinante, em especial, é o efeito da aurora de Northland no palácio: durante essa estação, as paredes ganham vida com incontáveis luzes e sombras bailarinas. Essa experiência é única do Palácio Invernal, e eu fui abençoado com a oportunidade de ver isso uma vez na vida. Como um andarilho bem viajado pelo mundo, eu vi incontáveis maravilhas, naturais e feitas pelas pessoas, mas nada se compara ao impacto e deslumbramento que senti quando vi as luzes do norte brilharem no palácio...",
  str_dispatch_book_chaptercont_7000_1 = "O Criador do mundo \n Decidiu começar algo novo \n Assim, uma terrível tempestade começou a limpar a terra \n A luz da lua foi extinta \n Ele anunciou a chegada do Eclipse ao mundo \n Ele viajou entre a luz e a escuridão por dois dias e criou seus mensageiros \n Por fim, ele mandou a luz do sol brilhar no mundo abaixo \n Com magma ardente \n E, do mundo, ele exterminou todas as criaturas vivas que resistiam a ele \n __________ \n ____________________ \n _____________ \n ____________ \n _____ \n _________ \n\n Antes da Escuridão cair \n Uma pessoa perguntou uma vez, \n “Qual era o propósito desse sonho e sua concepção?” \n E uma Consciência respondeu, \n “Permitir que a eternidade retorne aos céus. \n Alcançar o outro lado \n Avançar.” \n Outra perguntou, \n “Qual é o objetivo que encontraremos no fim desse labirinto?” \n E a consciência respondeu, \n “Saber tudo.\n Remover os obstáculos. \n Convergir.” \n Então, ele revelou sua vontade \n\n “Avancem. Avancem sem parar. \n Superem. Superem sem hesitar.” \n Nessa hora \n Um seguidor disse, \n “Provavelmente morreremos aqui.” \n Assim, a Consciência pôs em movimento os imensos corpos celestiais. \n E quebrou o mais absoluto dos princípios \n Pois ninguém, além dela, poderia fazer isso. Com determinação inabalável, \n Ela decidiu viajar para muito além dos céus \n Ver os olhos do abismo \n E assim, os Fiéis apareceram \n Eles executam suas ordens \n Abolir \n Proibir \n Renovar \n Permitir que tudo chegue ao fim \n Ser como o fim dos dias \n Permitir que a Escuridão caia",
  str_dispatch_book_chaptercont_7000_2 = "No começo, ele responderá às perguntas que pesam na sua mente. \nQuando você estiver obcecado com a liberdade, ele lhe dirá:\n“Emoção e obsessão são as raízes dos seus problemas. Livre-se delas, e se aproximará da liberdade.”\nQuando você não tiver certeza de como prosseguir, ele lhe dirá: \n“Adversidade é necessária para avançar. Somente ao aceitar e suportar a adversidade, você ficará mais forte a cada dia que passar e caminhará ao longo da estrada certa.” \n\nLogo ele começa a nos mostrar como nos tornar uma pessoa justa: \n“Para entender alguém, é necessário apenas observar se as ações e motivações dessa pessoa estão alinhadas. Então, é possível julgar a sinceridade dela.” \n“Quanto mais você se dedicar em entender as mentes dos outros, menos esforço precisará para melhorar a si mesmo. Entende?” \n\nEle começa a agir como nosso professor e compartilha sua sabedoria: \n“Os que não se banham, cheirarão como nada quando o fogo estiver baixo. Aqueles que sacrificam nada e que não aprendem habilidades, embora pareçam virtuosos para alguns, aos poucos perderão o cheiro do fogo com o passar do tempo.” \n“A inveja não adicionará nada de valor na sua vida, nem diminuirá a distância entre você e os outros.”\n \nEle começa a nos moldar como heróis: \n“Em vez de remoer o fato da derrota, mantenha a calma como uma pessoa de coragem faria.” \n\nEle começa a refletir: \n“Expresse sua persistência por meio da humildade, adicione uma pitada sutil de tragédia e os outros aceitarão.” \n“Todos os grupos têm uma determinada quantidade de vida, mas nem todos os grupos entendem, muito menos protegem, aquilo que constitui sua vida. Essas vidas que entendem esse princípio, por consequência, são atormentadas por ele.” \n\nEntão, ele começa a proclamar: \n“Os vivos possuem a vontade de Deus e suas bênçãos, e as duas devem ser cuidadas e protegidas de acordo.” \n“'As emoções não são nem públicas nem particulares. Não há regras nem normas para elas’. Esse é o tipo de mentalidade que os indivíduos buscam e em que se agarram até a morte.” \n“Mas por meio da reunião de desejos individuais como uma mentalidade de grupo, podemos acomodar aspirações ainda maiores.” \n\nEle começa a nos culpar: \n“Você encheria seu cantil com areia? Então porque encheria sua mente de pensamentos mundanos?” \nEle começa a nos tentar: \n“Isso é o que você deveria almejar.” \nEle começa a representar: \n“Suas ideias se tornarão meus pensamentos. Suas aspirações devem ser direcionadas aqui, e se tornar tanto a fundação quanto o ímpeto da realização dos seus ideais.” \n\nEle representa a realidade, o pináculo da verdade e sabedoria. \nMas no fim, ele desiste de dialogar com as pessoas e escolhe dar as ordens em uma nova linguagem. \nÉ uma linguagem que vem das pessoas, mas não para as pessoas. \nÉ uma linguagem objetiva criada para nos liberar das correntes da subjetividade...",
  str_dispatch_book_chaptercont_7000_3 = "_____________________ \n________ \nA verdade dentro do texto \nSão como pedras em um rio \nSempre em silêncio, elas ficam no fundo \nEnquanto as pedrinhas e a areia são levadas pela corrente \nPor esse motivo, nós sabemos \nQue em algum lugar do mundo, em algum momento no tempo \nA grande mandíbula da guerra consumiu tudo \nSe alguém perguntasse o que começou essa guerra \nA resposta seria: a ganância \nA ganância de poucos causou desastres para todos. \n\nUma pessoa uma vez descreveu o que eles viram \nEm um instante \nUm totem dracônico se ergueu \nTrazendo consigo uma tempestade que escureceu os céus \nE então, na Terra do Aço \nUm mensageiro desceu \nEm uma missão de uma montanha distante \nEle galopou como o trovão \nSem precisar de um arco \nDez mil flechas apareceram em um piscar de olhos \nPerfurando as planícies infinitas abaixo \nMatando tudo à vista \n\nNa trágica consequência da batalha \nAs nuvens escuras pareciam cobrir a terra \nO mensageiro declarou que não haveria sobreviventes na guerra \nMas um corvo encontrou os sobreviventes \nE eles fugiram antes das névoas se dissiparem \nEles pegaram cem barcos \nCada pessoa carregando dez grãos \nCada vez que cruzavam uma montanha, uma gigante parede de lama e pedra, \nEles perdiam um barco \n\nEles formaram grupos e vagaram pela terra \nAté que o cetro se tornou um bastão \nE então, o pastor deu o bastão para o marinheiro \nE o filho do marinheiro deu a concha para o profeta \nE por fim, o profeta decidiu \nPegar a última pena da cauda da águia \nPegar o sangue queimado dos prisioneiros \nPegar o papel sobre o qual a aurora uma vez brilhou \nE nele escrever um pedido. \nE o jogou em um poço \nE depois de três dias e três noites \nUma pedra no fundo do poço abriu a boca para falar \nE a pedra disse: \nTodos vocês, esperem a neve cair com força \nE enterrem todos sob ela \nEsperem a luz salvar vocês do frio \nEsperem passar setecentos anos de calor \nEsperem dez milhões de vagalumes \nEsperem a grande torre desaparecer, e o lago aparecer \nEsperem os guerreiros viajarem pelo mundo como a maré \nEsperem a lua brilhar como o sol \nEsperem o sol parar de queimar o mundo quando subir \nEntão usem a pedra mais dura e o gelo mais frio para cercar o reino \nE ao fazerem isso, enfim retornem ao mundo.”",
  str_dispatch_book_chaptercont_8000_1 = "Projeto Valquíria - 15 de janeiro de XXXX, 10h00. Espécime 3. Teste de Decodificação de Consciência. Tentativa 219: Iniciar teste.\n“As instalações e o equipamento de gravação estão no lugar e prontos para começar.”\n“Conexão com interface cerebral bem-sucedida. Entrando na rede neural do espécime. Geração de imagens da ressonância nominal. Como se sente, XX?”\n“Eu... me sinto bem. Não está mais frio. Só estou sentindo tontura...”\n“Com base na sua resposta da tentativa anterior, ajustamos a estrutura do seu hipocampo. Isso pode ser resultado desse ajuste.”\n“Se tudo ocorrer bem, você pode esperar sua adaptação em 24 horas.”\n“Entendo... Hm... Ela vai estar aqui hoje?”\n“Ela... Ela sempre aparece... Com os cabelos longos e prateados dela, e... Ugh!”\n“Estamos perdendo o sinal da imagem, major!”\n“Você tem que se acalmar, XX!”\n“Acalme-se! A pessoa de quem você está falando... não existe.”\n“Não existe?”\n“Isso mesmo... Somos os únicos aqui. Aquela pessoa... Talvez seja uma memória de um espécime diferente?”\n“Não entendo...”\n“É só um sonho. Você sabe o que são sonhos, não sabe?”\n“Mas... Sou um homúnculo... Homúnculos também sonham?”\n“Claro que sonham... Você sonha quando dorme. Os sonhos podem ser longos ou curtos, felizes ou tristes... Mas a maioria é esquecido depois que acordamos. Assim como com os seres naturais.”\n“O sinal se estabilizou, major.”\n“Ótimo. Você já pode descansar, XX. Vamos, feche os olhos...”\n“Entendi... Boa noite, major Hartman. Tenha bons sonhos.”\n“Boa noite, XX. Tenha bons sonhos também.”\nProjeto Valquíria - 15 de janeiro de XXXX. 11h00. Espécime 3 (Sistema de Controle Mestre, codinome NOIR). Teste de Codificação de Consciência. Tentativa 219. Fim do teste.",
  str_dispatch_book_chaptercont_8000_2 = "Ano do calendário XXX, 14 de julho\nOs sintomas de Lilin estão piorando. Minha pobre e adorada filha... Mas tenho uma ideia. Será vista como uma transgressão contra Deus, se eu for descoberto, e serei espancado até a morte... Mas não tenho outra escolha. Sayla... Não consegui ficar ao seu lado e lhe salvar, mas dessa vez... Com certeza vou salvar Lilin!\n\nAno do calendário XXX, 4 de setembro\nO experimento ocorreu estavelmente, o que é, tenho que dizer, inesperado. Foi muito além das minhas expectativas! Ultimamente, comecei a me sentir cada vez mais... Peculiar. Alguma coisa não parece perfeitamente bem. Normalmente, sou quem projeta e conduz meus experimentos, seguindo minhas ideias, mas agora... Sinto como se alguém, ou alguma coisa, estivesse no meu cérebro, guiando minhas ações! Mas como isso seria possível? Afinal de contas, eu sou um neurologista. A ideia é positivamente risível! Seja como for, os dias não têm sido de paz, ultimamente. Com toda minha atenção dedicada a Lilin, o financiamento para meu experimento esgotou... Felizmente, eu consegui vender a lembrança do nosso amor para continuar minha pesquisa! Por favor, não fique irritada, Sayla. Isso foi para salvar nossa filha amada, afinal. Certo? Certo?!\n\nAno do calendário XXX, 13 de dezembro\nQue desastre! Aqueles vândalos estão na minha porta... Acho que Baas não vai resistir até amanhã. Estou tão perto do fim, também! Calma, calma... Eu fiz meus cálculos nas nove réplicas e nos sistemas sensoriais delas incontáveis vezes... E as estruturas corpóreas delas estão estáveis até agora! Por isso que... Vai ficar tudo bem! Estou acordando você agora, Lilin! Dessa vez, você consegue, eu sei que consegue. Você e o papai vão fugir deste lugar terrível, sem dúvida disso! Ouviu, Sayla? Observe-nos, meu amor... Vou escrever para você novamente depois que tudo ficar bem! Tudo vai ficar bem!",
  str_dispatch_book_chaptercont_8000_3 = "Relatório ____: \nDe acordo com o relatório da batalha “Encontro da Montanha Scythia 154” de __ dias atrás, o inimigo está equipado com um novo tipo de armamento avançado que pode mudar o cenário da guerra atual. Com base no conhecimento obtido da equipe de transporte, do inimigo que emboscamos __ dias atrás, essa arma nova ainda não foi produzida em massa. Em vez disso, provavelmente está em teste de campo de pequena escala. Acredito que o resultado do “Encontro da Montanha 154” forneceu ao inimigo resultados satisfatórios. \nA julgar pelo nosso progresso nos últimos três meses, a produção e a distribuição em massa da armadura de batalha ____ para nossas forças foi um grande sucesso. Individualmente, nossos soldados ficaram tão bem-protegidos, como pequenos tanques, ao equiparem a armadura de batalha ____. Não apenas puderam resistir a tiros de pequeno e médio calibre facilmente, mas também puderam carregar mais munição e outros suprimentos sem dificuldades. Além disso, os sistemas de inteligência e comunicações integrados na armadura permitiram que todos os soldados desempenhassem um papel vital no campo de batalha. Considerando que nossas forças já controlam os céus, nossa efetividade ao tomar e manter controle do território inimigo com certeza aumentará com nossos soldados equipados com essa nova armadura.  Sob essas circunstâncias, eu tinha confiança de que a resistência do inimigo logo cairia. \nNo entanto, ninguém antecipou o potencial destruidor dos novos rifles do inimigo. O terreno irregular e fragmentado da Montanha 154 atrasou nossas capacidades de reconhecimento aéreo, efetivamente anulando nossa superioridade no céu. Além disso, as forças inimigas estavam em grande número, mas espalhadas e escondidas pelo campo de batalha. Usando o conhecimento que tinham do terreno e os rifles novos, eles mataram dezenas dos nossos soldados à distância, com balas altamente perfurantes. De acordo com os cálculos dos nossos cientistas, nem mesmo o revestimento frontal dos nossos tanques de batalha podem resistir ao poder de perfuração deles. Mais aterrorizante que isso é que esses rifles novos aparentemente não emitem clarão no cano nem som quando são disparados. Os poucos soldados sobreviventes reportaram que não viram um único inimigo na suposta direção dos ataques. De acordo com a inteligência reunida pelos nossos espiões, é como se o inimigo tivesse desenvolvido uma forma de camuflagem ativa junto dos rifles novos. Concluindo, a batalha na Montanha de Scythia 154 foi pré-projetada por ___________ como um teste de campo do novo equipamento deles, e um massacre dos nossos soldados.",
  str_dispatch_book_chaptercont_8000_4 = "________ “Drácula! Esses demônios anciãos são como uma maldição sobre nós! Não, uma maldição sobre todos os seres humanos!” Ele jogou sua espada no chão e disse para o professor: “Essas criaturas, nascidas da mais negra maldição, preparam-se para a noite eterna como se fossem nascidos para isso. O sol é seu inimigo mortal, e a noite, o santuário... Estão para a noite como o peixe para a água.” \n“Meu bom prefeito, não acredito que precisemos temer esse tal de Drácula. De acordo com minhas pesquisas...” \n“Bem, você descobriu algo novo? Descobriu uma maneira de nos livrarmos desse tormento de uma vez por todas?” \n“N-não, senhor, sinto muito... De acordo com minhas pesquisas, apenas o sol pode matá-los...” \n“Você... chama isso de pesquisa? Declarar o que já sabemos?! Esses monstros vis já invadiram a cidade e nos encurralaram no subsolo! Se você não encontrar outra maneira de matar essas criaturas logo, não haverá mais tempo para sua assim chamada ‘pesquisa’!” \n“D-de acordo com minhas pesquisas...” \n“De novo esse papo de ‘pesquisas’?” \n“Pode ser melhor... nos unirmos a eles.” \n“Nos unirmos a eles?!” Completamente chocado, o prefeito sacou sua espada e a apontou para o professor. “Explique-se, e seja rápido.” \nO professor ajeitou os óculos devagar. “Estritamente falando, acho que esses demônios são capazes de se comunicarem. São formas de vida sencientes e orgânicas muito semelhante a nós! O Drácula é sábio e pode se comunicar muito claramente. Esses demônios são racionais e sentem emoções, têm as próprias estruturas sociais e, de fato, uma civilização completa exclusiva à espécie deles. Com certeza, os hábitos alimentares deles fazem com que seja um pouco difícil para nós os aceitarmos...” \n“’Hábitos alimentares’, você diz!” O prefeito girou a espada, quebrando um vaso de vidro. “Os ‘hábitos alimentares’ deles são sugar cada gota do sangue dos nossos corpos!” \n“Talvez ‘hábitos alimentares’ seja o termo errado. Em vez disso, é a fraqueza deles. Eles precisam se alimentar de sangue para sobreviver, o que, em contrapartida, torna-os fatalmente vulneráveis à luz do sol. Em troca, no entanto, eles são dotados de longevidade, força, agilidade e beleza...” \n“Uma beleza tão pálida quanto a morte, para ser claro...” \n“Então o senhor também reconhece a beleza de Drácula, meu caro prefeito!” \n“Não ponha palavras na minha boca, professor!” \n“Mas o senhor tem que admitir que sob uma noite eterna, esses seres são muito mais poderosos do que nós. Talvez essa seja a direção verdadeira do nosso futuro, ou da evolução em si. Mesmo que o senhor os tema e despreze, e seus filhos? Ou os filhos dos nossos filhos? O passado era repleto de ódio entre raças diferentes, mas com o tempo elas se mesclaram e deram à luz novas raças!” \n“Nem mais uma palavra da sua boca, professor!” \n“Meu caro prefeito, acalme-se, por favor, e embainhe sua espada. Matar-me agora não vai mudar nada.” \n“Hein?!” \n“Por que já é tarde demais para você...” ________",
  str_dispatch_book_chaptercont_9000_1 = "Os homens do Grande Papagaio eram bravos guerreiros de todo o reino, o que se podia ver pelo seu comportamento e os nomes com que chamavam uns aos outros. Querendo trazer entretenimento a bordo do navio, olharam rindo para o jovem Colin, que admirava o mar calmo como se estivesse hipnotizado.\n“Que tipo de gente é essa, junto com os maiores heróis de nossa terra? Ele nunca pôs os olhos no mar antes?” Alguns dos homens começaram a rir alto.\n“Ouvi dizer que ele é filho de um pescador local,” disse alguém.\n“Pela cara dele, nunca leu uma carta náutica nem saiu pelo mar uma única vez, muito menos lutou pela própria vida. Só conhece os peixes! Os pescadores daqui nunca vão além dos corais, então só pegam os peixinhos meio mortos que boiam pra dentro da rede.”\n“Então qual a serventia dele pra encontrar o tesouro? Vai jogar umas redes pra procurar? Ah, pelo menos ele vai trazer camarão ou algas pro jantar!”\nA essa hora, o convés todo morria de rir, e os maiores heróis do reino começaram a chamar o garoto de “Capitão Colin.”\nIgnorando as zombarias dos outros, Colin se retirou para seus aposentos a fim de descansar para a aventura que viria.\nEle foi acordado de seu sono pelo som de alguém gritando, “Tempestade à vista!” Ainda meio dormindo, percebeu que o Papagaio balançava violentamente de um lado para o outro, como uma planta ao vento.\nEle cambaleou até o convés para ver o que estava acontecendo, mas quase foi jogado ao mar pelo vento fustigante. Ao ser lançado pelo convés, instintivamente agarrou o que conseguiu. Por sorte, acabou sendo um pedaço de corda que estava amarrado ao mastro.\nO capitão, um homem alto e magro com uma vasta experiência em navegar em alto mar, se orgulhava de sua habilidade de pressentir a chegada de uma tempestade por meio das juntas de seus joelhos. Nesse dia, no entanto, ele tinha tomado uma taça ou duas de seu melhor vinho, cortesia do filho de um nobre, e seus joelhos proféticos estavam trêmulos e totalmente desatentos ao desastre que chegava. Segurando-se com toda a sua força, ele ordenou à nova tripulação que abaixasse as velas. Com dificuldade, vários dos poderosos heróis da terra tentaram se equilibrar no navio desgovernado, apenas para serem varridos para o mar por uma onda gigantesca que colidiu com o convés com uma força devastadora.\nEm meio à chuva torrencial, Colin tossia e cuspia. Recobrando os sentidos, ele percebeu que a onda o tinha derrubado, mas felizmente não o tinha mandado para um túmulo aquático. Vagamente, se lembrou de ouvir o capitão gritando para que abaixassem as velas, antes da onda atingi-lo, e com a confusão, percebeu que ninguém tinha seguido as ordens.\nO capitão também estava inconsciente por causa de seus ferimentos. O resto da tripulação estava ferida, afogada, ou resignada a seu destino pelas mãos da Mãe Natureza. Tomando coragem, Colin amarrou a corda na cintura e começou a subir o mastro. Enquanto tentava abaixar o mastro sozinho, gritava para os homens, “Enquanto o navio sobreviver, sobreviveremos com ele!”\nAlguns homens abaixo, animados pelas palavras e ações de Colin e desejando não morrer em vão, seguiram o exemplo do garoto. Amarrando cordas em volta de si, subiram ao convés para apoiar Colin, suas palavras soando verdadeiras para eles. Com o navio como espada, eles cortaram pela tempestade e sobreviveram ao primeiro encontro com a morte em sua viagem.\nNa calmaria após a tempestade, um dos homens se aproximou de Colin e perguntou seu nome. Notícias do feito heroico se espalharam rapidamente pelo navio, chegando aos ouvidos dos sobreviventes e do próprio capitão, que já havia recobrado a consciência. Ele foi reconhecido por cada um dos homens restantes como herói. O homem que lhe havia nomeado zombeteiramente de “Capitão Colin” se desculpou, e passou a chamá-lo de “Colin, o Valente”.\nNo entanto, os problemas deles estavam longe de acabar. A tempestade deixara as velas em frangalhos, e o capitão avisou que sem as velas para direcionar o navio, eles iriam boiar sem rumo ou bater e naufragar. Foi aí que Colin, o Valente, teve uma nova ideia: voltando-se para a tripulação, ele sugeriu que costurassem os cobertores e outros tecidos nas velas rasgadas.\n“Deixem tudo comigo,” Colin assegurou a eles. “Afinal, sou filho de um pescador.”\nEle começou a desenrolar um pedaço de corda para fazer a linha, e, com uma agulha feita de uma espinha de peixe, tomou para si a tarefa hercúlea de costurar novas velas totalmente à mão.\nDepois de horas e horas de trabalho, o Grande Papagaio içou suas novas velas improvisadas, e voltou a navegar sem incidentes.",
  str_dispatch_book_chaptercont_9000_2 = "A segunda ilha era ocupada por dragões voadores, mais do que qualquer um dos homens já havia visto na vida. Guardavam um tesouro secreto no fundo de uma caverna, e atacavam em bando qualquer um tolo o suficiente para se aproximar. Apesar da proficiência em combate dos guerreiros, ao verem um número incontável de dragões voadores, eles decidiram bater em retirada num primeiro momento.\nOs dragões, no entanto, não foram tão amigáveis. Perseguiram incessantemente os heróis até a costa da ilha.\nProvocado pela insistência deles, um guerreiro se voltou para a horda dracônica e gritou, “É assim que repagam nossa piedade? Escolhemos não massacrá-los, mas agora não nos deixam escolha! Atacar!”\nEle puxou a espada, com o furor da batalha rugindo em seus olhos.\nPorém Colin, o Valente, segurou o braço do homem, apontando na direção da montanha no centro da ilha. Antes que o guerreiro tivesse a chance de responder, rugidos altos e violentos tremores começaram ser ouvidos do meio da montanha.\nDe repente, uma forma colossal surgiu do topo. Não era uma montanha, mas sim um vulcão, e ainda por cima lar de um dragão gigantesco!\nOs guerreiros, sabendo que não tinham chance contra um inimigo tão grande, empurraram o navio de volta para o mar, para longe da ilha infestada de dragões.\nO guerreiro se virou para Colin, o Valente, e perguntou, “Como sabia que um dragão sairia daquele vulcão?”\n“Não sabia,” Colin respondeu. “Só senti as vibrações no chão aos nossos pés.”\nO guerreiro, no entanto, não ficou satisfeito com a resposta. “Os tremores só começaram quando a grande besta começou a surgir! Que besteira é essa que está me dizendo, então?”\nColin educadamente pediu que o guerreiro evitasse conclusões precipitadas, então ouviu atentamente por alguns segundos antes de dizer, “O cozinheiro do navio vai subir ao convés em alguns instantes.”\nE certamente, alguns segundos depois, o cozinheiro subiu para o convés.\nColin começou a se explicar novamente, mas o guerreiro finalmente entendera: Colin, o Valente, era capaz de sentir vibrações que outras pessoas não sentiam, e podia até mesmo discernir o tamanho e forma aproximados de um objeto próximo. Assim, conseguiu prever a forma massiva do dragão se aproximando. O cozinheiro, ouvindo sobre a experiência e a habilidade incrível de Colin, cordialmente convidou os homens para beber e comer sua carne seca de coelho especial.\nO Grande Papagaio navegou pela metade de mais um dia, mas ao chegar em seu destino, os passageiros ficaram completamente chocados. A primeira ilha onde haviam parado, e para a qual decidiram retornar, havia desaparecido no ar!\nUm aventureiro confuso olhou para a tripulação e perguntou se haviam lido o mapa incorretamente.\nA tripulação olhou o mapa com cuidado e consultou suas ferramentas de navegação, e após pequena discussão, concluiu que nenhum erro de navegação havia sido cometido.\nDe repente, Colin sentiu outra vibração misteriosa. Ele correu para a proa do navio e olhou para o mar. Após alguns instantes, ondas estranhas começaram a ir na direção deles, fazendo com que o Papagaio balançasse cada vez mais forte.\nEnquanto os heróis especulavam sobre a natureza do fenômeno, alguns olharam para o horizonte. Notaram que o mar estava ficando cada vez mais escuro, como se uma grande sombra pairasse sobre as águas.\n“Isso sempre acontece,” um dos homens disse, rindo consigo mesmo. “De vez em quando as nuvens cobrem o sol, e deixam uma sombra assim na superfície da água.”\nTodos olharam para o céu, mas para seu desespero... Não havia uma única nuvem acima deles. Perceberam que isso significava que a sombra estava abaixo da superfície da água, se escondendo nas profundezas.\nNão muito tempo depois, a superfície da água começou a borbulhar, e objetos pequenos e brancos começaram a boiar para a superfície. Um dos homens apontou a luneta para um conjunto dos objetos brancos. Aterrorizado, sussurrou, “São os coelhos que encontramos na primeira ilha...”",
  str_dispatch_book_chaptercont_9000_3 = "Colin, o Valente, acordou e percebeu que estava deitado no chão duro. Ainda tonto, ele tentou sentir com a mão. Era frio e liso, como uma grande pedra. Ele se sentou e esfregou os olhos, e começou a olhar em volta. O que viu tirou seu fôlego. Água corria acima de sua cabeça, embaçada e azul, como se ele estivesse no fundo do mar. Um ponto de luz fraca também brilhava acima. Seria o sol? Ele percebeu que respirava, mas não saíam bolhas de sua boca. Queria fazer algum som, mas o ambiente estava quieto demais.\nLevantando -se, ele percebeu que estava no meio do que parecia ser uma estrada, flanqueada nos dois lados por estátuas estranhas. Atraído por sua curiosidade, ele inspecionou as estátuas com mais atenção. Pareciam monstros esculpidos em algum tipo de argila.\nColin estendeu a mão para tocar uma delas, e a superfície estranhamente pedregosa fez com que ele afastasse a mão, como se tivesse tomado um choque.\nAlém das estátuas de pedra, ele viu uma estrada comum que se estendia a distância, e terminava no que parecia ser uma escadaria desproporcionalmente grande. Ele olhou para o topo. No fim da escada, parecia haver as ruínas de um enorme portão de pedra, em sua maior parte destruído.\nEle olhou para trás de si mesmo e viu que a escada terminava na beira de uma fossa marítima não muito longe, deixando Colin com apenas uma opção de caminho a seguir. Ele sentia como se estivesse sendo observado por inúmeros olhos, mas não havia nada a sua volta. Perdendo a coragem, ele começou a correr. Queria desesperadamente abandonar aquele lugar, mesmo se tivesse que rastejar pela enorme escada diante dele. Olhando para trás, ele percebeu com horror que os olhares que sentia pareciam vir do abismo. Cada pelo de seu corpo se arrepiou, cada instinto dizendo que devia fugir e se salvar.\nEle subiu dúzias dos grandes degraus de pedra quase sem esforço, mas então percebeu uma estranha característica desses degraus: pareciam ficar maiores e mais largos à medida em que ele subia.\nChegando ao portão destruído, ele viu uma figura grotesca entalhada em um dos fragmentos: algum tipo de monstro, com olhos gigantes e tentáculos.\nColin estremeceu, de medo ou animação. Sentiu seu coração o encorajando a seguir em frente.\nAo passar por cima dos destroços do portão, ele ficou atordoado com a visão diante de si. Situadas numa vasta planície submarina estavam as ruínas de um enorme reino. A mente de Colin praticamente zumbia com tantas perguntas, mas uma em particular o incomodava. No começo da escada que acabara de subir, os degraus eram compatíveis com o tamanho de um humano mediano. Conforme subia, no entanto, eles ficavam cada vez maiores até que ele não teve escolha a não ser escalar com as mãos e os pés. Que estranho, que mesmo esse reino uma vez adorado por todos, agora, estando em ruínas, seus visitantes ainda deviam rastejar em sua direção como se ajoelhassem em adoração.\nColin sentiu aquele olhar familiar desconfortável atrás de si, e rapidamente se virou... Mas quando se deu conta, estava deitado na areia de uma praia quente. As ondas que lavavam seus pés lhe asseguravam que ele não estava mais sonhando, e ele começou a explorar seus arredores. Não encontrou nada diferente, a não ser marcas estranhas na areia, como se algo tivesse sido arrastado.\nDe repente, Colin se lembrou da última coisa que tinha visto no mar: um enorme monstro com tentáculos de um branco acinzentado...",
  str_dispatch_book_chaptercont_9000_4 = "De repente, um enorme tentáculo surgiu da água, se esgueirando pela lateral do Argo. O navio inteiro começou a se inclinar, e a tripulação ficou congelada de medo. Apenas Colin, o Valente, se moveu. Levantou um machado acima da cabeça e o enfiou fundo no tentáculo, que se aproximava. O guerreiro, novamente contagiado pela bravura de Colin, puxou sua adaga e a enfiou no tentáculo. Os dois lutaram até que ele foi completamente cortado da besta.\nA tripulação levantou as velas com rapidez, tentando voltar para terra firme, mas os mares começaram a se agitar violentamente. Primeiro, a tripulação achou que era um grande pedaço de coral que havia boiado para a superfície, mas conforme continuava a vir à tona, perceberam que era a pele rugosa de algum monstro gigantesco. Para o alívio da tripulação, ele parou de emergir das profundezas, estranhamente quieto.\nColin, o Valente, se sentiu tonto, lembrando inconscientemente do enorme monstro esculpido nas ruínas do portão de pedra, no reino submarino. O que ele não sabia é que essa besta tinha um nome que só podia ser encontrado em antigas cartas marítimas: Havga.\nApós balançar de um lado para o outro na água, a antiga embarcação Argo finalmente chegou à praia. A tripulação desembarcou e decidiu escalar o penhasco que corria pela borda da praia.\nNa metade da subida do penhasco, um dos homens ouviu Colin murmurando.\n“Há dois monstros das profundezas...” ele o ouviu dizer.\nO guerreiro, sempre preocupado com Colin, mas também impaciente, o agarrou e perguntou, “O que disse?”\n“Um monstro que consegue atacar dez navios ao mesmo tempo... essa nova criatura negra combina muito mais com a descrição, não acha?” Colin não olhava para o guerreiro, mas sim encarava a distância, como se estivesse num sonho.\n“Dois monstros, você diz?” A tripulação estava incrédula, mas depois de pensar por um momento, perceberam que era totalmente possível. O primeiro monstro que haviam encontrado tinha tentáculos branco-acinzentados, da mesma forma que o tentáculo que havia acabado de agarrar o Argo. O novo monstro que se levantara do mar, no entanto, era totalmente negro...\n“Os rumores estavam errados? Esse não é o Kraken?” O guerreiro debateu consigo mesmo por um longo tempo antes de concluir a discussão.\n“Já viram uma criatura do mar chamada ‘polvo’?” Perguntou Colin, parecendo voltar a si.\n“Não, o que é?” Perguntou um dos homens.\n“Ouvi dizer que não é peixe, e sim um demônio que possui o mau-olhado!” Respondeu outro.\n“Ouvi rumores sobre ele, dizem que é uma criatura esperta e enganosa,” opinou um terceiro homem.\n“Isso mesmo. Meu pai já pegou um, mas ele escapou... e aquele monstro branco-acinzentado parece muito com um polvo,” Colin disse. “Mas polvo nenhum é grande o suficiente pra fazer uma frota de navios ou uma ilha inteira desaparecerem de um dia pro outro,” ele acrescentou.\nDito e feito, o monstro negro que emergia gradualmente do oceano era muito maior do que qualquer polvo. Conforme a espuma e as ondas em volta dele ficavam maiores e mais violentas, a forma de uma pequena montanha apareceu da água. Parecia ter perdido a maior parte da vegetação que antes crescia nela, e só a pedra nua estava exposta ao ar.\nSomente quando a tripulação chegou ao topo do penhasco e olhou para baixo é que perceberam a verdadeira dimensão do monstro das profundezas. A pequena montanha que tinham visto antes tinha emergido completamente, junto com um enorme tentáculo preto. Com um gesto enorme, o tentáculo jogou uma onda que atingiu a floresta da ilha abaixo, junto com o Argo.\nCom o navio preso entre as árvores, agora submersas, os homens começaram a perder a esperança.\n“É impossível... Como podemos derrotar um monstro como esse?” O terror começou a tomar conta dos corações dos heróis mais corajosos do reino.\n“O antigo navio Argo e o Olho Dourado... de acordo com nosso mapa do tesouro, só o que falta é o Tridente do Mar Profundo. Contanto que o encontremos, temos uma chance de derrotar esses monstros do mar!” proclamou Colin, o Valente.",
  str_dispatch_book_chaptercont_10000_1 = "I. Renda-se à liderança exemplar do Grande Marechal.\nCitando o Grande Marechal de Illumina, “Só os corajosos ousam tentar alcançar alturas impossíveis.”\nComo líder da Federação Illumina e núcleo indiscutível das forças armadas, o Grande Marechal de Illumina é, sem dúvida, um cidadão modelo e um exemplo que os cidadãos de Illumina devem estudar e seguir. O Grande Marechal nos ensina a tratar uns aos outros como família, e nos une ao reforçar nossos ideais e apoiar a autodisciplina. O Grande Marechal vê todos os cidadãos de Illumina com a luz e o calor de um glorioso dia de primavera, e os protege ao erradicar seus inimigos com um poder avassalador.\nCaso ache que em sua vida falta fé ou liderança, o Grande Marechal de Illumina é, sem dúvida, sua melhor escolha de salvação.\n\nII. Splendor Illumina, permaneça fiel a suas tarefas e mantenha a mente limpa. Quer esteja enfrentando a praga Eclipsita na linha de frente, ou desenterrando descobertas de civilizações antigas, cada soldado de Illumina deve reconhecer e manter as responsabilidades colocadas em seus ombros:\na. Eliminar todos os Eclipsitas que ameacem a sobrevivência de Aurorians.\nb. Escavar e pesquisar com vontade as ruínas de civilizações antigas, para melhorar nosso entendimento tecnológico e inovação.\nc. Restaurar a luz, a glória e a prosperidade dos Aurorians e desse continente, em nome de Illumina.\n\nIII. Se junte à glória e à justiça.\nA maior diferença entre a Federação Illumina e as outras forças é nossa gloriosa missão de lutar por todos os Aurorians, e nosso claro senso de justiça para distinguir o certo do errado. A Guarda, liderada pela Inspetora Geral Nemesis, trabalha incessantemente para assegurar a implementação inequívoca de nosso dogma. São os supervisores da disciplina militar da Federação Illumina e defensores de nossa fé. Caso a Inspetora Geral Nemesis ache por bem questionar você, seja honesto quando responder às perguntas e não faça nada para irritar essa Executora da Justiça. Naturalmente, se for um verdadeiro defensor da justiça e expressar sua gratidão a ela, também pode se tornar seu aliado na justiça.",
  str_dispatch_book_chaptercont_10000_2 = "I. Obedeça, mas lembre-se de que todos são iguais.\nNa Federação Illumina, a hierarquia e posição militar determinam quem lidera e quem segue, mas aqueles mais acima na hierarquia não têm mais privilégios do que os cidadãos comuns! Essa igualdade entre todos os cidadãos é um fator crucial que distingue nossa ideologia da de Lumópolis. Na Federação Illumina, não somos apenas companheiros de luta, mas também família! Independentemente do seu passado, enquanto concordar e defender os valores de Illumina, pode passar em sua avaliação e se tornar um orgulhoso membro de valor na nossa sociedade!\n\nII. Certifique-se de que seu equipamento está sempre funcionando.\nCada soldado na Federação Illumina tem a responsabilidade, para consigo mesmo e seus companheiros de luta, de verificar e fazer manutenção em seu equipamento. Isso inclui, mas não se limita a: manutenção de rifles cinéticos, conservação da armadura de combate e otimização do fio das lâminas. Isso não é somente porque Cidade Gannon serve como principal força de combate contra a ameaça Eclipsita e deve estar pronta para a batalha a qualquer momento, mas sim porque se qualquer instrutor achar que você não está preparado o suficiente para o combate, vai mandá-lo para uma dura sessão de treinamento muito pior do que enfrentar uma legião de Eclipsitas. Você foi avisado.\n\nIII. Tecnologia em primeiro lugar.\nOs soldados de Gannon originais eram civis armados, que receberam ordens de imigrar para cá por Lumópolis, bem como toda sorte de descendentes dos semi-humanos e Aurorians. Inicialmente, o governante de Lumópolis pretendia que Cidade Gannon fosse usada como isca para chamar a atenção dos Eclipsitas, e, portanto, fornecia apoio limitado. Esses bravos soldados e cidadãos comuns enfrentaram vários desafios por causa do ambiente hostil, ameaças Eclipsitas, e até a própria Lumópolis.\nApesar das circunstâncias avassaladoras, nossos antepassados nunca se renderam. Graças aos incansáveis esforços dos muitos cientistas e pesquisadores, que lutaram para combinar o conhecimento de Luminática com a tecnologia antiga escondida na Cidade Baixa de Gannon, Illumina criou vários tipos de tecnologia Lúmina para enfrentar a ameaça Eclipsita. Com o tempo, nosso conhecimento tecnológico ultrapassou o das outras cidades-Estado. Hoje em dia, nossa tecnologia até ultrapassa a de Lumópolis, nosso antigo lar.\nPor esses motivos, cientistas e pesquisadores são membros muito respeitados na sociedade da Cidade Gannon. Em circunstâncias emergenciais, trabalhadores científicos e civis devem ter prioridade na evacuação. Em casos extremos, a proteção de trabalhadores científicos e seu equipamento importante pode ser altamente priorizada.",
  str_dispatch_book_chaptercont_10000_3 = "I. O Exército Tem Prioridade\nNão pense na Cidade Gannon como um abrigo subterrâneo, mas como uma fortaleza impenetrável. Como base de operações em nossa luta contra a ameaça Eclipsita, todos os aspectos da vida aqui foram desenhados para priorizar as funções normais das atividades militares. Com a Cidade Gannon como modelo, acreditemos que todos os assentamentos dentro da Federação Illumina devem seguir sua filosofia: o exército tem prioridade sobre tudo. Se houver um conflito de interesses entre o exército e outros aspectos da vida (assuntos domésticos e estrangeiros, qualidade de vida dos cidadãos, pesquisa científica, etc.), prioridade e apoio incondicionais serão dados ao exército.\n\nII. A Divulgação da Ciência\nDeve ser observado que, em caso de um cerco Eclipsita à Cidade Gannon, só podemos contar com nós mesmos para nos salvar. Somente estudando a ciência e as tecnologias de civilizações antigas é que os Aurorians podem melhorar sua eficácia na luta contra os Eclipsitas. Especificamente, isso significa aumentar nosso conhecimento da tecnologia Lúmina. Somente por causa da ciência conseguimos afastar a ameaça Eclipsita, melhorar as condições da Cidade Gannon, fornecer alimentos e armas avançadas a nossas tropas, e alimentar a população com o emprego de tecnologias avançadas. Resumindo, a ciência é nossa arma não somente na luta contra o mal, mas na luta contra os vestígios de nossa ignorância pré-moderna. O espírito da razão e o pragmatismo devem guiar-nos para nosso maior objetivo.\n\nIII. Coletivismo\n“Uma flecha sozinha pode ser quebrada, mas um feixe de flechas jamais se curvará.” Somos uma raça de criaturas sociais, incapazes de sobreviver inteiramente sozinhos, muito menos prosperar. Diante das realidades e ambientes difíceis da vida, só podemos contar com o coletivo, pois só o coletivo pode nos oferecer o apoio do qual realmente precisamos. Quando estiver sozinho em uma cidade estranha, estará protegido por ninguém menos que o enorme coletivo conhecido como Federação Illumina. Portanto, deve evitar perguntar o que o coletivo pode fazer por você, e sim perguntar o que você pode fazer pelo coletivo.\n\nIV. Razão e Praticidade\nAinda que sejamos criaturas capazes de emoções, nosso mundo é pautado na realidade material. Assim, conversas vazias sobre o metafísico devem ser evitadas. A ciência é a base da Federação Illumina, e as bases da ciência são a racionalidade e o pragmatismo calculados. Conjecturas aleatórias, superstições ignorantes, e ilusões de grandeza são inimigos mortais da razão, e provaram, ao longo da história, levar as pessoas à escuridão. Somente a luz da razão pode afastar a escuridão e nos ajudar a não somente enfrentar a realidade, mas melhorá-la.",
  str_dispatch_book_chaptercont_10000_4 = "I. Proteja os Interesses da Federação Illumina\nAo longo da história, somente a Federação Illumina permaneceu à frente da luta contra a ameaça Eclipsita e liderou todos os Aurorians para erradicar os Eclipsitas para a paz mundial. Deve-se melhorar a Federação para atingir o principal objetivo. Assim, todos os membros têm o dever de proteger os interesses da Federação e não se abster, mesmo quando assuntos centrais estiverem envolvidos.\n\nII. Proteja os Interesses Militares\n“A verdade só chega até o alcance militar.” Não se deixe enganar pela paz do presente. Nessa terra, as posições das cidades-Estado são determinadas pela força militar. A Federação foi fundada por militares e solidificou as suas muitas cidades com esse poder. Assim, devemos prestar atenção em qualquer estado com um exército poderoso. Não importa a sua atitude, tais estados são ameaças em potencial para a Federação. Todos os interesses militares devem ser protegidos, direta ou indiretamente, enquanto não entrarem em conflito com o Artigo I.\n\nIII. Proteja os Interesses da Cidade Gannon.\nA Cidade Gannon é o coração da Federação Illumina, assim como a última linha de defesa contra os Eclipsitas. Defender, proteger e desenvolver a Cidade Gannon é a crença que nenhum cidadão de Illumina deveria esquecer. Contanto que isso não contradiga os Artigos I e II.\n\nIV. Proteja os Interesses de Pesquisa\nÉ dever dos pesquisadores de elite desenvolver a tecnologia e explorar teorias científicas. Portanto, cada pesquisador é precioso. E mesmo quando servindo a escritórios diferentes, cidadãos de Illumina devem obedecer às ordens de qualquer pesquisador para realizar tarefas especiais, contanto que não entre em conflito com os Artigos I, II e III.\n\nV. Proteja os Interesses Comuns\nQuando as circunstâncias permitirem, todos os cidadãos de Illumina devem se juntar para proteger interesses comuns, mesmo como coletivos temporários. Sem violar os primeiros quatro Artigos, sempre é necessário priorizar os interesses comuns acima de interesses pessoais.",
  str_dispatch_book_chaptercont_10000_5 = "I. Siga a Programação\nCidadãos de Illumina devem ter senso de tempo. Na vida diária, cada tarefa deve seguir um planejamento. Atrasos impedem o trabalho dos outros. Portanto, a programação deve ser seguida.\n\nII. Seja Honesto\nMentiras não podem existir num coletivo como a Federação. Independentemente da intenção, uma mentira vai com certeza causar danos a outros quando a verdade for revelada, e danos ao interesse coletivo também, talvez irreparavelmente. Ser honesto e falar a verdade é responsabilidade de cada cidadão de Illumina.\n\nIII. Obedeça Ordens\nCada cidadão de Illumina deve obedecer ordens, assim como um braço obedecendo aos comandos do cérebro. Decisões de superiores devem ser completadas sem nenhum desvio, recusa ou mesmo insubordinação.\n\nVI. Continue a Aprender\nA ciência não tem limites, e o conhecimento também não. A Federação busca inovações tecnológicas a todo momento. Cada cidadão de Illumina deve aprender novos conhecimentos para se adaptar a novos ambientes. Não se acanhe por falta de talento ou aptidão. Todo cidadão de Illumina que aprende é um cidadão de verdade.\n\nV. Mantenha a Forma\nUm corpo em Illumina não pertence somente à pessoa, mas também à Federação. Portanto, permanecer em forma é proteger os interesses da Federação. Treinos sensatos para melhorar atributos físicos e uma recusa em desperdiçar tempo com indulgências sem sentido devem estar na mente de todo cidadão de Illumina.",
  str_dispatch_book_chaptercont_11000_1 = "Ada frequentemente sonhava com um véu que, ao ser gentilmente afastado, mostrava duas figuras magras.\nEles colocavam a criança de seus braços em um berço. Então o vento soprava pela janela, e dispersava a silhueta, deixando as palavras “Papai e mamãe estão indo ver o mundo lá fora.”\nConforme Ada cresceu, o sonho ficou mais vívido. Ela podia ver os cabelos castanhos esvoaçantes da mãe, e o queixo ligeiramente pálido do pai. Eles iam embora cada vez mais decididos, seus corpos sempre se fundindo naquela luz maravilhosa. Ada conhecia bem essa luz. Podia vê-la toda noite no céu e sabia que era a aurora.\n“Como é o mundo lá fora? Se eu pudesse pilotar uma Colossus como eles, também poderia sair de Eraveil?” Ada se perguntava.\nUm dia, seu desejo foi atendido. Ela escutou uma voz que vinha das profundezas de Eraveil.\n“As Colossi foram feitas para o céu. Algumas podem estar na terra, e até no mar, mas o céu é o verdadeiro lar das Colossi!”\n“Essas Colossi grandes são idiotas. Poderiam com certeza voar tão alto, mas se confinaram a Eraveil sem nenhuma ambição. Se fosse eu, chegaria até o fim da aurora! Mas não estou com inveja...”\n“Eu me pergunto como seria ter um navegador?”\n“Provavelmente deve ser parecido com ter um amigo,” Ada respondeu, gentilmente.\n“Quem é? Como consegue falar comigo?” A pequena Colossus estacionada nas profundezas de Eraveil ficou surpresa, seu indicador piscando de medo. “Você é um fantasma? Nenhum Celestita viria a esse ferro-velho. Isso não acontece.”\n“Mas eu sou Celestita.” Ada saltou com graça na cabeça da Colossus, que parecia um dragãozinho, e deu algumas pisadas curiosas.\n“Ei, ser Celestita significa que pode bisbilhotar e pisar na minha cabeça? Minha linda cabecinha é proibida para todos!”\n“É linda mesmo. Tem até algumas flores adoráveis nela.”\n“Eu sou linda mesmo! Então, Celestita, por que me respondeu? Nem pense em me pregar uma peça, porque vou lhe explodir pelos ares com minha última reserva de energia!”\n“Você quer voar, não quer?” Ada estendeu o convite. Sempre quis ver o que há fora de Eraveil. Quer vir comigo?\nNo entanto, a Colossus não aceitou a oferta e se encolheu no canto.\n“Bem, eu gostaria, mas sou pequena e não tenho muito espaço. Até minhas asas são minúsculas. Acho que não consigo voar para fora de Eraveil. Não posso mesmo...”\n“Mas você quer.” Ada estendeu a mão para a Colossus e naquele momento, um sentimento profundo perpassou as duas, enquanto se conectavam uma com a outra.\nA Colossus sentiu suas asas se abrindo e voou para o céu, vendo o mundo de cima como uma baleia pulando fora d’água. Juntas, as duas tocaram as estrelas e a aurora.\nO mundo inteiro se desenrolava lentamente diante delas.\n“Ah, meu nome é Ada. E o seu?”\n“Voar no céu e andar como o vento, eu sou Kaz.”",
  str_dispatch_book_chaptercont_11000_2 = "A esfarrapada Kaz e a navegadora novata Ada voaram sem rumo pelo céu. Turbulências fracas as viraram de cabeça para baixo, e com a energia se esgotando, foram forçadas a aterrissar.\n“Eu sabia, não é sensato fazer viagens não planejadas como essa. Agora estou presa ao chão... Afinal, não sou boa em voar! E acho que você também não é boa em pilotar!” Kaz falava com ela por meio da conexão telepática.\nAda esfregou a cabeça que havia batido no painel de controle durante a aterrissagem. O lado direito ainda estava dolorido, mas ela fingiu que não se importava. “Admito que não sou boa, já que nunca tive lições para pilotar Colossi por nunca ter tido guardião.”\n“O quê? Então o que lhe deu coragem de estabelecer uma conexão mental comigo?”\n“Ah, acho que foi instinto.” Ela se levantou novamente. “Mas confie em mim, acho que tenho um talento natural.”\n“Você é ainda mais egoísta do que eu! Porém acho isso admirável... Mas eu com certeza não voarei novamente. Prefiro ficar enterrada na sujeira a explodir no ar. Deveria ficar esperando no ferro-velho até que alguém viesse me desmontar, não ficar até os joelhos numa floresta desconhecida como essa...  É assustador aqui! E molhado! E tem tantos cogumelos estranhos...”\n“Sem contar os visitantes inesperados.”\n“Criaturas” com armas nas mãos atacaram Ada de todas as direções.\nKaz, tensa, fechou os olhos.\nCelestitas não combatentes, como Ada, eram alvos fáceis, destinados a serem cercados por esses monstros. O Lúmina dentro dela se mexeu, enquanto surgia dúvida atrás de dúvida em seus circuitos. Ela sempre tinha sido covarde, não podia voar, não podia ajudar sua navegadora, nem podia manter os olhos abertos enquanto Ada estava em perigo. Ela queria chorar, mas uma máquina como ela podia derramar lágrimas?\nEla ouviu a voz de Ada. “Não tenha medo, Ada. O problema está resolvido. Estamos bem.”\nQuando Kaz abriu os olhos, viu Ada segurando um gato, com diferentes animais caídos à sua volta.\n“Celestitas não são bons lutadores, mas eu sou. Derrubei esses animaizinhos quando me atacaram, então cocei suas barriguinhas. Eles não conseguiram resistir!”\nDessa vez, o gato em seus braços falou. “Que falta de educação! Não somos animais, e sim semi-humanos! Você acabou de amassar nosso cogumelo pérola mais precioso e deve pagar dez milhões de noitium em compensação! Porém, dada a sua técnica de massagem decente, vamos cobrar somente o seu trabalho!”\n“Semi-humanos?” Ada olhou para o gato em seus braços, confusa.\n“Miau. Não sabe de nada? Os que podem ver rastros de luz são Celestitas. Os que não podem ver os rastros, mas conseguem usar o Lúmina, são Aurorians.” O gato se espreguiçou.\n“E o que são semi-humanos, então?”\n“Nos comunicamos por meio da linguagem, somos fortes, mas não temos nada a ver com Lúmina... Ei, coça aqui... Porém nossa grande vantagem é... ”\n“Somos fofinhos demais.”",
  str_dispatch_book_chaptercont_11000_3 = "Viajar sem destino é como ser uma semente de dente-de-leão, vai-se aonde o vento leva.\nA última parada de Ada e Kaz foi uma ruína desolada, na qual encontraram uma compatriota de Eraveil: uma Colossus cheia de flores.\n“Parece estar nas últimas e quase sem energia.” Ada acariciou a gigante idosa, que tremeu e respirou como uma Celestita.\n“Como pode ser isso? Porque não voa de volta para Eraveil? Com certeza podem ajudar!” opinou Kaz, perplexa.\n“Porque não consigo mais encontrar Eraveil. Nem mapa nem sistema de navegação podem me impedir de me perder...” A pobre Colossus abriu lentamente os olhos. “Pode-se dizer que esse é meu lar agora.”\nAda sentou-se diante da Colossus.\n“Pode me contar sua história?”\nA gigante levantou a cabeça. “Meu navegador e eu chegamos a essa floresta, em que conhecemos outra raça, os Aurorians.”\n“Ei, são eles que podem controlar Lúmina! Podem atirar água com as mãos apenas com a força do pensamento!”\n“E daí? Podem voar? Se tem que se impressionar, fique impressionada com o quão poderosas as Colossi são.” Kaz murmurou, sem ligar nem um pouco para os Aurorians(Colossi ou Colossus?).\n“Meu navegador foi aceito pelos Aurorians e morou com eles, mas mesmo assim se sentia solitário. Celestitas são diferentes de Aurorians, e aqui não é o lar dele. Logo quando decidiu ir embora, no entanto, Eclipsitas atacaram a vila.”\n“Eclipsitas!” O coração de Ada acelerou, sua mente cheia das imagens aterrorizantes de um monstro da cor das cinzas surgindo da escuridão, rugindo e todo manchado de sangue, correndo em sua direção. No momento em que a lâmina estava a apenas um centímetro de cortar sua garganta, a imagem se dissipou.\n“Meu navegador sacrificou a vida para ajudar os Aurorians locais. Por fim, eles venceram, mas a área ficou completamente manchada pelo Fluxo Escuro e se tornou inabitável. Os Aurorians que ele protegeu retornaram e deixaram flores para ele, as mesmas que pode ver proliferando em mim agora.”\nAda e Kaz ficaram em silêncio. Queriam consolar a Colossus, mas não sabiam o que dizer.\n“Não fiquem triste, jovens. Nunca me importei com as flores em mim, nem me arrependi de esperar o pouco que resta de energia drenar de mim, pois posso sentir vidas acordando em meu corpo. As flores magníficas são provas da gratidão dos Aurorians pelo meu navegador e meu tributo a ele.”\nA Colossus finalmente fechou os olhos e encerrou a conexão mental com Ada.\nAs flores eram o único sinal de vida na ruína. Ada lembrou de seus pais e Eraveil. Ela murmurou, “Será que é realmente a escolha certa ver o mundo exterior? Ou é totalmente errada?”",
  str_dispatch_book_chaptercont_11000_4 = "“A areia cobre tudo aqui. Se ficarmos aqui, meu exterior vai se tornar imundo, com certeza... Ai, a areia também está quente!”\nAda e Kaz voaram para um deserto e fizeram uma parada.\n“Muito bem, Kaz! Não podemos ver tudo isso sem você!”\nO sol causticante acima cozinhava o ar. Dunas de areia se estendiam para sempre. Mesmo uma Colossus era apenas um pequeno grão de areia no deserto. Era uma visão que só podia ser contemplada ao deixar Eraveil.\n“Não pode ver isso sem mim? Sim, sim, é verdade! Sou uma ótima Colossus! Então um deserto é assim! Mas não há ninguém por perto.”\n“Mas o que é aquilo ali?”\nUma comoção se iniciou no deserto outrora quieto.\n“É uma nave? Está vindo para cá e vai bater na gente!”\nA pobre Kaz estava desconfiada desde o começo da viagem, e acabava de ser atingida por uma nave viajando pelo deserto.\n“Ai!” Kaz berrou. A nave a acertara bem nas asas.\nO capitão da nave cambaleou para fora do veículo, segurando a cabeça.\n“Como vão... Uau, foi uma batida e tanto. De qualquer forma, sou o líder dos Astroviajantes. Somos nômades Aurorians explorando a maravilhas do mundo em nossa aeronave.”\n“Li nos arquivos que naves navegam no oceano. Como pode haver uma nave no deserto?” Ada olhou para o capitão, confusa.\n“Isso são navios, veja isso aqui.”\nAda abaixou a cabeça na direção em que o capitão apontava. A areia abaixo de seus pés foi levada com o vento, revelando um “céu”. Ainda mais incrível é que viram um planeta único nele.\n“Esse é nosso mundo, Eoria,” explicou o capitão.\n“Parece um biscoito esfarelado em uma tigela de água,” Kaz murmurou.\n“É. E o biscoito esfarelado é Astra. Em um lado desse mundo perpetuamente dia, no outro, perpetuamente noite. Vivemos na linha fina entre eles.”\n“E pretende explorar as maravilhas do mundo em uma nave imunda como essa?”\nO capitão coçou a cabeça. “Pode estar suja, mas por dentro é bem luxuosa. E temos a melhor tripulação. Nosso mecânico, por exemplo...”\nUm Aurorian no navio balançou um martelo, como se demonstrasse suas habilidades, e acabou fazendo um buraco na nave. Outro Aurorian tentou pular graciosamente da nave, mas caiu de cabeça na areia.\n“Que vergonha!” O capitão revirou os olhos, mas rapidamente retomou a compostura. “Desbravar novas trilhas e buscar o desconhecido é o que fazemos.”\n“Todos os Aurorians são curiosos assim?”\n“Pessoas normais não navegariam na areia.”\n“Areia?” Ada olhou para baixo e viu que a galáxia a seus pés estava novamente coberta de areia. Quando olhou para cima, a nave havia desaparecido.\nOs Astroviajantes teriam sido um sonho ou existiam mesmo?",
  str_dispatch_book_chaptercont_11000_5 = "Ada se sentou na ponta de Azurita enquanto Kaz se escondia nas nuvens.\nO tempo tinha voado. Já fazia tempo desde que haviam deixado Eraveil. Um dia, um mês, um ano... Ou talvez vários anos. Memórias de Eraveil haviam se tornado vagas para Ada.\n“Ainda se lembra de como era em Eraveil, Kaz?”\n“Claro que sim, sou uma Colossus. Vou checar os arquivos... Ei, onde estão os arquivos sobre Eraveil? A informação nova que eu guardei apagou a antiga? Não pode ser... minha capacidade não pode ser tão patética!”\n“Lembro de uma torre branca. Também há estruturas altas e brancas em Azurita, mas não é a mesma coisa. Pássaros pousavam na torre em Eraveil, e abaixo dela há uma floresta com dentes-de-leão.”\n“Por que estabeleceu uma conexão comigo e me tirou de Eraveil, Ada?” Kaz seguiu Ada e olhou para o horizonte. Podiam ver deserto, planície, geleira, vulcão e até o mar, algo que não poderiam ver sem deixar Eraveil, mas às custas das lembranças de lá.\n“Só queria encontrar as duas pessoas, meus pais, dos sonhos que tinha. Eu provavelmente parecia relaxada, mas é porque odiava minha vida em Eraveil. Pensava que qualquer outro lugar seria melhor do que lá. Meus pais me abandonaram em Eraveil. Não conseguia me enturmar com as outras pessoas e ficava sozinha o dia todo. Era horrível.”\n“Eu sentia o mesmo... Acordei e percebi que era uma Colossus incompleta. Supostamente, eu era um fracasso e nunca poderia voar. Meu destino era esperar minha energia acabar no ferro-velho. Sair de lá era pelo menos melhor do que morrer lá, pensei. Estranhamente, agora sinto falta daquele lugar.”\n“Eu também. Não sei quando, mas parei de me importar com encontrá-los. Eles devem estar vivendo a própria vida, e eu tenho a minha. Voar com você é muito mais interessante do que tentar resolver um mistério sem sentido.”\n“Você realmente acha isso? Eu não esperava! Uma Colossus consegue processar isso? Não tenho nada sobre isso nos meus arquivos!”\nPor que não posso me sentir assim? Somos parceiras, o que é mais do que uma relação superficial.\" Ada fechou os olhos e se concentrou na conexão. \"Consegue sentir?\"\n\"Eu... Consigo sentir. Posso sentir o que está pensando, Ada. Você está pensando...\"\n\"Eraveil. Acho que é hora de voltar para onde nos conhecemos.\"\nAntes que as memórias se apagassem completamente.",
  str_dispatch_book_chaptercont_12000_1 = "Por várias vezes eu sentei-me às margens do Rio Áureo, observando o sol mover-se lentamente pelo céu.\nAs águas gélidas banhavam minhas pernas, e eu sentia meu estômago dar um salto. O pai de Sif pescava no rio com sua rede. Ele costumava olhar para nós com um sorriso no rosto, suas mãos atrás das costas, mas eu sabia que suas palmas estavam cobertas de calos marrons. Sif corria descalça de um lado a outro da margem. Ela depositava os mexilhões que colhia em uma grande pilha ao meu lado, e então me pedia para abri-los com minha faca e remover a carne enquanto mergulhava no rio para lavar os cortes provocados pelo cascalho em seus pés.\nO sol brilhava intensamente sobre nós.\nNada era tão difícil quanto ir até a casa de Sif para cear. Eu tentava com muito esforço comer na mesma velocidade que ela, porque considerava rude terminar minha refeição antes ou depois.\nA mãe de Sif era gentil e me dava peixe seco e bacon para levar de volta para o meu pai embriagado.\n\"As coisas seriam mais fáceis se sua mãe ainda estivesse viva\", dizia.\nA mãe de Sif gostava de pentear meu cabelo embaraçado usando os dedos. Seus olhos estavam sempre cansados, e ela parecia olhar através de longas distâncias para alguém completamente diferente.\nEla e minha mãe eram boas amigas, como Sif e eu. Quando minha mãe morreu, meu pai e eu só sobrevivemos graças à sua boa vontade.\nMeu pai me dizia para colocar a comida na mesa bamba de madeira e ir lavar minhas roupas. Quando ele caía no sono, eu procurava suas garrafas escondidas.\nElas espalhavam-se por toda parte. Embaixo da cama, nas pilhas de roupas, nas cinzas do fogão...\nEu sempre as lavava no rio e amarrava um fio da rede de pesca em seus pescoços, laçando-as em grupos de dez. Havia dois pregos fixados em cada lado das janelas do quarto, e era lá que eu pendurava as garrafas. O sol refletia em cada uma delas, e as garrafas produziam um som cristalino enquanto batiam umas nas outras.\nAté aquele dia, esse era meu único divertimento.\n(continua)",
  str_dispatch_book_chaptercont_12000_2 = "Lembro que era um dia sombrio. O vento soprava folhas e poeira em espiral no ar.\nPodia-se ouvir os sinos dos cavalos à distância, e as crianças encostavam as orelhas no chão para ouvir os cascos. Era uma caravana! Tinham parado em um campo desocupado fora da cidade, armaram uma grande tenda branca e arrumaram os bens lá dentro.\nAo ouvirem a agitação, muitos aldeões correram para o local para dar uma olhada. Sif e eu nos enfiamos na multidão. Ela agarrou forte a minha mão, e eu senti o nervosismo e o entusiasmo se espalharem pelos meus ossos e pele até meu coração.\nO ar estava cheio com o fedor de esterco de cavalo, mas apesar da longa viagem, as roupas dos caravaneiros estavam brilhantes, seus rostos limpos e cheios de vigor. Naquela época, eu não sabia que era por conta da Luminática.\nAs notícias logo se espalharam que os caravaneiros trocavam grãos, lã e chifre por roupas finas e cerveja. Alguns comerciantes foram até a vila e ficaram em pousadas que não recebiam hóspedes desde o último semestre. Em pouco tempo, o odor de ervilhas cozidas exalava das janelas.\nOs mercadores de roupas anunciavam seus produtos, pendurando o tecido nos braços e desdobrando-os para exibi-los aos espectadores. Branco neve, verde pavão, azul safira, vermelho pôr-do-sol... Foi a primeira vez que eu via cores tão vibrantes.\nSif me disse que queria trocar as peles de lobo que ela pegou no inverno passado por um vestido branco. Foi aí que pensei nas garrafas de vidro penduradas na minha janela.\n\"Preciso pelo menos tentar\", pensei.",
  str_dispatch_book_chaptercont_12000_3 = "Quando Sif e eu voltamos para casa, ela pegou as peles, enrolou-as firmemente em um pacote e as colocou debaixo do braço. Enquanto eu caminhava, a corda de garrafas nas minhas mãos tilintava uma alegre melodia. Esses simples objetos eram nossos tesouros.\nSif estava tão animada. Quase parecia que ela saltitava em direção à caravana, mas as garrafas eram pesadas e frágeis, então eu seguia devagar atrás. Eu sentia como se todos estivessem olhando para nós. Eu nunca tinha sido o centro das atenções, e por um momento me senti muito feliz.\n\"Pelo que você quer trocar essas coisas?\", perguntou o perplexo comerciante, a medida que caminhávamos em sua direção.\nEu não entendi o que ele quis dizer. Simplesmente estiquei meu pescoço ansiosamente para olhar para a cornucópia de mercadorias dispostas atrás dele, muitas e muitas vezes.\n\"Não aceitamos garrafas de vinho\", afirmou ele simplesmente. Por fim, ele perguntou, \"São só garrafas de vinho comuns?\"\nNaquele momento, senti um zumbido repentino nos ouvidos e meu constrangimento me paralisou. O sol acima da minha cabeça parecia estar batendo como um tambor. Mesmo o som das minhas garrafas batendo uma na outra se tornou insuportável.\nAs garrafas eram pesadas demais, e minha mão começou a tremer com peso da corda que as prendia. Suor começou a escorrer pela minha nuca e pela parte de trás das orelhas, mas eu ainda não conseguia fazer meus pés se mexerem.\nDe repente, ouvi uma voz baixa à minha direita,\n\"Garota, pelo que você quer trocar essas garrafas?\"\n(continua)",
  str_dispatch_book_chaptercont_12000_4 = "Foi quando conheci o Sheriozha. O brilho do sol em sua armadura de prata era ofuscante.\nNa época, Sheriozha tinha trinta e poucos anos e tinha sido contratado como guarda da caravana. Ele tirou o elmo, revelando uma franja marrom suada e uma barba espessa e áspera, e sorriu para mim com dentes brancos como pérolas.\nEle queria minhas garrafas e em troca me deu num tipo de pão branco chamado \"Ração Biscoito de Lumópolis\". Ele me disse que são feitos especialmente para soldados de Lumópolis, e eu o embrulhei com a ponta da minha saia.\nEu tinha conseguido uma coisa realmente incrível! Meu constrangimento desapareceu.\nSheriozha pegou uma garrafa da corda e segurou na mão. Ondas cintilantes de calor surgiram da mão que segurava a garrafa, que se contraiu e se retorceu.\n\"Você gosta de cachorrinhos? Eu gostava quando criança\", ele disse.\nSheriozha abriu a mão, revelando dentro dela um cachorrinho de vidro sentado. Mas mais do que isso, eu estava curiosa sobre as ondas de calor que subiam pelo ar. Sheriozha percebeu minha animação e sorriu.\n\"É Luminática. Quer aprender?\"\nA caravana permaneceu por três dias, e foi como se toda a vila tivesse voltado à vida. As chaminés cheiravam a carne defumada, as crianças corriam descalças pelas ruas, os velhos pegavam suas bengalas e saíam mancando de suas casas escuras, e mesmo as águas do Rio Áureo pareciam menos frias. Sheriozha sentava na praça da vila e tentava me ensinar Luminática. Sif sentava do meu lado, acompanhando a aula ou às vezes cochilando no meu ombro.\nSheriozha gostava de passear à cavalo pela aldeia depois do jantar, e Sif e eu o acompanhávamos. Ele quase nunca tirava a armadura ou a espada e escudo que ele levava amarrados.Uma vez, eu corri na frente, bati no escudo entalhado, e perguntei o que era.\n\"É um escudo torre\", ele me disse. \"Um símbolo dos Cavaleiros Lumo\".\nTrês dias depois, a caravana foi embora, e Sheriozha se despediu de nós.\nPassado um mês, finalmente consegui fazer uma bola de água do tamanho de um punho na minha mão.\nEu havia ganhado um novo destino.",
  str_dispatch_book_chaptercont_12000_5 = "Três meses depois que o Sheriozha foi embora, alguém bateu na minha janela.\n\"Com licença, a Mina mora aqui?\"\nDuas bochechas rosadas e um par de rabos-de-cavalo louro-claro estavam pressionados contra a janela. Ela me viu, piscou os olhos verde-oliva e virou para sua mochila. Ela então tirou um pequeno livreto encadernado em couro. Duas asas verde-esmeralda projetavam-se de suas costas, as lustrosas penas brilhando ao sol, e seus dedos batiam no emblema preso ao livreto.\n\"União Mensageira\", disse ela lenta e claramente.\nApós confirmar que eu era a pessoa certa, ela me entregou um pacote embrulhado em papel impermeável, deu dois passos para trás, e abriu as asas. A poeira subiu enquanto ela girava em círculo, então ela acenou para mim, e logo ela havia sumido.\nEu rasguei o pacote e dentro havia uma carta e um presente do Sheriozha. A carta era curta, e só mais tarde, depois que aprendi a ler e escrever, eu soube que estava cheia de erros. O presente era um dente-de-leão, um caule fino sustentando uma bola branca de penugem. Um bom tempo depois, aprendi que a flor era da longínqua Eraveil.\nSheriozha continuou a mandar pacotes com vários presentes: linguiças de Northland, figuras de madeira da Rainha Bethlehem, balas encravadas com a insígnia da estrela dupla de Illumina, doces que você podia soprar como um apito, petisco crocante com sabor estranho, e uma vez, até mandou o olho de um Eclipsita.\nCada carta era um mensageiro diferente que trazia, mas todos tinham algum tipo de característica semi-humana, como asas, chifres, presas, ou manchas. Quando me acostumei com esses mensageiros, tentei conversar mais com eles. Por fim, até pedi que me ajudassem a ler as cartas.\nIndependentemente da aparência, eles sempre eram o ponto alto do meu dia.\nO último pacote do Sheriozha foi enviado de Lumópolis. Quando abri, caiu um desenho de dentro. Era um desenho dele, em pé em uma varanda espaçosa com o céu atrás dele. Logo adivinhei que o local era Lumópolis. Ele havia me dito que a cidade foi construída na ilha flutuante de Azurita, onde viviam os Aurorians. Foi o último pacote que recebi do Sheriozha.\n(continua)",
  str_dispatch_book_chaptercont_12000_6 = "Seis meses depois, enquanto meu pai estava em um de seus torpores raivosos e inconsequentes, peguei minha mochila e sai de casa. Dentro havia apenas um pouco de comida. O resto do espaço foi ocupado pelas cartas e presentes do Sheriozha. Seguindo as orientações que os mensageiros me deram, logo cheguei no correio da União Mensageira.\nAlguns mensageiros me reconheceram. Expliquei a degeneração do meu pai com certo exagero, por precaução, e eles concordaram em me acolher, em troca de ajuda na separação de correspondências e outras tarefas. Durante esse tempo, aprendi a ler e escrever. Li as cartas do Sheriozha várias e várias vezes, e, embora sua escrita fosse confusa, eu ainda conseguia entender o que ele queria dizer. Ele raramente descrevia suas viagens, mas frequentemente escrevia sobre sua juventude. Apesar de ter nascido em Lumópolis, ele era pobre como eu, e eu sentia que ele tentava me confortar. Afinal, ele era um Cavaleiro Lumo, e todas as suas dificuldades só o tornaram mais forte. Depois de um tempo, comecei a responder suas cartas. Enviei para o endereço da sua última carta, mas não recebi resposta.\nSif e sua mãe me encontraram quando foram para a cidade.\nEla segurou meu braço e não soltou, chorando e lamentando pelo tanto que se preocupou comigo. Eu não conseguia falar, mesmo para pedir desculpas, e apenas enxuguei as lágrimas de seu rosto.\nPor fim, Sif limpou o rosto com a manga e soluçou uma palavra.\n\"Olha\".\nEla fechou os olhos, e relâmpagos ofuscantes brilharam ao seu redor, perfurando o ar.",
  str_dispatch_book_chaptercont_12000_7 = "Eu havia tentando me juntar à União Mensageira, mas fui rejeitada.\n\"Mina, você é nova demais\".\n\"Você não é rápida o bastante. Não é culpa sua. É só que... Você só consegue correr com os pés\".\n\"É perigoso demais. Um deslize e você vai se machucar\".\n\"Você já encontrou um Eclipsita? Eu já\".\n\"O pagamento não é muito bom, de qualquer forma\".\n\"É, isso é o principal\".\nAinda que eles reclamassem que o trabalho tinha todos esses problemas, eles entregavam suas caratas com um largo sorriso no rosto todos os dias.\nOs mensageiros não cederam, então eu tive que deixar o assunto de lado e voltar à separação de cartas, na esperança de encontrar uma carta do Sheriozha. Mas isso também não deu certo.\nDepois que a Sif aprendeu Luminática, seus pais permitiram que ela fosse à cidade sozinha. Nós sentávamos com os mensageiros debaixo sob o carvalho em frente ao correio, e bolotas caíam nas nossas cabeças. Eu adorava perguntar aos mensageiros sobre Lumópolis, especialmente sobre os cavaleiros, mas eles não explicavam muito.\n\"Os cavaleiros são poderosos, especialmente a Luminática deles\".\n\"Uma vez eu fiz uma entrega pra uma Cavaleira Lumo. Ela era o cúmulo da elegância, mesmo abrindo uma carta\".\n\"Você sabe mais alguma coisa?\", eles perguntavam uns aos outros.\n\"Não conheço muitos deles, pra falar a verdade\".\nSif se recostou com as mãos como apoio, a luz do sol infiltrando-se pelas folhas e dançando em seu rosto voltado para cima. \"Eu gostaria de vê-los eu mesma\".\nNão sei se esse foi o momento decisivo, mas eu tinha me decidido.\nEu veria todos os lugares com meus próprios olhos: Lumópolis, Eraveil, a Subcidade de Illumina, o Deserto Rediesel, Umbraton, e até mesmo o Território Secreto.\n(continua)",
  str_dispatch_book_chaptercont_12000_8 = "Talvez isso fosse mais do que apenas querer se livrar dos grilhões da terra que minha curiosidade havia superado. Minha partida teve um significado mais profundo para mim—era a chance de alcançar e tocar o próprio propósito da vida. Como Sheriozha, eu não nasci para suportar uma vida de monotonia e sonhos não realizados.\nQuando completei dezessete anos, Sif e eu finalmente fomos viajar juntas. Eu tinha proposto que nosso primeiro destino deveria ser Lumópolis, e Sif concordou.\nViajamos o Rio Áureo acima em um frágil barco de madeira, batendo de um lado para o outro na correnteza durante meio mês antes de chegar à curva mais próxima de Lumópolis.\n\"Azurita!\"\nSif levantou o braço e apontou para o céu. Protegi meus olhos da luz com a mão e olhei na direção que ela apontava. Foi então que eu vi—uma ilha flutuante, como um chapéu redondo com topo cônico, flutuando sobre as terras devastadas do leste, majestosamente iluminada pelo sol ofuscante.\nQuanto mais nos aproximávamos, mais aparente sua grandeza e autoridade se tornava para nós. Ao entrarmos em sua sombra, uma onda de ar frio nos envolveu. Sombras são muito frias para Aurorians.\nO centro de transporte é o único lugar onde se pode entrar e sair de Lumópolis, e se você quer acessar a cidade, deve ir por aeronave. Mas Sif e eu não tínhamos nem as credenciais necessárias para embarcar na aeronave, então fomos convidadas a nos retirar de Lumópolis.\n\"Todos os viajantes precisam solicitar a aprovação do Departamento de Relações Exteriores para entrar em Lumópolis!\"\nSif perguntou, \"Quanto tempo leva pra conseguir a aprovação?\"\n\"De quinze a trinta dias\".\nObviamente, não tínhamos dinheiro suficiente para ficar lá tanto tempo. Até a passagem da aeronave era mais do que podíamos pagar. Sem outra opção, demos a volta e fomos embora.\nEnquanto dávamos sugestões para o nosso próximo destino, Sif disse com raiva, \"Aonde quer que você queira ir, certifique-se de que seja um lugar que não precise de nenhum tipo de aprovação para entrar!\"\nEntão decidimos que nosso próximo destino seria Northland.\nMas no caminho para Northland, o destino dos ofereceu uma chance de entrar em Lumópolis de graça.",
  str_dispatch_book_chaptercont_12000_9 = "Após sair do porto de Lumópolis, fomos em direção ao norte. A estrada parecia não ter fim. Foi aí que vimos uma mensageira ferida que tinha encontrado um Eclipsita no seu caminho para Lumópolis. Após a Crise Darkover, Eclipsitas podem ser encontrados com frequência aventurando-se no interior. Ela caiu da parte de trás de uma rena. Suas asas e a parte inferior da perna manchadas com sangue vermelho vivo pingando no pelo da rena.\nSif e eu a levamos para o correio mais próximo, onde outros mensageiros curaram suas feridas com Luminática. Para mostrar sua gratidão, ela sugeriu que descansássemos no correio por alguns dias. Por fim, surgiu o assunto da nossa tentativa fracassada de entrar em Lumópolis. “Há restrições rígidas para todas as cargas e viajantes que entram em Lumópolis.” Ela nos olhou com um sorriso, “mas a União Mensageira não transporta cargas, e não somos viajantes”.\n“Temos permissão especial para entrar e sair de Lumópolis. Tudo que precisamos fazer é mostrar o comprovante de identificação para os guardas.\"\nEla tirou alguma coisa do bolso, um caderno que eu tinha visto várias vezes no correio próximo à minha terra natal. Mensageiros geralmente registram suas viagens. Estava afixado com dois distintivos, gravados com a imagem de uma caneta de pena flutuando.\nEla removeu os distintivos e os alfinetou nos nossos peitos. “Com eles, vocês poderão entrar e sair de Lumópolis livremente. Eu posso emprestá-los temporariamente, mas vocês não podem contar pra ninguém.”\nSif e eu seguimos a mensageira para Lumópolis e embarcamos na aeronave exclusivamente reservada para o pessoal da união.\nAssim que saímos, minha mão recaiu sobre um pedaço de papel enrolado no meu bolso. Foi a última coisa que Sheriozha me mandou.\n(continua)",
  str_dispatch_book_chaptercont_12000_10 = "O centro de transporte vai para Umbraton. As pessoas o descrevem como a área mais caótica, barulhenta e perigosa da nobre Lumópolis. Mas eu sabia que eles tinham usado os adjetivos errados na primeira vez que o vi. Era certamente a área mais vivaz, excitante e vibrante de Lumópolis.\nAssim que chegamos ao centro de transporte, fomos acolhidos por todos os tipos de tavernas, cafés e lojas de joia. O ar estava coberto com a fragrância dos temperos, cerveja e sementes de cacau. Sif até espirrou no meio da rua, seus sentidos aparentemente sobrecarregados por este ataque olfatório repentino. Os Aurorians andavam de mãos dadas pelas ruas, e seus saltos batiam contra as pedras da calçada, formando uma melodia contínua e nítida. Os assistentes das lojas, que ficavam na frente delas, estavam bem-vestidos e igualmente bem-comportados, segurando calmamente lenços entre seus dedos que pareciam cobrir pedestres inocentes com uma gama de fortes fragrâncias.\nEsta era a terra natal de Sheriozha.\nEnquanto Sif pressionava seu nariz contra a janela da loja e olhava um lindo colar suntuoso pendurado no busto de um manequim, eu perguntei a um Aurorian sentado no degrau e bebendo cerveja pelo endereço que Sheriozha me deixou.\n“Fica nas favelas”, ele disse. Ele estava um pouco bêbado, e seu bigode coberto de espuma branca. Ele levantou seus olhos e olhou para mim: “Por que está indo para lá, garotinha?”\nEu disse a ele que estava procurando um cavaleiro.\n“Um cavaleiro?”, ele balançou a cabeça e sorriu: “Que tipo de cavaleiro ia morar naquele lugar?”\nSenti minha expressão rígida por um momento, mas tentei esconder minha ansiedade. Eu argumentei: “Ele tem um escudo de torre concedido somente a um cavaleiro!”\n“Um escudo de torre?” Conforme ele torcia as palavras em volta da sua boca por um momento, eu temi que ele estava se preparando para dizer alguma forma de crítica ofensiva, mas ele falou: “De fato este é um item que somente um cavaleiro carrega. Onde você o conheceu, garota?”\nEu senti que devia acabar com a conversa aqui. Mesmo assim, não podia tolerar sua atitude arrogante, então descrevi como Sheriozha se vestia, como ele escoltava a caravana e sobre sua Luminática.\n“Ele escolta caravana?”, ele zombou de repente: “Nenhum Cavaleiro se sujeitaria a escoltar uma caravana!”",
  str_dispatch_book_chaptercont_12000_11 = "Eu não sei como exatamente eu sai do centro de transporte. Quando me recuperei do meu estupor, percebi que Sif estava acariciando minha cabeça conforme eu agarrei o braço dela bem forte. Ela gritou meu nome com dentes cerrados: “Mina! Você tá me machucando!”\n“Desculpa”, disse enquanto a soltava rapidamente.\nSif esfregou seu braço e levantou seus olhos para olhar as fileiras de casas de muro branco na montanha. Ela me perguntou: “Você tem certeza que estamos indo pro lugar certo?”\nEu vi uma placa alguns passos a diante, fui para a frente para olhar e verifiquei que de fato este era o endereço que Sheriozha escreveu no envelope.\nApós andar em uma rua com pequenas casas espalhadas, nós nos perdemos. A parede externa da casa atrás da estrada estava coberta de pegadas e grafite. A estrada abaixo de nossos pés não era mais formada de uma calçada uniforme de ardósia, mas agora era um caminho enlameado grosseiro. Olhos estranhos e desconfiados lançaram-se, olhando para nós na sombra. Sif pegou meu braço e me perguntou: “Por que você não pergunta pra alguém o endereço exato?”\nMinha ansiedade anterior ainda continuava na minha mente, e eu tinha medo de revelar todos os segredos do meu coração assim que eu abrisse minha boca para alguém.\nMas Sif não estava nem aí. Ela viu uma mulher voluptuosa passando, deu um passo à frente e perguntou se ela conhecia Sheriozha.\n“O que você ia querer com aquele inútil?” Ela fez uma careta que preencheu cada bela linha do seu rosto com desprezo. “Talvez se você puder pagar o que ele me deve, eu posso te dizer onde ele está.”\nSif não entendeu o que a mulher estava falando. “Há mais alguém chamado Sheriozha que mora por aqui?” ela disse. E, em seguida, descreveu Sheriozha para a mulher com entusiasmo.\n“Garota, você esqueceu de um detalhe”, disse um nômade sentado em uma esquina enquanto levantava um dedo sujo para Sif e sorria para nós com uma boca quase cheia de dentes amarelos. “Você também devia mencionar que ele tem uma perna esquerda estropiada.”\nEu puxei Sif para perto de mim e sai.\nApós andar por um tempo, eu perguntei a alguns dos Aurorians ao lado da estrada sobre Sheriozha. Mesmo assim, a reação deles foi quase a mesma. Sheriozha fez bastante dívidas de jogo, revendeu equipamento que pertencia aos Cavaleiros Lumo e depois foi pego pela força de segurança pública, ficando com uma perna estropiada após lutar com os soldados.\n“Uma vez, quando ele estava bêbado, ele se gabou pra mim que fez um grande negócio. Sabe o que era? Era o escudo de torre e a blindagem de Cavaleiro Lumo! Era como se ele estivesse procurando problema!”\n“Quando ele era jovem, ele queria se juntar aos cavaleiros, mas como ele possuiria uma posição tão nobre!?”\n…\n“Desça o morro. Tem uma taverna no fim da estrada. Geralmente você o encontra lá.”\nFinalmente, alguém nos disse onde podemos achar Sheriozha.\n(continua)",
  str_dispatch_book_chaptercont_12000_12 = "Sif me perguntou: “Você quer dar uma olhada?”\nEu aquiesci, e com uma expressão séria, respondi: “Não sei. Eles devem ter se enganado.”\nDescemos o morro e finalmente vimos a taverna dilapidada. Vários homens de alturas diferentes estavam encostados na parede de fora com várias ferramentas penduradas em suas cinturas. Suas mangas estavam dobradas até os cotovelos, e eles seguravam canecas de cerveja, feitas de madeira, nas suas mãos enquanto conversavam alto.\nSentado de perna cruzada contra a parede estava um homem desarrumado com cabeço castanho cacheado e uma barba, que cobria a maior parte de seu rosto. O homem colocou suas mãos no chão, se inclinou para frente e sorriu para os outros enquanto dizia: “Ei, Will, me dá um gole?”\nUm homem com aparência forte e com cabelo preto o chutou e riu: “O estropiado quer uma bebida?”\nO homem de cabelo castanho protestou de forma estranha e moveu sua perna ruim com sua mão. Depois, sentou-se contra a parede, mas o sorriso no seu rosto sujo permaneceu. Ele esticou sua língua e lambeu seus lábios rachados, encarando as canecas nas mãos dos outros homens. Sif me perguntou: “Consegue ver Sheriozha? Eu nem me lembro mais da aparência dele.”\nEu tinha o reconhecido.\nMas não conseguia falar.\nO sol estava bem acima da minha cabeça, e aquele som de tambor aumentou mais uma vez. Senti que meu corpo estava cheio de água turva do Rio Áureo. Batendo e subindo, por minha boca e nariz, e submergindo meus olhos.\n“Não”, eu me escutei dizendo: “talvez devêssemos voltar outra hora…” Esta promessa vazia quase me asfixiou. Era uma mentira. Mas Sif sabia que eu estava desistindo da busca, e ela estava feliz. Ela pegou minha mão e se virou, recontando as coisas estranhas que ela viu no centro de transporte.\nSaímos de Lumópolis naquele mesmo dia.\nDesde então, eu raramente voltei para aquela cidade flutuando no céu.",
  str_dispatch_book_chaptercont_13000_1 = "Havia dois arcos de pedra na entrada do vilarejo. Eles eram feitos de pedras das montanhas empilhadas em camadas. Pinheiros foram colocados em cada lado pra formar a moldura de um único portão, e um laço de seda amarrado a ele fazia barulhos por causa do vento gelado. Viajantes de longe sabiam que haveria abrigo no vilarejo adiante ao ver o portão e era comum ver crianças o escalando, tentando encaixar os pés em pontos de apoio, segurando nos galhos e se esforçando para ver o horizonte. Mas, nesse dia de inverno, alguns jovens escorregaram no arco congelado e se machucaram, e o ancião proibiu as brincadeiras.\nHavia nevado muito na noite anterior e neve quase chegou à altura dos joelhos. O ancião chamou Dorothy e Cruz, deu a cada um uma pá e os ordenou a retirar a neve com os outros habitantes. Alguns usaram Luminática para arremessar a neve para a floresta. Apesar de Dorothy saber como usar Luminática, ela não era capaz de fazer isso. Ela e Cruz seguiram os outros e trabalharam para tirar a neve da estrada. Horas depois, quando anoiteceu, eles devolveram as pás ao ancião, que os deu a mesma quantidade de arenques enlatados de sempre, perguntou se eles ainda tinham comida guardada e ofereceu a Cruz balinhas doces e macias. Cruz guardou os doces no bolso, mas eles caíram por um buraco. Ele se abaixou para protegê-los, mas Dorothy os pegou. Mais tarde, o ancião falou sobre um casal ao sudeste do vilarejo: \"Eles querem filhos e vocês são jovens sem responsáveis. Vocês fariam parte de uma família incrível.\"\nDorothy não respondeu e apenas segurou o bolso do irmão. Ela sussurrou: \"Quando estiver com um problema assim, me avise. Você sabe que eu posso consertar.\"\nO ancião suspirou e se despediu. Os irmãos o agradeceram novamente e foram para casa de mãos dadas.",
  str_dispatch_book_chaptercont_13000_2 = "No caminho para casa, começou a nevar novamente. A escuridão caiu, e só tinha apenas algumas lanternas fracas ao redor. Não muito longe da casa, Cruz correu em direção a ela, mas tropeçou. Ele olhou para cima e viu uma figura sombria deitada na neve. Dorothy seguiu o grito de Cruz, encontrando a figura tossindo e lutando para se levantar. Depois de se certificar de que era uma Aurorian, embora desconhecida, ela chamou seu irmão para ajudar a estranha a se levantar. Eles levaram a Aurorian para um galpão de lenha a alguns metros de distância. Com voz rouca, ela agradeceu, encostou-se na parede e ficou em silêncio. Sob a luz fraca, Dorothy podia ver um punhado de cabelo loiro e seco saindo do capuz da Aurorian, balançando com sua respiração rítmica.\nEra normal ajudar Aurorians estranhos, então Dorothy e Cruz rapidamente se esqueceram disso... Até o dia seguinte, quando a notícia de uma nova residente na vila foi divulgada. Tirando a neve com uma pá, os irmãos notaram que a porta e as janelas da casa velha e malconservada ao lado da deles estavam fechadas, com fumaça subindo da chaminé para o céu azul gelado.\nCruz apontou para o buraco do tamanho de uma banheira no telhado daquela casa e perguntou à irmã: \"Como alguém pode morar em uma casa como essa?\"\nDorothy o agarrou pelo colarinho e o puxou para longe.\nNaquela noite, uma nevasca caiu. Os irmãos, enrolados em cobertores, dormindo ao som do vento uivante e gravetos voando. De repente, houve um estrondo alto, seguido por vários ruídos e batidas, como se algo tivesse desabado. Cruz estremeceu em seu sonho, já Dorothy acordou, sentando e olhando em volta.\nEm pouco tempo, tudo ficou em silêncio de novo, salvo pelo vento que entrava pela fresta da janela. Dorothy esfregou os olhos e colocou a cabeça no travesseiro novamente. Ela acordou, algum tempo depois, com uma batida em sua porta, saiu da cama com cuidado para não perturbar o sono do irmão, foi na ponta dos pés até uma janela com uma lanterna na mão e olhou. Uma figura cambaleante estava do lado de fora, coberta por um cobertor fino, o vento frio batendo em seu cabelo loiro encaracolado.\nDorothy a reconheceu imediatamente, mas não abriu a porta, apenas segurou a lanterna e colocou a cabeça para fora. \"O que aconteceu?\"\nA Aurorian apontou para a velha casa. \"Meu telhado caiu... Você se importa se eu passar a noite aqui?\"\nDorothy parou por um longo tempo, olhou para a escuridão e respondeu: \"Acho que é melhor você falar com o ancião\".\nA loira concordou com a cabeça, agarrou o cobertor e se virou para sair. Dorothy, então, percebeu que ela estava andando descalça na neve. Ela cerrou os dentes e hesitou, antes de finalmente abrir a porta e chamar a mulher em um tom moderado: \"Você... pode entrar\".",
  str_dispatch_book_chaptercont_13000_3 = "Dorothy aprendeu o nome da Aurorian, Martha, que passou a noite junto à lareira, enrolada em seu cobertor. Quando os irmãos saíram pela manhã, viram que apenas metade da velha casa ainda estava de pé. O telhado havia sumido completamente, com tijolos espalhados por toda parte.\nMartha vasculhou as ruínas, primeiro, retirando um par de botas, que calçou depois de remover a neve e a serragem de dentro. Depois de calçar as botas, ela moveu uma viga quebrada para o lado para descobrir uma bolsa de lona preta.\n\"Quer um? É chocolate.\" Martha tirou da sacola algo embrulhado em papel alumínio, mas Dorothy deteve Cruz quando ele estendeu a mão para pegá-lo. Martha deu de ombros, colocou o chocolate de volta na sacola, pegou um pão selado a vácuo e mastigou enquanto a neve caia em cima dele.\nSentada nas ruínas, Martha mastigava, enquanto examinava a casa desabada. \"Vou consertar esta casa assim que puder\", ela jurou.\nDorothy acenou com a cabeça e saiu com o irmão.\nAo ouvir a notícia, o ancião sugeriu que Dorothy deixasse Martha ficar com eles por um tempo, até que a casa fosse consertada. Dorothy não gostou da ideia, mas tinha vergonha de recusar depois que o mais ancião deu um grande pedaço de tubarão fermentado.\nMartha pegou um cavalo emprestado. Todos os dias, ela era vista movendo pedras e madeira serrada da floresta para um estoque atrás da casa destruída. Dorothy quase nunca via Martha pela manhã. Só à tarde ou à noite, quando Martha estava cozinhando ou dormindo junto à lareira.\nNo início, Martha não jantava com os irmãos. Ela apenas se sentava de pernas cruzadas, de frente para a lareira e mastigava o pão, ocasionalmente acompanhada de carne grelhada e sopa de peixe. Dorothy não conseguia se lembrar de como tudo começou; talvez fosse Martha que compartilhou coelho fresco com Dorothy, ou Cruz e Martha sentados de pernas cruzadas perto da lareira, compartilhando balas de goma e chocolate. De qualquer forma, eles acabaram na mesma mesa, desfrutando das refeições juntos.",
  str_dispatch_book_chaptercont_13000_4 = "Martha parou de passar o dia todo no bosque próximo ao vilarejo, e ficou fazendo as refeições. Ela não gostava de comer tubarões frios e arenques enlatados, o que levava a mais ensopados de vegetais, sopas de peixe, espetinhos e purê de batatas na mesa de jantar. No início, Dorothy não queria que Martha cozinhasse, já que Martha é considerada uma convidada, mas comparado à falta de habilidades culinárias de Dorothy, Cruz obviamente gostava mais da comida de Martha. Isso obrigou Dorothy a ajudar Martha durante o trabalho de preparação na cozinha sempre que possível, enquanto secretamente guardava as receitas na memória.\nMartha não se contentava apenas em encher a barriga. Uma vez, ela provou um caldo e comentou: \"Isso provavelmente precisa de mais sal\".\n\"Sal?\" Dorothy pensou por um longo tempo antes de perceber que é um condimento do tamanho de minúsculas bolinhas de neve. \"Isso é muito difícil de conseguir\", disse ela.\nMartha assentiu, pensativa com a resposta.\nNo dia seguinte, quando Dorothy voltou depois de fazer tarefas para o ancião, Cruz puxou suas mangas e a guiou para a cozinha, apontando para um pequeno saco, gritando em voz alta: \"Sal!\"\nDorothy se agachou, passou um dedo nos finos grãos brancos e provou. O salgado espalhou-se por sua língua.\n\"De onde veio isso?\"\n\"Martha trouxe!\" Cruz apontou para trás de Dorothy enquanto Martha se aproximava da cozinha com uma perna de javali na mão.\n\"O sal... foi caro?\" Dorothy, hesitante, perguntou a Martha.\nMartha fez uma pausa antes de responder: \"Não comprei\".\n\"Onde você conseguiu então?\"\nMartha sorriu. \"No lago de água salgada aqui perto.\"\nDurante o interrogatório dos irmãos, Martha revelou como ela conseguiu o sal. Ela seguiu sua presa até o lago de água salgada em uma caçada não muito tempo atrás. Ela pegava a água e a deixava congelar na praia, depois, trouxe a salmoura descongelada para casa, ferveu para obter o sal e, em seguida, filtrou várias vezes para torná-lo comestível. Dorothy e Cruz ficaram cativados com o relato, incomodando Martha mesmo quando ela estava marinando a perna de javali.\n\"Como você sabe tanto, Martha?\" Dorothy perguntou enquanto imitava Martha esfregando sal em toda a carne.\n\"Não é tão difícil\", Martha deu uma resposta um tanto vaga.\nDorothy assentiu consigo mesma, pensando que também não era difícil de fazer.",
  str_dispatch_book_chaptercont_13000_5 = "Foi outro dia normal. Além de retirar a neve com uma pá, o ancião encontrou uma nova tarefa para Dorothy: colocar ovelhas para pastar no bosque. Assim que Martha trouxe mais madeira e pedras, foi direto para a cozinha preparar o jantar. Apoiado na janela, Cruz pôs a cabeça para fora, olhou para os blocos de gelo da velha casa, virou-se e perguntou: \"Você está se mudando, Martha?\"\n\"Em uma ou duas semanas, provavelmente.\" Ela fatiou batatas em uma panela suspensa.\nCruz correu para a cozinha, sentou-se ao lado de Martha, o rosto apoiado nas mãos e a olhou antes de finalmente falar: \"Mas eu não quero que você vá.\" Outra pausa. \"Mas não deixe minha irmã saber que eu disse isso\".\n\"Por que não?\" Martha mexeu na panela com uma concha.\n\"Porque ela disse que não deveríamos depender de adultos... Porque eles simplesmente nos abandonariam depois.\"\nA concha girava e ocasionalmente batia na panela.\n\"Os adultos sempre têm muitas coisas para fazer. Dorothy disse que uma dessas coisas seria mais importante do que cuidar de nós.\" Cruz baixou a cabeça, permitindo que o fogo aquecesse suas bochechas. \"Mas você nunca nos abandonaria, certo?\"\n\"O que aconteceu...\" Martha lutou muito para engolir a pergunta que tinha em mente, antes de olhar ao redor e se perguntar: \"Como Dorothy ainda não voltou?\"\nCruz levantou a cabeça e olhou pela janela. O céu escureceu, com granizo batendo na casa e o frio da vitória uivando.\nO menino começou a entrar em pânico. \"Dorothy... Por que Dorothy ainda não está em casa?\"",
  str_dispatch_book_chaptercont_13000_6 = "Dorothy, trêmula, andou na neve, lutando contra o vento forte a cada passo do caminho. Ela mal conseguia ver o que estava à sua frente e começou a se arrepender de cada decisão que tinha tomado hoje. Depois de pastorear as ovelhas de volta à cidade, ela deveria ter ido para casa e se aninhar perto da lareira. Ela deveria ter percebido que o desvio para o lago seria traiçoeiro no meio do caminho e voltar. Mesmo depois de chegar ao lago, ela deveria ter verificado o tempo e não esperando a água congelar... A nevasca rugia por toda parte. Pior ainda, estava escurecendo. Dorothy olhou em volta e se preparou para o pior: passar a noite aqui na selva nevada.\nCom esse pensamento, ela tateou seu caminho através das pedras, procurando por uma fenda para se abrigar. Felizmente, ela encontrou uma, grande o suficiente para se espremer. Ela suspirou de alívio enquanto descansava a cabeça na laje atrás dela.\nEla não conseguia deixar de se preocupar com Cruz. Ele vai entrar em pânico e chorar? Talvez até enfrentasse a tempestade para implorar que o ancião enviasse um grupo de busca para ela? Será que o ancião enviará um, dada a condição adversa? Martha ficará preocupada por ela não estar em casa? Ou apenas está sentada e olhando para a lareira?\nDorothy podia ler a mente de Cruz. Ele quer que ela aprove Martha e pense nela como uma família, não apenas uma vizinha que ficará temporariamente. Mas eles nem sabem de onde Martha veio. Seu passado é uma folha em branco que ela nunca divulgou.\nDorothy se lembrou de como Martha se sentava diante da lareira: a cabeça baixa, o cabelo loiro pendurado ao lado do rosto, tranquilo, cansado, até mesmo exausto. Dorothy viu Martha sorrir apenas na mesa de jantar, um alívio rápido por deixar o passado para trás por um momento fugaz. Dorothy acreditava que não deveria confiar em tal pessoa, que Martha não seria uma boa \"família\". Ela veio aqui trazendo segredos, e seria assim que ela iria embora. Dorothy já estava farta das perdas...\nFelizmente, a casa de Martha está quase consertada.\nDorothy finalmente percebeu que a nevasca parecia ter cessado. Ela massageou as pernas dormentes, saiu da fenda e fez o possível para traçar um caminho no escuro. De repente, ela ouviu ruídos fracos. Ela sentiu seu sangue congelar quando viu brilhos verdes convergindo lentamente para ela.\nNo vento agonizante, ela podia ouvi-los respirando.\nSó podiam ser lobos.",
  str_dispatch_book_chaptercont_13000_7 = "\"Smack!\"\nOutro lobo colidiu com a neve rodopiante na frente de Dorothy. Ela perdeu a noção de muitos lobos que ela bloqueou com Luminática.\nApós a morte de seus pais, ela descobriu que poderia solidificar o ar. Era apenas um cubo transparente do tamanho de uma palma que desapareceu em uma dúzia de segundos no início. Mas então, o tamanho aumentou, assim como a duração. Na melhor das hipóteses, ela poderia produzir uma barreira de até a metade do tamanho de um portão por dois minutos.\nMas na noite escura, ela dificilmente poderia dar o seu melhor. Os lobos avançando se aproximaram cada vez mais. Ela podia até sentir o cheiro de suas babas rançosas. De repente, ela tropeçou. Ela olhou para baixo e viu um lobo segurando uma perna da calça, tentando puxá-la para trás. Ela gritou e atingiu o lobo na cabeça com um tijolo de ar. O lobo uivou de dor, mas ainda assim arrancou um bom pedaço da perna da calça, enquanto seus companheiros rondavam e rosnavam em uníssono.\n\"Smack!\" Ela cerrou os dentes, suor frio escorrendo, enquanto ela mal evitava outro ataque.\nEla sabia que não poderia continuar assim. O medo quase a paralisou, e ela estava diminuindo a velocidade que fazia barreira. Era como se uma voz clara falasse em seus ouvidos: Você não pode detê-los. A noite ainda está começando. É impossível.\nO frio feriu sua panturrilha exposta como uma faca, mas demorou muito para que Dorothy percebesse que estivera tremendo o tempo todo. Uma vez que o pavor se instalou, ele abriu a comporta para o desespero.\nA parede de ar se dissipou na nevasca. Ela não foi capaz de reformá-la. Não muito longe dela, os brilhos verdes dos olhos dos lobos ainda faiscavam malícia.\nUm lobo atacou. Dorothy ergueu os braços para cobrir o rosto.\nNo entanto, a dor não veio. Dorothy ouviu o barulho de algo congelando. Ela abaixou os braços e viu o lobo saltando suspenso no ar em uma pose cômica. No segundo seguinte, um flash passou, levantando o lobo alfa e jogando-o na neve. O lobo não respingou sangue apenas porque estava todo congelado por dentro. Dorothy queria gritar, mas não conseguia encontrar forças.\nAlguém chutou o lobo para o lado, se virou e ficou na frente de Dorothy. O capuz caiu para trás e as mechas de cabelos loiros esvoaçantes acariciaram seu rosto. Sua salvadora estava segurando uma adaga de lâmina dupla que emitia um brilho implacável na noite fria.\nDorothy sentiu algo quente no rosto. Ela percebeu que eram lágrimas.",
  str_dispatch_book_chaptercont_13000_8 = "A noite apavorante aconteceu há muito tempo. Dorothy parou de pensar sobre como Martha a levou para a vila, sobre como os cães de trenó cheiraram seus pés, sobre o suspiro de alívio do ancião e sobre o lamento de Cruz. Agora, ela só queria terminar de esculpir a lanterna de gelo para colocar no corredor.\nO Ano-Novo estava chegando.\nA casa de Martha foi consertada, mas o ancião a recrutou como um local de boas-vindas e entretenimento para convidados da cidade. Por isso, o ancião pagou um barril cheio de tubarão fermentado como compensação.\nDorothy já tinha perguntando a Martha sobre a adaga de duas lâminas. Martha apertou o interruptor no cabo de metal para retrair as lâminas e colocá-la na mão de Dorothy, dizendo que ela não iria mais usá-la, pois agora pertence a Dorothy. Ela sabia o que Martha estava querendo dizer e aceitou a adaga sem dizer uma palavra, abaixando sua guarda.\nMartha disse a ela: “Eu abandonei o passado, mas jamais abandonarei vocês.”\nLanternas de gelo se acenderam uma por uma. A Fogueira surgiu na praça da cidade. O ancião tocou o sino. Habitantes saíram de suas casas com várias comidas na mão: queijo, pão de mel, linguiça defumada, ensopados, tortas de fruta… Dorothy e Cruz se enrolaram em robes grossos brancos e felpudos, kebabs em mãos, bolsos cheios de balas de goma e saíram pela porta.\nMartha já estava perto da fogueira, conversando com o ancião. Ela acenou para os irmãos quando eles apareceram, com o sorriso afetuoso de sempre.\nOs habitantes se reuniram em volta da fogueira e do ancião, compartilhando histórias do último ano e dividindo suas comidas. Rapidamente, uma jovem começou a cantar. Os habitantes se juntaram bem rápido para fazer um coro harmonioso de canções antigas. Outra garota começou a dançar e sua saia com pelos girou, sua Luminática produzindo faíscas de fogo que sincronizavam com seus movimentos.\nDorothy sentou ao lado de Martha, batendo palmas ritmadas e cantarolando suavemente a melodia. Seus olhos brilharam como duas estrelas distantes e felizes.\nConforme a cantoria diminuía, uma Dorothy sorridente fechou os olhos e repousou seu queixo em suas mãos num formato de concha. Martha olhou ao redor e viu que os habitantes também fecharam seus olhos como se fossem rezar. Ela sussurrou para Cruz e descobriu que os habitantes estavam fazendo desejos para a próximo ano.\nDorothy abriu seus olhos e viu uma Martha sorridente, que parecia que ia perguntar o que Dorothy desejou. Mas, neste momento, Martha parou de sorrir. Seus olhos focaram em um canto da iluminação da fogueira.\nUma Dorothy atordoada olhou naquela direção, mas só viu escuridão.",
  str_dispatch_book_chaptercont_13000_9 = "Dorothy percebeu que a vila tinha um novo visitante quando ela ajudou alguns habitantes a carregar lenha. Um Aurorian desconhecido com cabelo escuro saiu da residência do ancião e foi para uma casa velha que foi consertada. Quando Dorothy saiu de casa, ela viu Martha consertando a roupa de Cruz próxima à lareira quando ela normalmente já estaria caçando faz tempo. Martha tinha sumido quando Dorothy voltou. Cruz apontou para a casa vizinha quando sua irmã perguntou onde a loira foi.\nO Aurorian de cabelo escuro veio atrás de Martha, Dorothy tinha certeza.\nNo almoço, Dorothy quis saber sobre o Aurorian de cabelo escuro, mas ela subestimou a relutância de Martha.\nMartha permaneceu em silêncio durante as indagações insistentes de Dorothy antes de admitir que o Aurorian é um “amigo”.\nDorothy não ficou satisfeita com a resposta. Ela estava morrendo de curiosidade de saber a origem e intenção do Aurorian, e se era uma possível ameaça a Martha.\n“Só um amigo”. Martha calmamente desprezou as perguntas dela.\nDorothy, desapontada, parou de insistir.\nO trio comeu em silêncio, até que o alarme soou do lado de fora.\nMartha foi a primeira a levantar e abrir a porta.\nHabitantes gritaram na praça da cidade, alguns xingando em voz alta, alguns chorando e outros sussurrando uns para os outros. Dorothy ouviu a comoção e seguiu Martha para o lado de fora da porta.\nA expressão de Dorothy se transformou em choque quando ela percebeu o que os habitantes estavam discutindo.\nEclipsitas. Os habitantes disseram que havia sinais de Eclipsitas na vizinhança.",
  str_dispatch_book_chaptercont_13000_10 = "O ancião convocou todos os homens adultos na vila, dividindo-os em grupos de cinco e os enviou em grupos de busca para procurar por atividades Eclipsitas.\nAssim que os grupos saíram da cidade, as crianças escalaram o arco para se despedirem daqueles que elas conheciam. Dorothy entrou de fininho entre os homens, segurando a adaga de duas lâminas escondida. O ancião jamais deixaria que ela se juntasse ao grupo de busca, mas ela sabia que tinha que fazer algo. Os grupos partiram um a um. Certificando-se de que ninguém estava vendo, Dorothy abaixou sua cabeça e saiu andando rapidamente, imaginando que alcançaria o último esquadrão que ia sair.\nDe repente, alguém agarrou seu braço.\n“O que você pensa que tá fazendo, Dorothy?” Era a voz da Martha.\nDorothy se esforçou para se desvencilhar. “Me solta!”\nMartha viu e pegou a adaga. “Você vai atrás dos Eclipsitas?”\n“Não é da sua conta!” Dorothy tentou pegar a adaga de volta, mas Martha desviou facilmente. “Me devolve!”\n“Volte pra casa comigo”, Martha ofereceu gentilmente. “Aí eu te devolvo”.\nDorothy cerrou os dentes e rasgou sua manga com um barulho alto, se afastando de Martha. Antes que ela pudesse correr, um par de braços em volta da sua cintura a impediu.\n“Você acha que é divertido brincar com os Eclipsitas?!”\nDorothy congelou. Martha nunca a repreendeu assim antes, mesmo que ela fosse muito grossa. Ela cautelosamente virou para Martha, e o rosto tremendo de raiva que ela viu era completamente desconhecido para ela.\n“Não brigue comigo!” Dorothy rapidamente se recuperou, endurecendo sua atitude. “Quem você pensa que é para me dizer o que fazer?”\nOs braços em volta da sua cintura abaixaram. Dorothy correu sem olhar para trás.\n“Você vai deixar seu irmão para trás desse jeito?”\nA voz enfurecida do ancião ressoou atrás dela. Dorothy fechou seus olhos frustrada e parou no meio do caminho.",
  str_dispatch_book_chaptercont_13000_11 = "Martha abriu a porta da casa e houve apenas um completo silêncio. O quarto dos irmãos estava fechado. Ela se aproximou e tentou bater, mas a mão dela parou no meio do ar, hesitante.\n“Há cinco anos, a vila foi atacada por Eclipsitas. O pai de Dorothy e Cruz estava em um grupo de busca que nunca voltou... Mais tarde, a mãe deles seguiu a trilha, mas se deparou com Eclipsitas. Ela voltou com feridas graves e morreu pouco depois...” O que o ancião disse ainda ressoava nos ouvidos de Martha. “Não seja tão dura com eles. Todos têm um passado que não podem esquecer.”\nEla hesitou um pouco mais e finalmente decidiu não bater na porta. Ela virou e olhou para fora.\n“Martha”, disse o Aurorian de cabelo escuro esperando na entrada, “você decidiu ir?”\n“Vamos”. Ela conformou-se com um suspiro.\nDe repente, o quarto abriu. Martha sentiu um puxão. Era Cruz. “Você pode entrar, Martha?”\nLá dentro, Dorothy estava sentada em silêncio na cama. Ela virou quanto Martha entrou e perguntou: “Você vai embora?”\nAntes que Martha pudesse responder, ela questionou: “É por minha causa?”\n“Sobre hoje, sinto muito...” Os lábios de Dorothy tremeram. “Foi muita grosseria da minha parte dizer aquilo...”\n“Não, não é isso.” Martha se agachou e olhou para os olhos em lágrimas dela. “Eu tenho que ir.”\n“Por quê?”\n“Eu sou... uma desertora”, Martha pausou. “Eu sou da Federação Illumina”.\nDorothy obviamente não sabia o que era a Federação Illumina, mas ela entendeu o “desertora”.\nNão posso mais lutar contra Eclipsitas. Nenhum dos meus companheiros sobreviveu. Eu não suportava lutar, então eu fugi até chegar em Northland”.\nMartha abaixou seus olhos. “Agora, um dos meus companheiros me achou. Se eu não voltar...”\n“Você não precisa ir!” Dorothy exclamou ofegante. “Diz para o seu amigo que você tá feliz aqui! Eles vão entender... Você pode implorar para o ancião, ele vai falar em seu nome...”\n“Você nunca vai nos deixar, né?”\n“Dorothy...” Martha limpou a lágrima do rosto da garota. “Eu sinto muito pelo que aconteceu com seus pais...”\nDorothy, assustada, parou por um momento. E então perguntou: “É por isso que você está indo?”\n“Eu não posso ficar com vocês... Por favor, me perdoem...”\nDorothy sentiu seu corpo tremer. “Então você sempre escolhe fugir?”\nO ar estava espesso com um silêncio desagradável. Martha não conseguia achar uma desculpa. Ela estava acostumada com o papel de desertora, uma face que ela, de forma desajeitada, fazia e que todos podiam ver. Era uma face decepcionante.\n“Vai logo”, disse Dorothy, desalentada, caminhando de costas como se quisesse se distanciar.\nMartha levantou, olhou para Cruz, que ficou de pé em um canto, e tentou passar a mão no cabelo dele, mas ele também se afastou. Ela forçou um sorriso e disse em uma voz baixa: “Não deixem a vila por enquanto. Se protejam.”\nMartha saiu do quarto, colocou a adaga na mesa da sala de estar e saiu da casa.",
  str_dispatch_book_chaptercont_13000_12 = "Era a manhã do dia seguinte quando Martha e o Aurorian de cabelo escuro saíram da vila. A neve sobre o arco tinha derretido, formando poças lamacentas no chão.\n“Você não vai se despedir daquelas crianças?”\n“Não é preciso”. Martha colocou seu capuz para cobrir sua cabeça da neve que derretia. “Eles não querem me ver mesmo.”\n“É fácil não ser encontrada”. O Aurorian tinha uma expressão sutil, mas complexa. “Tudo que você tem que fazer é continuar correndo até que os perseguidores percam a paciência. Illumina não vai perder tanto tempo assim com um desertor.”\nMartha zombou de uma maneira autodepreciativa. “Você pode me deixar ir agora.”\nO Aurorian não respondeu.\n“Você e eu sabemos que aquele tipo de vida é sem sentido”. Martha ouviu o som distante da neve pingando e sussurrou: “Eu não fugi de Illumina porque eu queria viver. Eu estava cansada de ser tratada como uma arma, cansada da luta sem fim.”\n“Então porque você escolheu voltar comigo?”\n“Porque...” Martha finalmente continuou após uma pausa significativa. “Eu sou uma desertora e sou a única que pode me perdoar por isso.”\n“Isso parece contraditório\".\n“Sim”, Martha riu, “foi isso que finalmente percebi depois de correr por tanto tempo.”\nO Aurorian parou de forma abrupta. “Você não pode mais ver a vila depois desta curva”.\nOs lábios de Martha se alegraram e sussurraram: “Obrigada.”\nEla virou. Da perspectiva dela, ela ainda podia ver o arco e os laços encharcados de neve derretida pendurados nos galhos.\nQuando estava mais longe, ela podia enxergar os telhados pretos altos, apesar de ainda ser muito cedo para as chaminés exalarem fumaça.\nMartha se arrumou para ir, mas notou alguém espiando do arco. Podia estar um pouco longe, mas ela não teve dificuldade em dizer que era Cruz.\nEla ficou de boca aberta e o vento frio balançou seu cabeço loiro. Suas bochechas ficaram geladas, mas seus olhos estavam quentes.\nEla viu uma garota de robe branco correndo em sua direção, parando a meia distância dela.\n“Dorothy?”\n“É pra você...” Uma Dorothy ofegante abriu sua mão para mostrar a adaga de duas lâminas. “Eu não quero isso.”\n“Você devia levar com você. Não vale a pena se você vai embora. Se isto é sua desculpa, eu não aceito. Não é nada especial e eu não ligo.” Dorothy apertou a adaga na mão de Martha e disse de forma teimosa:\n“Eu só quero saber quando você vai voltar.”\nEla então riu rapidamente. “Você vai voltar, né?”\nA mão dela segurando a adaga tremeu. Martha estava muda e só conseguia balançar a cabeça.\n“É uma promessa!” Dorothy pulou e acenou. “Adeus, Martha!”\nEla correu em direção à vila. Cruz saltou do arco. De mãos dadas, as duas crianças voltaram para a cidade, até que a parede escondesse suas formas.\nA fumaça finalmente subiu das chaminés nos telhados. Os laços flutuavam no vento novamente. A neve derretida caia no ritmo, das florestas até os campos, da estrada até a vila...\nQuando todo o gelo do inverno derreter, todos sabem que o arco ficará cheio de crianças observando o horizonte.",
  str_dispatch_book_chaptercont_14000_1 = "Caros Sr. Max e Sra. Minny,\nEsta é a Rosa do Deserto Rediesel. Eu vi seu anúncio em uma caixa de tequila pirata. Eles enrolaram seu folheto em uma massa e o usaram como um tampão entre as garrafas. Os preços em sua loja de peças parecem muito justos. Eu gostaria de ter encontrado você antes. Entrei em contato com uma caravana para ajudar a entregar esta carta de pedido para você em Umbraton. Agora estou com os dedos cruzados para que eles tenham uma jornada segura para começar a fazer negócios.\nAnexei uma lista separada de peças que preciso, junto com um desenho esquemático. Você o verá no verso desta carta.\nCalculei um preço aproximado com base no seu anúncio e enviei 1.500 Nightium para este pedido. Por favor, verifique o valor total. No caso de alguém da caravana ficar ganancioso, servindo-se de uma gorjeta em cima da taxa de serviço que já paguei. Se isso acontecer infelizmente, por favor, use um mensageiro confiável para sua resposta, e eu vou compensar você.\n\nCom os melhores cumprimentos,\nRosa\nEscrito em uma tarde seca\n\n\nPrezada Senhora Rosa,\nÉ nossa honra atendê-lo. As peças necessárias foram embaladas por categorias e enviadas de Umbraton usando a mesma caravana (recebemos exatamente 1.500 Nightium. Acho que você pode confiar e continuar usando o serviço deles). A quantia que você enviou é muito alta, então devolvemos 21 Nightium com esta carta. Espero que as peças cheguem até você mais cedo ou mais tarde. Tenha um bom dia.\n\nSeu,\nLoja de peças M&M\nEscrito no final da estação chuvosa\n\n\nObs:\nOlá, Rosa. Essa é a Minny. Eu não diria que gosto de ser tratada como uma senhorita. Parece tão elevado e muito importante. Mas meu pai adorava que você o chamasse de senhor. Os adultos parecem gostar do respeito alheio, mesmo que seja hipócrita. É provavelmente por isso que ele começou esta carta com a palavra querido. É um primeiro. Ele geralmente prefere o termo maldito.\nAjudei papai a separar as peças do seu pedido, mas, para ser sincero, não consigo imaginar onde elas serão usadas. Muitos dos recursos de que você precisa são bastante especiais, provavelmente já estão na prateleira de baixo do nosso armazém há um bom tempo. Tarefas de modificação regulares simplesmente não as usam. Por favor, diga-me para que servem, se não se importar. Estou realmente curioso!\nMais uma coisa. Por favor, não mencione isso ao meu pai. Eu não queria abrir sua carta, mas vamos lá. Ele me enviou para entregar o pacote.",
  str_dispatch_book_chaptercont_14000_2 = "Caros Sr. Max e Minny,\nSó recebi as peças da caravana ontem. Acho que nunca se deve esperar um bom serviço de correio de uma caravana. É seu trabalho vagar e enganar as primeiras nações ignorantes. Então eu estou usando um mensageiro adequado desta vez. Só descobri recentemente que o Sindicato dos Correios tem um posto não muito longe do nosso acampamento. Passar algumas horas da manhã para deixar meu pacote no posto deles é uma opção melhor para mim. Ouvi dizer que o Courier Union também tem uma boa reputação em Umbraton. Você não tem que lidar com a caravana de agora em diante.\nDesta vez eu preciso de alguns metais especiais. Não precisa ser matéria-prima. As peças que contêm esses metais fariam o mesmo. Favor me cobrar as peças. Uma lista dos metais é fornecida no verso desta carta.\nAnexei mais 1.500 Nightium. Por favor, mantenha o extra se houver algum e gentilmente considere um depósito para meus pedidos futuros. Eu tenho muitas coisas para consertar e remontar no Rediesel Desert. Mesmo aqueles que eu já fiz irão falhar ou quebrar mais cedo ou mais tarde.\nA propósito, o que estou tentando reformar é um hovercar. Alguma garota pode estar interessada nesta informação.\n\nCom os melhores cumprimentos,\nRosa\nEscrito em uma noite fria\n\n\nPrezada Senhora Rosa,\nÉ Minny. Você pode dizer pela caligrafia que eu não escrevi o título. Eu nunca usaria uma abertura tão antiga. Estou tão feliz que você não me chamou de miss desta vez. Parece muito mais legal. Mas suas últimas linhas não poderiam ser mais óbvias! Papai me olhou desconfiado assim que leu sua carta e me disse para \"cuidar dessa resposta a Lady Rosa, já que você gostava tanto de escrever\". É por isso que estou escrevendo para você à luz agora.\nAgora vamos ao que interessa. Meu pai escreveria muitas palavras inúteis aqui, como \"Os metais especiais que você precisava foram embalados por categorias e enviados para o Deserto Rediesel usando o Courier Union\" ou algo do tipo. Provavelmente é difícil para ele aceitar que você receberá esta carta e todas as partes simultaneamente.\nOs 1.500 Nightium que você enviou desta vez não são suficientes. Você nos deve 327 Nightium agora. Abrimos um livro exclusivo para Lady Rosa do Deserto Rediesel para registrar seus pagamentos e despesas. O pai achava que era o melhor plano de negócios de todos os tempos.\nPor acaso notei que os metais especiais do seu pedido são todos materiais essenciais para a confecção de próteses. Deus abençoe não é para você.\n\nSeu,\nMinny e Max\nEscrito pouco antes do Ano Novo",
  str_dispatch_book_chaptercont_14000_3 = "Caros Minny e Sr. Max,\nOs materiais metálicos que você me enviou ajudaram muito. Infelizmente, tenho que dizer a uma garotinha que foi realmente para mim. Nosso acampamento foi atacado por Eclipsites há alguns meses. Durante essa batalha, minhas pernas sofreram ferimentos leves, que persistiram e não cicatrizaram. Eu estava mancando, e dirigir só poderia acontecer em meus sonhos até que eu recebesse seu pacote. Agora eu posso fazer algumas cintas de perna para mim.\nNossa condição no Deserto Rediesel não é muito melhor do que nossos dias no Território Secreto. Eu esqueci de mencionar. Costumávamos fazer parte da Federação Illumina. Fomos enviados como grupo avançado para explorar o Território Secreto. Teria sido uma missão árdua, mas gloriosa, se não fosse por aqueles altos funcionários mesquinhos e ingratos. Somos livres no Deserto Rediesel, mas nos custa comida, sono e estabilidade manter nossa passagem para a liberdade.\nO ruim do Deserto Rediesel é o clima. A menos que você esteja em um oásis ou à beira do deserto, você teria que se esconder no subsolo para se salvar do sol mortal. Após o anoitecer, você precisa colocar suas camadas mais quentes para evitar que seu sangue e medula congelem. Não tínhamos muita experiência vivendo no deserto. Quando chegamos aqui, nosso hovercar estava severamente danificado e tive que substituir todas as peças. Esses Eclipsites errantes também me deixam louco. Preciso de mais alguns componentes de energia para atualizar nosso sistema de defesa. Uma lista é fornecida no verso desta carta, como antes. Junto com esta carta está também o desenho de modificação do meu hovercar. Pode fornecer alguma inspiração para Minny.\nSinto muito, mas nosso fundo está acabando. Não consigo quitar minhas dívidas desta vez. Você poderia me dar mais alguns dias? Tenha um ótimo dia.\n\nCom os melhores cumprimentos,\nRosa\nEscrito em uma manhã fria",
  str_dispatch_book_chaptercont_14000_4 = "Prezada Senhora Rosa:\nNos solidarizamos com sua situação. Você pode acompanhar o último pagamento quando enviar seu próximo pedido. Além disso, o esquema de modificação do hovercar que você enviou foi muito valioso e acredito que pode compensar uma parte de sua dívida.\nMuita saúde e sorte para você.\n\nSeu, \nPeças M&M\nNa estação das flores\n\n\nObs:\nRosa, esta é Minny de novo.\nEu me pergunto se sua perna já estava curada no momento em que escrevo este livro... Oh, como detesto essas saudações vazias que falharam em transmitir minha sinceridade e soar como mero serviço da boca para fora, mas eu realmente espero que você esteja se recuperando.\nVocê mencionou na carta anterior que já trabalhou para a Illumina, o que seria uma notícia chocante. Meu pai e eu tentamos adivinhar sua identidade antes. Eu conheci aqueles do Deserto Rediesel, e enquanto alguns deles estavam em mods, eles eram puros novatos comparados à sua experiência. O mistério foi finalmente resolvido por sua carta, e mal posso conter ou descrever minha excitação a não ser: \"Claro!\" Estamos honrados por ter conquistado sua confiança e não vamos decepcioná-lo ou revelar sua identidade a ninguém.\nO esquema de modding que você enviou é fantástico! Suponho que sua intenção é aumentar a estabilidade do carro ao pairar e garantir que nenhum detritos seja sugado para o interior. Também notei que o gerador é uma nova iteração, então decidi seguir o projeto, replicá-lo com meu pai, instalá-lo em nossa pequena picape e ver como funciona. Nunca se sabe. Talvez tenhamos uma coleta muito rápida em breve!",
  str_dispatch_book_chaptercont_14000_5 = "Caro Minny e Estimado Sr. Max:\nAnexei 3.000 Nightium. Além dos 327 que eu devia, gostaria de comprar outros instrumentos listados no verso desta folha.\nEu gostaria muito de deixar Minny saber que aprecio seus pensamentos, e acredito que ele seja sincero. Desde a nossa última correspondência, minhas pernas estão se recuperando e os aparelhos de metal devem sair em breve. Acho que isso não é possível sem a sua vontade. De qualquer forma, é um prazer conhecê-lo.\nTivemos dias muito melhores ultimamente, graças a um tiroteio. No Deserto Rediesel, temos que procurar bandidos errantes e eclipsitas. Os bandidos são surpreendentes em número aqui nas dunas, com pessoas cada vez mais desesperadas, seja simplesmente por desespero ou suas casas destruídas pelos Eclipsitas, prontas para apoiá-los todos os dias. Além de lutar contra Eclipsites, lutar contra bandidos também faz parte da vida cotidiana. Depois, algumas das vítimas desabrigadas recém-rendidas escolheriam se juntar a nós.\nE foi o que aconteceu com uma jovem há alguns dias. Um bando de bandidos invadiu sua aldeia. Ela foi a única a escapar. Não quero entrar em detalhes já que descrever eventos infelizes não é meu forte... Não que ela gostaria que eu contasse sua tragédia, de qualquer maneira. Ela realmente não queria ficar no começo, mas tentou nos contratar para vingar seu povo. Por isso, ela ofereceu um aparelho como pagamento, que praticamente produzia água destilada do nada – uma peça genuína de tecnologia antiga. Ela não estava nem um pouco assustada com a possibilidade de nós a estarmos traindo, já que ela sabia onde encontrar mais desses aparelhos. Nós apenas temos que trocar pelo local com corpos de bandidos mortos. Oh, o nome da garota é Summer, e ela é uma de nós agora.\nApós o tiroteio, encontramos um esconderijo atrás do outro no esconderijo dos bandidos cheio de Nightium, uma adega cheia de vinho, um armazém abastecido com armas e explosivos e até cinco caminhões adaptados. Mas tudo isso empalidece em comparação com o que o verão nos levou... Eu tenho uma necessidade urgente de desmontar criações de tecnologia antiga com as ferramentas adequadas. Talvez na próxima vez que eu escrever, eu tenha montado um gadget capaz de dispensar bebidas sem fim.\n\nSinceramente,\nRosa\nNo calor escaldante da tarde",
  str_dispatch_book_chaptercont_14000_6 = "Prezada Senhora Rosa:\nEstou honrado em receber seu pedido mais uma vez. Também estou feliz em saber que sua perna está melhorando. No entanto, lamento informar que conseguimos encontrar apenas alguns instrumentos que você solicitou, pois muitos deles eram praticamente desconhecidos e difíceis de localizar em mercados convencionais ou em ferros-velhos. Por favor, dê-nos mais tempo. Se tivermos sorte, talvez vejamos os itens da sua lista aparecendo em um leilão.\n\nSeu,\nPeças M&M\nEm uma tarde movimentada\n\n\nObs:\nOlá, Rosa! Acredito que, no momento em que escrevo, você esteja totalmente recuperado da lesão na perna. A vida é realmente traiçoeira no deserto de Rediesel, e espero que você não se machuque novamente.\nMal posso esperar para compartilhar o que aconteceu recentemente. Você sabe sobre a celebração do Dia da Fundação de Lumopolis, certo? Poucos dias antes desta carta, meu pai me deu consentimento para ir a Lumopolis sozinho. No Dia da Fundação, o hub de ônibus ficou mais tranquilo, e os turistas não precisaram apresentar documentos para aprovação do Ministério das Relações Exteriores. Fiquei três dias em um hotel de Lower Lumopolis e não voltei para casa até que a festa acabou ontem. Se você for a Lumopolis, certifique-se de me ter como seu guia. Com o passar dos dias, fui conhecendo a cidade como a palma da minha mão, de qual padaria tem o melhor bolo, qual loja oferece as frutas mais frescas, até onde ver o Santuário no Jardim de Lumopolis, não há nada que eu não tenha descoberto . A celebração real contou com desfiles e fogos de artifício, mas o mais importante, você pode experimentar todos os tipos de comida deliciosa de graça. Normalmente, eu achava os aurorianos da cidade distantes e arrogantes. Ainda assim, no Dia da Fundação, eles sorriam para todos, elaboravam a celebração para qualquer um e até convidavam você a entrar em suas casas para experimentar seus pratos. A hospitalidade estava fora do padrão, sem um sinal da vibração desagradável habitual. Desejo que todo dia seja o Dia da Fundação.\nAh, além dos instrumentos que meu pai encontrou para você, há uma especialidade local que trouxe de Lumopolis no pacote. Eu escolhi especificamente aqueles com datas de validade longas, então não se preocupe com eles expirando no caminho. Acompanha também uma marionete de macaco com chapéu vermelho, presente para mim do filho do estalajadeiro, com quem passei boa parte da festa. Eu tenho duas marionetes. Eu guardei um para mim, e este é para você. Por favor, valorize-o.",
  str_dispatch_book_chaptercont_14000_7 = "Caro Minny e Estimado Sr. Max:\nRecebi os instrumentos que vocês enviaram, o que agilizou muito minha pesquisa. Eu vi alguns dos itens listados apenas na Illumina, então não é uma surpresa que eles não estejam disponíveis em outros lugares, mas eu não estou decidido a eles. Se o preço do leilão for proibitivo, deixe-o ir.\nEstou escrevendo para você desta vez para ver se você pode encontrar algumas guitarras e alto-falantes antigos para mim. Alguns membros da equipe pegaram uma febre do rock-n-roll no deserto de Rediesel, e seu aniversário é daqui a um mês. Eu gostaria de modificar uma guitarra para ela para que ela não tirasse mais os meus cabos para as cordas da guitarra.\nO deserto nunca teve escassez de músicos, e nossa equipe, em particular, tem mais do que nossa parte. Eles são sempre improvisados. Sempre que eu entrava, ouvia todo tipo de barulho: tamborilando em garrafas de bebida ou barris de óleo, sacudindo calotas com os dedos, assobiando, etc... Dificilmente um momento de paz. Eles também compunham músicas, pintando letras com spray e notas por todas as paredes. Se você gosta de rock também, posso gravar algumas músicas para você.\nPeguei sua marionete de macaco, Minny. Está atrás do pára-brisa do hovercar agora. Estou chocado que você passou a celebração com um estranho. Isso não é como você em tudo. Falando nisso, você tem idade suficiente para ter um namorado? Estou brincando. Quase esqueci de te dizer, Summer adorou os scones e a geleia que você mandou. Eu mesmo preferia as passas e o queijo. É difícil tentar se acostumar com a comida no deserto. Quem sabe quantos vermes da areia em conserva eu vomitei. Os lanches que você enviou reviveram meu paladar.\n\nSinceramente,\nRosa\nNo intervalo da tarde após uma refeição completa",
  str_dispatch_book_chaptercont_14000_8 = "Caro Minny e Estimado Sr. Max:\nPreciso de um carregamento a granel de materiais para próteses desta vez. Perdoe-me, mas o analgésico passou e eu não conseguia controlar minha mão trêmula. Se você não conseguir decifrar o que está escrito no verso desta folha, consulte a lista de três anos atrás.\nEu nunca pensei que eles fariam isso, nem que eu acabaria me juntando a eles. Não consigo colocar em palavras meus sentimentos pela Illumina. Morei lá por mais de 20 anos, com amigos e colegas em todas as agências. Eu chamei Gannon de minha \"Cidade Mãe\". Eles me expulsaram sem cerimônia com armas e apatia, mas eu nunca imaginei que viraria uma arma para eles. Você pode pensar que lealdade é tolice. Afinal, como crianças que fugiram podem apontar armas para suas mães?\nEu não sei se os pôsteres da Illumina estariam nas paredes de Umbraton, mas se você ouviu o boato, é verdade: nós roubamos um transporte da Illumina. Seis motoristas, vinte guardas, nenhum sobrevivente. Estávamos com medo, e tenho vergonha de usar essa palavra como se isso justificasse a ação. Não consigo descrever a emoção que senti. O medo tomou conta de nós como demônios, obrigando-nos a puxar o gatilho incessantemente nos rostos inocentes. Conchas vazias choveram no chão e se enterraram na areia. Nós simplesmente não conseguíamos parar... Como chegou a isso?\nAdmito que os provocamos primeiro, mas ninguém previu um massacre a seguir. Começou como uma mera brincadeira. Eu não me lembro quando o primeiro tiro foi disparado, mas a próxima coisa que eu percebi foi que havia sangue por toda parte e penetrando na areia. A maior parte do meu braço direito sofreu queimaduras, minha panturrilha esquerda foi carbonizada por Lumantics e a rótula direita quebrada por balas. Acordei após a cirurgia com minha perna direita amputada do meio para baixo e minha perna esquerda abaixo do joelho. É um castigo pela minha traição, assim como pelo massacre. Paguei um alto preço pelo meu erro, mas não quero ficar confinado a um leito de doente. Perdoe-me, e eu entendo se você vê as próteses como uma maneira obscura de contornar a punição.\nDevo terminar esta carta agora. A dor é esmagadora. Você não será capaz de ler a escrita se eu continuar.\n\nRosa",
  str_dispatch_book_chaptercont_14000_9 = "Querida Rosa:\nVocê está se recuperando bem? Depois de todos esses anos, posso finalmente dizer a você, quando recebi sua carta, chorei debaixo do cobertor por um longo tempo, até pensei em convencê-lo a deixar o deserto e se mudar para Umbraton para ser nosso vizinho. Mas suas cartas seguintes não foram escritas com a mesma agonia. Em vez disso, eles eram sobre mods, música e lanches como antes, então eu acreditei que você estava melhorando e até fiz questão de evitar perguntas como \"Como está sua saúde?\" Admito que bebi demais hoje, então, por favor, não zombe de mim se eu escrever algo estúpido.\nEstou bêbado porque estou noivo. Eu posso te dizer, qualquer especulação que você teve sobre o filho do estalajadeiro de Lumopolis e eu, nada aconteceu. Embora trocássemos endereços e os e-mails funcionassem sem problemas entre Umbraton e Lumopolis, nunca nos escrevemos. De qualquer forma, pare de me provocar sobre ele. Conheço meu noivo desde criança. Ele estudou no exterior por um longo tempo, voltou com algumas habilidades estranhas e agora trabalha em vendas para uma guilda. Meu pai o considera bastante normal.\nLi muitos romances e me imaginei me casando, mas não posso deixar de me sentir nervosa com as núpcias iminentes, como se estivesse presa entre duas paredes, com dificuldade para respirar. Em Umbraton, a vida geralmente dá voltas inesperadas. Você poderia passar de se esconder da chuva com roupas esfarrapadas dentro de um beco minúsculo um dia para sentar em um trono de ouro com diamantes nos dedos no dia seguinte. Mas para alguns, como meu pai e eu, nossas vidas são simples. Nada tende a se desviar de comer, dormir, conversar, trabalhar, casar, ter filhos e morrer. Então este é outro evento esperado que estou enfrentando, mais um passo no caminho do meu destino.\nTudo isso provavelmente soa deprimente, mas o noivado deve ser um evento feliz, então eu não deveria ficar triste com isso. O casamento acontecerá em dois meses. Eu mesma fiz o convite e mal podia esperar para colocar seu nome no primeiro. Você estará no meu casamento com isso em mãos?\n\nSinceramente,\nMinny\nNo pôr do sol tranquilo",
  str_dispatch_book_chaptercont_14000_10 = "Querida Minny:\nA notícia do seu casamento me deu sentimentos contraditórios. Por favor, não tome isso como eu desaprovando. Estou apenas um pouco deprimido desde que você comparou com \"mais um passo no caminho do destino\". Eu também me senti assim. Exceto que estou vendo você dar esse passo de longe. Assisti a casamentos de amigos quando estava em Gannon, vendo-os saindo da igreja em meio a flores e fitas enquanto a porta para uma nova vida se abria para eles enquanto eu ficava para trás... Isso não era um sentimento bom, para dizer pelo menos.\nEu teria aparecido na primeira oportunidade antes. Agora, porém... desculpe não ter contado isso antes, eu fundi minhas próteses no banco do motorista para facilitar a condução, então é muito difícil para mim andar no chão. Além disso, perdoe meu egoísmo, mas não quero que você me veja assim.\nEu fiz um buquê de rosas de metal para você. Você pode sentir o cheiro do diesel nele. Torça o caule e as pétalas se abrirão ou fecharão. Talvez eu esteja ficando velha demais para ser romântica, mas acho que as rosas nunca sairão de moda. Espero que você goste das flores perenes e, da mesma forma, sua vida será livre de preocupações, pelo menos de chuva ou tempestade.\nVocê desenhou um lindo convite. Gosto muito do padrão nas costas. Diga-me, você fez bom uso do esquema que lhe enviei?\n\nSinceramente,\nRosa\nEm uma tarde tranquila",
  str_dispatch_book_chaptercont_14000_11 = "Caros Sr. Max e Srta. Minny:\nPor favor, aceite meus mais sinceros cumprimentos. Sou a assistente de Rosa, Summer, e tenho notícias infelizes: há alguns dias, nosso comboio foi emboscado por Eclipsites e, para cobrir a equipe, Rosa detonou o hovercar para parar os atacantes, mas também significa que ela não está mais conosco .\nDepois da amputação dupla, tenho enviado e recebido correspondências do Courier Union para ela. Acho que devo passar a notícia para você. Não tenho certeza se Rosa falou com você sobre isso, mas ela me disse que se o pior acontecer com ela, o saldo de seu depósito Nightium na M&M Parts será entregue à Srta. Minny. Fornecerei todos os documentos legais necessários o mais rápido possível.\nRosa muitas vezes mencionou você para mim. Suas peças nos ajudaram muito. A modificação para o hovercar, os instrumentos musicais da equipe, as próteses de Rosa... Seus componentes são onipresentes aqui. Todos no acampamento sabem que há um negociante de peças usadas em Umbraton que é honesto, confiável e amigo de Rosa.\nPerder Rosa é um grande golpe para nós. Ela sempre ajudaria os necessitados e nunca esqueceria suas promessas. Ela era um gênio da tecnologia que podia construir qualquer coisa que quisesse com chapas de metal, parafusos e chaves. Aprendi com Rosa desde os treze anos, aprendendo a desmontar e modificar com ela. Ela nunca se casou e não teve filhos, mas ainda assim, ela era uma mãe para mim. Tendo me correspondido com você ao longo dos anos, não acho que ela gostaria que terminasse com um pedido rabiscado às pressas, então enviei isso em seu nome. Espero que não se importe com minha grosseria.\n\nSinceramente,\nVerão\nEm uma manhã com uma tempestade de areia se aproximando",
  str_dispatch_book_chaptercont_14000_12 = "Querida senhorita verão:\nMuito obrigado por nos informar.\nA morte de Rosa entristece meu pai e eu. Ele chegou primeiro à sua carta, já que faz muito tempo que não estou na loja. A M&M Parts já esteve à beira do fechamento, mas conseguiu sobreviver graças a esses pedidos de Rosa. Nós não vendemos mais peças usadas para viver, mas papai ainda mantém a loja porque recebemos ocasionalmente pedidos por correio de antigos clientes regulares.\nJá faz tanto tempo que não me lembro como começamos a nos corresponder. Acho que recebemos uma carta bastante interessante que provocou uma resposta, que foi seguida por uma resposta gentil. Por causa disso, eu consegui fazer um grande amigo. Ela me enviava esquemas, me contava histórias do Deserto Rediesel e confidenciava tudo o que acontecia em sua vida. Antes de me casar, na carta que ela enviou ao lado das rosas de metal, ela escreveu que seus amigos casados abriram a porta para uma nova vida e a deixaram para trás. Eu pensei que ela estava reclamando até que eu finalmente entendi seus sentimentos mais tarde. Ela se arrependeu de ter ficado parada, mas provavelmente estou trancada atrás da porta pela qual passei.\nAté agora, ela continua sendo uma \"grande amiga\". Ela testemunhou a morte, acolheu uma nova vida, sempre teve vontade de ajudar os outros e sempre foi capaz de fazer as escolhas mais corajosas e inesperadas como seu sacrifício por você.\nTodo esse tempo, eu questionei mais de uma vez se Rosa realmente existia, e era tudo na minha imaginação, já que nunca nos conhecemos e ela nem compareceu ao meu casamento. Agora, eu prefiro que tudo seja uma fantasia, pois eu poderia pelo menos ressuscitá-la em minha mente. Mas é tudo em vão porque me lembro das rosas de metal que ela enviou na minha cabeceira e seus esquemas no meu caderno.\nAntes de escrever isso, pedi uma carona à caravana a caminho do deserto. Eu deveria vê-lo logo depois que você conseguir isso. Desejo a todos o melhor.\n\nSinceramente:\nMinny\nNa meia-noite tranquila",
  str_dispatch_book_chaptercont_15000_1 = "Qualquer um que fosse para Umbraton inevitavelmente entraria na arena de combate do Poço para assistir a uma ou mais rodadas de luta e matança. A corrente de ferro que pesava milhares de quilos presa em um anel, esticada para fora, pendurando pessoas e coisas no palco na luz. O público alinhado para cima em um círculo com o anel como centro e formou um arco circular. Os nobres adoravam criar guerreiros e colocá-los na arena para lutar entre si. Se um lutador não morresse durante a noite e tivesse mais vitórias, ele poderia usar o cinturão de ouro do Campeão da Meia-Noite na cintura. No entanto, este cinto foi, como de costume, permitido ser usado apenas por um dia e teve que ser devolvido quando o Poço abrisse à noite. Quando a luta se tornava acirrada, o público gritava e algumas pessoas jogavam moedas de ouro no palco. Cha-ching, Ba-ing, soava o dinheiro chovendo. Fiquei na arena até o amanhecer. A atmosfera tornou-se menos tensa e o público fraco e cansado se dispersou. As pessoas começaram a limpar o sangue na arena do Poço. A água foi derramada na plataforma de pedra, fazendo com que uma cortina de água vermelha pálida ficasse pendurada em sua borda. Empregados dedicados retiraram as moedas de ouro do palco para o vencedor e as limparam com água para remover o sangue e a poeira, colocando-as em um baú de lata, que dois homens carregaram.\nUma das melhores lutas que eu já vi aconteceu há três anos. Um tinha sido o campeão nos últimos dias. Uma exceção foi feita para ele usar o cinturão de Campeão da Meia-Noite para a arena. Havia dois chifres de bronze brilhantes em sua testa, e seus músculos escuros e ferozes ondulavam como ondas. Seu oponente era um homenzinho envolto em roupas sujas e cuja pele tinha hematomas por toda parte. Ele parecia ter sido gravemente ferido antes de sair. Quando os dois subiram ao palco juntos, houve muitas vaias na platéia. O garçom caminhou entre a platéia com uma bandeja para que os convidados fizessem apostas no lado que julgassem ter mais chance de ganhar. Quando ele veio para a minha amiga que me convidou para vir, ela apostou todas as suas apostas no homem mais pequeno. Fiquei muito surpreso e perguntei por que ela fez isso. Ela pegou seus binóculos e apontou para o homenzinho, dizendo: \"Esse homem é um dos homens da Sra. Red Mercury\".\nEmbora eu não fosse a Umbraton com frequência, ouvi um pouco da Sra. Red Mercury. Umbraton prosperou em todos os tipos de contrabando, sendo o mais perigoso o contrabando de armas. Se der certo, você pode ganhar um pote cheio de fortuna, mas, por outro lado, também pode custar sua vida. No entanto, fosse uma transação privada, um leilão secreto ou uma aquisição em massa, esses negócios estavam mais ou menos nas mãos de uma guilda, e a cabeça dela era a Sra. Mercúrio Vermelho. Eu assisti as duas pessoas lutarem. O Campeão da Meia-Noite deu um soco forte. Ele esmagou com Luminatics, que enviou detritos voando por toda parte. O homenzinho tropeçou e se esquivou para a esquerda e para a direita. Sempre que ele se movia mais devagar, ele era atingido por detritos e caía no chão, então ele mal precisava rolar para evitar ser atacado.\n\"A Sra. Red Mercury não se importa que seu subordinado esteja em uma briga mortal com alguém?\" Não pude deixar de perguntar ao meu amigo.\nMinha amiga balançou a cabeça e olhou para a escuridão no canto. \"Ela está sentada aqui assistindo.\" ela sussurrou.",
  str_dispatch_book_chaptercont_15000_2 = "Feixes quentes e secos de luz branca foram lançados por todo o ringue, a platéia estava escondida nas sombras e os gritos dos espectadores eram como um maremoto. Segui o vislumbre do meu amigo para olhar a escuridão e de repente descobri que estava em silêncio. Os lutadores vestidos de preto se levantaram solenemente, e bem no coração estava uma pessoa. No entanto, as sombras eram muito grossas para eu ver a aparência deles ou como eles estavam vestidos. Só parecia que o preto parecia estar corado de vermelho ferrugem. No ringue, o baixinho viu o momento certo para roubar um golpe bem embaixo das costelas do adversário. De repente, havia fogo ardendo, e o silvo do lutador campeão podia ser ouvido em toda a arena. Os espectadores ficaram empolgados por um momento. O homem atrás de mim que tinha apostado no lutador praguejou em voz baixa, mas a escuridão naquele canto permaneceu quieta.\nEu realmente não entendi, então perguntei ao meu amigo novamente. \"Por que a Sra. Red Mercury enviaria seus subordinados para o ringue?\"\nO povo de Umbraton não tinha o hábito de manter combatentes, e é inédito para um líder de Guilda usar seus homens como brinquedos. \n \"Aquele homem é um traidor que se juntou a alguns forasteiros tentando roubar os bens de sua própria Guilda,\" meu amigo sussurrou de volta para mim.\nDe repente fui iluminado. \"Você apostou mal. Olhe para a batalha no palco. A Sra. Red Mercury claramente quer este traidor morto.\" Eu disse ao meu amigo depois de pensar por um momento.\nMeu amigo sorriu e pegou seu binóculo para continuar assistindo a luta.\nApós ser atingido pelo homenzinho, o lutador ficou furioso e deu um grande passo para pegar o homenzinho. O golpe flamejante agora parecia ter drenado a força do homenzinho. Agora ele apenas se esquivou cansado, recuando direto para a borda do ringue. O lutador viu isso e balançou o braço para o homenzinho, acertando-o no peito, fazendo-o tropeçar para fora do ringue. Os espectadores ficaram surpresos, mas antes que percebessem, o homenzinho foi visto segurando a corrente de ferro e impedindo-se de cair do ringue. O lutador aproveitou o momento e se preparou para seguir com um golpe, mas o árbitro apitou no intervalo, e o lutador teve que pisar para trás enquanto o homenzinho tossia e lentamente rastejava de volta ao ringue.\nA luz branca brilhante se retirou do palco e lentamente se virou para iluminar a platéia perto do centro. De repente, houve movimento não muito longe daquele canto da escuridão. Um prisioneiro ensanguentado foi expulso. Sua cabeça estava pendurada e suas mãos estavam amarradas atrás dele. Tortamente, ele se ajoelhou na junção de luz e escuridão. Fiquei horrorizado. De repente, ouvi um silvo do palco e me virei apressadamente para ver de onde vinha o som. O que eu vi o homenzinho, que um momento atrás ainda estava no chão ofegante, correu para cima, mas foi parado pelo árbitro e atendentes. Uma série de maldições desafinadas veio dos cantos de sua boca manchada de sangue.",
  str_dispatch_book_chaptercont_15000_3 = "O apito soou, sinalizando o fim do intervalo. Os raios voltaram ao ringue e uma nova rodada de combate começou. Não pude deixar de olhar para o cativo ajoelhado no meio da platéia. Ele não fez nenhum barulho. Sua cabeça caiu. Sangue e suor caíram das pontas de seu cabelo. Quando me virei para olhar novamente para a arena, a situação havia se tornado muito diferente do primeiro tempo.\nChamas saltavam dos braços do homenzinho, e seus dez dedos estendidos queimavam vermelhos como ferro. Ele lentamente arrastou seu corpo em direção ao seu oponente. As pedras caíam como chuva na arena. Embora ele ainda estivesse se esquivando, ele não estava mais lutando. Ele continuou andando para frente, sobrecarregado por seus ferimentos quando foi atingido por pedras. O lutador foi forçado a se afastar dele, mas, eventualmente, ele não conseguiu mais impedi-lo de se aproximar. De repente, as chamas se acenderam e, após aquele flash de luz, o homenzinho agarrou os pulsos de seu oponente, e havia fumaça escaldante por toda parte. O lutador gritou de dor e raiva, e então o punho do pequeno homem se estendeu como um longo gancho e atingiu seu oponente diretamente no abdômen. Houve suspiros nas arquibancadas dos espectadores, e alguém atrás de mim ficou de pé e gritou severamente quando os servos saltaram para o ringue e arrastaram o homenzinho para longe do lutador.\nQuando o homenzinho reapareceu diante dos meus olhos, outro lutador estava na arena. Ele estava vestindo um smoking com uma gravata-borboleta em volta do pescoço. Uma camiseta que havia sido trocada recentemente, mas estava encharcada de sangue novamente em alguns momentos. Olhei para ele com o canto dos olhos e vi que ele estava tremendo um pouco. Ele ainda deve estar em choque com o combate de vida ou morte agora.\nAlguém chutou o cativo ajoelhado na escuridão, e uma voz profunda e suave pode ser ouvida perguntando ao pequeno traidor: \"Você sabe o nome dele?\"\nO traidor limpou o sangue da boca com um lenço e disse um apelido com voz rouca. A pessoa com a voz riu, pronunciando outro nome. \"Você nem sabe o nome verdadeiro dele, e se atreve a acreditar nele?\" ela disse.\nO traidor lutou para espremer algumas palavras entre os dentes. \"Senhora, minha irmã...\"\nA pessoa com a voz suspirou e disse: \"se sua irmã estivesse viva, as mentiras dele teriam durado tantos dias?\" O traidor ficou atordoado. Depois de um momento, soluços reprimidos brotaram de sua garganta quando ele lentamente caiu de joelhos e enterrou a cabeça na escuridão.\nDe repente, uma luz prateada fina, fria e afiada irrompeu do peito do cativo, mas rapidamente se retraiu quando o cativo grunhiu baixinho e caiu. Sangue carmesim fluiu debaixo dele. O som de choro parou. O traidor se endireitou e olhou em silêncio para o cadáver a seus pés, aparentemente em choque e fervendo de ódio. O som de roupas farfalhando foi ouvido, e a pessoa sentada na escuridão finalmente mostrou seu rosto sob a luz fraca.\nDe repente, ficou quieto por um tempo. O cabelo ruivo da pessoa rolou pelos ombros e braços. Parecia um rio escarlate silencioso. Ela olhou para o traidor ajoelhado a seus pés e não olhou para outro lugar, mas senti que seu olhar estava em toda parte, como a luz do dia em um dia frio. Olhei, e então não me atrevi a olhar novamente. Do canto dos olhos, pude ver vislumbres do lírio preso à lapela, que era tão fresco e delicado que se suspeitava que o orvalho estivesse rolando da ponta das pétalas.\nEla estendeu a mão na frente dos olhos do traidor. Como que com determinação, o traidor segurou as pontas dos dedos daquela mão, pressionou sua testa contra suas costas.\nEra um rito para jurar lealdade.",
  str_dispatch_book_chaptercont_15000_4 = "Minha amiga fez uma boa quantia nessa aposta, então ela me convidou para uma taverna para beber com ela. Lá, falei com ela sobre a Sra. Red Mercury. Minha amiga teve vários negócios com a guilda da Sra. Red Mercury e reconheceu muitas pessoas lá, mas ela só a conheceu uma vez. \"Ela nasceu muito atraente, então inevitavelmente haverá rumores se ela mostrar seu rosto com muita frequência.\" Minha amiga riu e disse quando falamos sobre ela.\nMas ainda havia muitos rumores sobre a Sra. Red Mercury em Umbraton. Eu tinha ouvido alguns deles, e a maioria deles eram tão ridículos que eram risíveis. No entanto, o verdadeiro era provavelmente sua origem. Surpreendentemente, ela veio de Lumopolis, e seu nome original não era Red Mercury, mas algo que parecia terminar com um som \"na\". De qualquer forma, era um nome comum para os nobres de Lumopolis. Uma pessoa de Lumopolis não acaba em Umbraton a menos que seja exilada. Eu não tinha ideia de como ela passou por isso.\n\"Ela era uma dama nobre que se casou com um homem humilde em Umbraton\", meu amigo se inclinou em direção ao meu ouvido e sussurrou, parecendo muito seguro sobre isso. \"De qualquer forma, é como uma daquelas histórias de amor estranhas. Ela conheceu um contrabandista de armas em Umbraton quando era jovem e de alguma forma ficou determinada a se casar com ele. Os anciãos de sua família não conseguiram impedi-la, então pediram à igreja que viesse e disse que tirariam seu título de nobreza, mas ela ainda se recusou a se curvar.\"\n\"Ela provavelmente era muito jovem na época.\"\n\"Claro que ela era jovem. Quem faria algo assim se não fosse jovem?\" \n\"Mesmo assim, o custo de virar sua vida de cabeça para baixo para apostar em um futuro ambíguo não é algo que as pessoas comuns possam aceitar.\" Suspirei, balançando a cabeça. \"Nesse caso, onde está o marido dela agora?\" Perguntei.\n\"Morta.\"\n\"Morta?\" Eu continuei a perguntar. \"Quão?\"\n\"Dizem que ele teve algum problema com um nobre de Lumopolis, o Hermes, você sabe. Pode ser algo relacionado a negócios ou algo que não pode ser contado. Quem sabe o que essas pessoas em Lumopolis estão fazendo.\" Meu amigo riu. \"E então ele foi pego e morto. A guilda que ele deixou para trás foi então tomada pela Sra. Red Mercury.\n\"A Sra. Red Mercury não se vingou?\"\n\"A família Hermes? Basta perguntar ao redor e você saberá o quão rico é. Mesmo a família original da Sra. Red Mercury não era nada comparada a eles.\"\n Comecei a ficar bêbado e não conseguia mais lembrar o que meu amigo disse claramente naquele momento. A única coisa que eu sabia era que eu estava supondo que pessoas como a Sra. Red Mercury nunca deixariam de lado tanto ódio.",
  str_dispatch_book_chaptercont_15000_5 = "Dois anos se passaram desde este incidente. Uma viscondessa que apreciou meu romance pediu a uma livraria de Lumopolis que imprimisse mais alguns volumes para a conveniência dos amantes de livros locais, então a livraria me convidou a Lumopolis para discutir os arranjos. Eu vi isso como uma oportunidade de visitar Lumopolis, então enviei a documentação de turismo para aprovação antes do horário marcado e fiquei em um hotel de trânsito.\nOs hotéis de trânsito vinham em todos os tipos de estilos, Umbraton ou Lumopolis, interligando-se fileira após fileira. O hotel em que fiquei foi inaugurado por uma família civil de Lower Lumopolis há mais de um século. Sua localização era ótima, com uma fileira de quartos de hóspedes e varandas, todos de frente para a luz fresca e diáfana da manhã. Eu geralmente escrevi histórias no meu quarto ao longo do dia. Ocasionalmente, à noite, vou ao salão principal para jantar, onde folheio o jornal ou uma revista até que as luzes do salão se apaguem. Até encontrei um romance meu na estante do corredor. A maior socialização que eu fazia todos os dias era com os atendentes, que traziam o café da manhã para o meu quarto enquanto embrulhavam as mudas de roupa dos hóspedes do dia anterior em um saco de pano para levar para a lavanderia. No segundo dia, as roupas limpas seriam devolvidas junto com o café da manhã.\nNaquele dia, ao entardecer, o céu estava carregado de nuvens escuras e ventos frios sopravam entre as paredes e grades das muitas casas da zona de trânsito. Sentindo-me triste, fui ao salão principal para jantar para levantar meu ânimo. Não havia muitos hóspedes no hotel, então a maioria se tornou rostos familiares ao longo da minha longa estadia. Mas desta vez, tive um vislumbre de uma figura totalmente desconhecida.\nVestida no estilo típico de Umbraton com botas de couro, um casaco grosso, um lenço preto finamente costurado em volta do pescoço e o cabelo todo enrolado em um elegante lenço cor de bronze, ela estava encostada no balcão enquanto perguntava algo ao estalajadeiro em uma voz suave, mas rápida. Eu não conseguia entender os detalhes, apenas pedaços como \"uptown\" e \"aprovação\" — presumivelmente ela estava perguntando sobre algo a ver com Lumopolis. Havia algo familiar em sua voz, e eu não pude deixar de usar minha luz restante para seguir sua figura até que ela se virasse.\nSeu nariz e boca estavam cobertos principalmente por um lenço preto, mas não havia como confundi-la – ela devia ser a Sra. Mercúrio Vermelho.",
  str_dispatch_book_chaptercont_15000_6 = "Descansando contra a mesa, ela observou enquanto a atendente levava sua mala para seu quarto, ocasionalmente levantando a mão para alisar mechas vívidas de cabelo vermelho em seu lenço. Eu me senti presa ao meu assento por um momento, incapaz de me mover e apenas ousando fingir olhar despreocupadamente ao redor do salão em uma tentativa de distinguir sua comitiva da multidão, mas não consegui encontrar nenhum sinal de um. Ela levantou o lenço novamente para cobrir completamente o nariz, antes de finalmente abaixar a cabeça e se dirigir rapidamente para o quarto. Então eu finalmente entendi – ela poderia estar em uma visita clandestina.\nEsperei que o som de seus passos desaparecesse antes de finalmente exalar. Uma pessoa como ela aparecendo de repente em um hotel na zona de trânsito me deu sentimentos ruins, então planejei voltar para o meu quarto mais cedo. Mas depois de me sentar por um momento, não pude deixar de continuar a olhar na direção em que ela foi. Depois de inconscientemente lançar meu olhar dessa forma algumas vezes, de repente voltei aos meus sentidos e percebi que estava ansioso para que ela aparecesse. Pensando nisso, decido sentar no corredor e esperar, com minha coragem do nada me acompanhando.\nUma atendente me trouxe outra cerveja e, quando eu estava na metade, ela finalmente e lentamente emergiu das sombras do corredor do quarto de hóspedes. Ela havia trocado o lenço e estava usando um chapéu de abas largas, e seu cabelo comprido estava agora em uma trança que estava escondida entre o lenço e o casaco. Querendo evitar a atenção dos outros, ela apenas caminhou por áreas mal iluminadas antes de escolher uma mesa em um canto negligenciado para se sentar - bem perto da estante e na minha direção às 10 horas. Fiquei surpreso, mas secretamente eufórico.\nEnquanto esperava que o atendente servisse sua refeição, ela casualmente tirou um livro da estante – pude ver claramente que era meu romance publicado alguns anos antes. Como se uma força externa estivesse me puxando para ficar de pé, agarrei a caneca de cerveja de madeira em minhas mãos úmidas e caminhei até ela.\nFinalmente, eu estava bem na frente dela. Tarde demais para voltar agora, agarrei a caneca de cerveja enquanto me abaixei, apontei para o livro em sua mão e, fingindo ignorar sua identidade, perguntei: \"Senhorita, você gosta deste livro?\"\n\"Eu gosto do título.\" ela disse, sorrindo calmamente enquanto levantava a cabeça para olhar para mim. Ela passou a ponta dos dedos sobre o título dourado. \"Isso me lembra algo bonito.\"\nEu lutei para respirar, como se constrangido pelo peso de sua própria beleza. Era como se meu rosto tivesse sido mergulhado em água fria ou preso em um vendaval congelante. Fiz todos os esforços para respirar sem deixar meus dentes baterem: \"Estou muito feliz que você gostou, eu escrevi... Veja, esse é o meu nome.\"",
  str_dispatch_book_chaptercont_15000_7 = "Quando me sentei em frente a ela, percebi que a parte de trás da minha camiseta já estava encharcada de suor frio. Parece que conversamos sobre romances por um tempo, quando me lembrei, não consegui me lembrar de uma única frase com clareza. A única coisa que ficou na minha memória é uma sensação estranha, como se eu estivesse totalmente submersa em um lago enquanto outra pessoa estava andando na margem como se toda a azáfama fosse dividida em outro mundo. Quando voltei aos meus sentidos, eu já estava sentado na varanda do lado de fora do quarto dela. Estávamos separados por uma pequena mesa redonda com petiscos e taças de vinho, e um vaso de gargalo fino no centro segurando um único lírio com sépalas verdes exuberantes.\nA noite ainda não havia caído completamente, mas as nuvens acima bloqueavam a luz, envolvendo a área que nos cercava em uma escuridão sombria. Estremeci com o vento frio, então me lembrei de que a atendente estava preparando a refeição no salão principal quando de repente sugeriu que fôssemos comer na varanda. Ela tirou o chapéu e o cachecol e os jogou pela janela do quarto. Ela estava enrolada em seu casaco e nos braços de sua cadeira, mas não estava mais totalmente coberta. Assustada, virei o rosto e me concentrei em seu cabelo ruivo solto e esvoaçante ao vento, com muito medo de olhar diretamente para ela.\n\"Eu estou indo para Lumopolis, também.\" Ela sorriu enquanto enxugava os dedos com uma toalha de papel umedecida. Foi até agora que eu me lembrei que estávamos falando sobre nossos respectivos itinerários mais cedo. \"Eu morei em Lumopolis quando era jovem. Todos os meus amigos de infância moravam lá.\"\n\"Depois fui para Umbraton. Estava tudo ótimo, tirando aquela discussão com meu amigo antes de sair.\"\n\"Sobre o que você discutiu?\" Eu me endireitei para ouvi-la.\n\"Foi há tanto tempo que já esqueci. Tudo o que me lembro é a raiva, como se meu coração tivesse inchado, batendo forte e forte no meu peito. Quando penso nisso agora, nada me vem à mente, exceto um sentimento infantil.\" Seus dedos limpos lentamente penteiam seu cabelo enquanto sua trança gira e suavemente se desfaz. \"Recentemente, eu estava pensando naquele amigo de novo - começou com um sonho.\"\n\"Um sonho?\"\n\"Sim. No sonho, eu estava de volta ao meu antigo quarto, com suas paredes brancas e porta marrom-dourada. Eu estava sentado na frente da penteadeira que sempre usei naquela época. Seu espelho refletia o rosto do meu amigo Ela estava segurando um pente e estava escovando meu cabelo para mim.\" Ela juntou seus longos cabelos como um rio e olhou para mim, aparentemente me avaliando, antes de vagar de volta em seus pensamentos. \"Ela estava linda, muito mais bonita do que nunca. Depois que acordei, pensei nela por muitos dias.\"\n\"Então, você está indo para Lumopolis para ver seu amigo?\"\n\"Não exatamente 'ver minha amiga',\" ela disse com um suspiro, \"Vê-la, embora bom, também seria difícil, infelizmente. Mesmo se eu só a visse de longe, ainda seria bom.\"\nOs hotéis da zona de trânsito estavam todos iluminados agora em halos de luz de vários tamanhos, brilhando através do vento úmido e da névoa. Ela olhou para mim com o copo de vinho na mão. Eu estava em transe, então senti a onda de medo gradualmente subir em mim novamente – A expressão em seu rosto lentamente retrocedeu até que apenas alguns vestígios dela foram deixados. Era uma metáfora para o destino, como as bordas suaves e silenciosas da lua. Quando a mortalha da escuridão caiu, seu rosto também afundou na sombra, junto com seus longos cabelos em forma de bandeira, que brilhavam em um vermelho frio e enferrujado nas profundezas da escuridão.",
  str_dispatch_book_chaptercont_15000_8 = "Acordei com falta de ar, então percebi que estava deitada na minha cama ainda intacta. Não pude deixar de me sentir aliviada. Minha cabeça doía com uma dor formigante – os restos de uma ressaca. Além das cortinas, o céu ainda estava escuro — devo ter acordado mais cedo do que de costume, e o atendente ainda não havia batido na minha porta. Saí do meu quarto apoiando minha cabeça em uma mão e fui para o quarto da Sra. Red Mercury, apenas para descobrir que estava vazio. Frustrada e desapontada, caminhei cansada pelo resto do corredor até chegar ao salão principal, não parando até que avistei o estalajadeiro.\n\"Com licença, você sabe se... aquela senhora,\" eu disse com a voz rouca, apontando para o quarto atrás de mim, \"Ela foi embora?\"\n\"Ela saiu cedo esta manhã.\" disse o estalajadeiro, parando seu trabalho e olhando para mim com interesse. \"As pessoas de Lumopolis vieram buscá-la em seu dirigível flutuante. Ela deve ser uma nobre, não é?\"\nEu não sabia se balançava a cabeça ou balançava a cabeça, tudo o que senti foi uma lenta decepção. O estalajadeiro suspirou, \"Quando ela entrou, eu pude dizer imediatamente que ela estava diferente - a beleza, era quase inquietante.\" Ele virou um olhar de aprovação para mim enquanto falava: \"Estou surpreso que você teve a coragem de subir e falar com ela.\"\nEu balancei minha cabeça, sentindo uma amargura na minha garganta enquanto eu lentamente me virava para voltar para o meu quarto. Sentei-me à mesa e, alguns momentos depois, o atendente chegou com meu café da manhã e roupas limpas. Continuei sentado à escrivaninha por um longo tempo, levantando-me quando a luz do sol do lado de fora da janela começou a perfurar meus olhos.\nDe acordo com minha rotina habitual, fui até o sofá para arrumar minhas roupas antes de guardá-las no armário. Distraidamente, eu estava dobrando minhas roupas enquanto um pequeno pedaço de coisa murcha flutuava entre os vincos. Eu o peguei e fiquei chocado com o que vi...\nEra um lírio seco que tinha sido achatado como um marcador de página. Este era o cartão de visita dela.",
  str_dispatch_book_chaptercont_15000_9 = "Esperei mais três ou quatro dias depois disso e, surpreendentemente, meu pedido de entrada na cidade ainda não havia sido aprovado. Perplexo e inquieto com meu encontro com a viscondessa e o livreiro a poucos dias de distância, tudo o que eu podia fazer era sair do hotel e pedir notícias de Lumopolis, tentando encontrar outra maneira de não atrasar meu encontro.\nFoi durante o interrogatório que fiquei sabendo do mais recente caso de assassinato em Lumopolis, cuja infeliz vítima era o filho mais velho da família Hermes. Lumopolis foi isolada devido ao incidente, acumulando todos os aplicativos para entrar nele. Incapaz de parar de pensar nisso, não pude deixar de me sentir ansioso no caminho de volta para o hotel. Enquanto eu refletia sobre o que a Sra. Red Mercury havia dito, continuei sentindo que suas palavras estavam cheias de significados ocultos, e que um deles pode ter insinuado esse assassinato. Fiquei tão perdido em pensamentos que até esqueci meu encontro com a viscondessa.\nA história se espalhou como fogo, com anedotas na boca até mesmo dos lavadores de hotel, mas eu me vi de alguma forma desconectado de toda a excitação. Eu era um insider com um segredo para proteger, e eu não poderia revelar meus verdadeiros sentimentos até que a tempestade passasse. Alguns dias depois, os pedidos de entrada na cidade foram retomados gradualmente e os documentos de aprovação começaram a circular junto com o resultado da investigação do assassinato - o assassino havia sido capturado e seria enforcado em Lumopolis.\nEncontrei-me com a viscondessa, mas estava distraída, tentando várias vezes interromper suas divagações sobre a leitura com perguntas sobre detalhes do caso do assassinato. Ela estava concentrada e exuberante enquanto falava, como se a perda da vida de duas pessoas não fosse motivo de alarme ou algo que ela não tinha intenção de mencionar a alguém de fora como eu. Não havia nada que eu pudesse fazer além de suprimir minhas dúvidas. Depois do nosso encontro, a viscondessa pediu ao livreiro que me levasse a um passeio por Lumopolis antes de nos despedir.\nPedi impacientemente ao livreiro que me levasse para ver a forca, e chegamos ao entardecer.\n\"A execução ainda não começou?\" Eu perguntei esperançoso.\nO livreiro pensou por um momento, então perguntou: \"Você quer dizer o assassinato da família Hermes do outro dia?\"\n\"Sim.\"\n\"Acabou.\" Provavelmente notando a confusão em meu rosto, ele acrescentou: \"A sentença foi executada ontem.\"\nAs pessoas normalmente não eram permitidas perto da forca e só podiam assistir de longe. Apenas algumas pessoas estavam andando pelo local, junto com um pombo cujo pequeno corpo corpulento se mexeu enquanto bamboleava pelo chão.\n\"Você viu isso?\" Eu perguntei a ele.\n\"Claro.\"\n\"Você sabe quem foi o assassino?\"\n\"Você terá que perguntar com o Salão de Justiça.\"\nMinha suspeita cresceu. \"Que tipo de pessoa era o assassino?\"\n\"Eu não sei\", disse o livreiro, balançando a cabeça. \"Os condenados têm que usar uniformes prisionais, você não pode dizer nada sobre eles através dessas roupas esfarrapadas. Suas cabeças também são cobertas com um saco de estopa, ou capacetes de ferro com apenas dois buracos para os olhos no caso de crimes graves. ver os rostos dos criminosos durante o enforcamento.\"\n\"Por que?\"\n\"Isso seria assustador, não seria?\" ele riu.\nEu me senti abalada ao ouvir isso e só consegui forçar uma risada. \"É menos perturbador quando eles estão mascarados, eu acho.\"\n\"Mais divertido, também!\" ele disse, ainda rindo.",
  str_dispatch_book_chaptercont_15000_10 = "Saí de Lumopolis como se estivesse fugindo. Um amigo me convidou para ficar com eles em Umbraton, mas entrei em pânico e recusei. Quando fui para Umbraton, já era vários meses depois.\nMeu amigo me convidou para uma bebida, como de costume. O bar estava cheio de gente e ressoava com uma conversão densa e fragmentada. Já meio bêbado, meu amigo virou o copo e apontou para um lugar na multidão, dizendo: \"Olha, é aquele rebelde do Poço\".\nVirei a cabeça para olhar e meus olhos pousaram no homenzinho de preto e me lembrei vagamente da luta de alguns anos atrás. Minha mente foi então inundada com memórias da Sra. Red Mercury. Se eu o tivesse encontrado há alguns meses, certamente o teria evitado, mas depois do que aconteceu, fiquei com a calma. Segurando meu copo na minha mão, fui até ele.\n\"Eu me lembro de você\", eu disse, levantando meu copo para ele, encorajada pelo álcool. \"Eu vi você no Poço.\"\nSua expressão ficou incerta por um momento enquanto ele e seus companheiros trocavam olhares. Com meu medo e memória da ferocidade dessas pessoas há muito esquecidas, continuei: \"Eu cruzei o caminho de sua diretora, Sra. Mercúrio Vermelho\".\nAo ouvir isso, suas expressões finalmente se suavizaram.\n\"Por favor, dê a ela meus cumprimentos. Eu sou o escritor - hotel da zona de trânsito, ela vai se lembrar.\" Observei suas expressões cuidadosamente, procurando traços de tristeza para corroborar minhas suspeitas. Mas o jovem com uma velha cicatriz em seu rosto tinha apenas uma expressão branda e vaga.\n\"Ela está bem, eu espero?\" Eu perguntei, sondando.\n\"Ela está muito bem,\" Eles se entreolharam, suspirando levemente, \"mas ela não é mais a diretora da guilda.\"\n\"Isso significa que você está sem um diretor agora, não é?\"\nEles riram ruidosamente: \"Quando um vai, outro toma seu lugar. Você já ouviu falar de uma guilda sem um diretor?\"\nCom isso, a conversa parou abruptamente. Não voltei a ver a Sra. Red Mercury depois disso, nem ouvi nenhuma notícia sobre ela.\nAs fofocas sobre Umbraton e Lumopolis se espalham incessantemente entre as marés de pessoas. Ouvi a maioria desses rumores fragmentados, mas não consegui decifrar de nenhum deles se a Sra. Sonhe.",
  str_dispatch_book_chaptercont_15000_11 = "Caros leitores, é uma honra conhecê-los na coleção de romances da Sra. Yvonne. Esperamos que você não fique descontente com nossa seleção de \"Mrs. Red Mercury\" como o título geral da coleção. \"Mrs. Red Mercury\", embora talvez não seja o melhor trabalho de Yvonne - afinal, é apenas um conto - mas é o que aparece com mais destaque em suas discussões. Como leitora fiel da Sra. Yvonne, meu primeiro pensamento depois de terminar esta saga de personagens foi: \"Quero encontrar a verdadeira 'Sra. Red Mercury'.\" Imagino que muitos de vocês devem ter tido o mesmo pensamento.\nPara este fim, liguei especificamente para a guilda Umbraton, paguei a taxa de entrada de 1.000 Nightium para visitar o Pit e pedi a alguém para verificar alguns arquivos no Lumo Hall of Justice. Cheguei a questionar cada um dos servos da família Hermes sobre aquele sensacional caso de assassinato. Agora, vou compartilhar minha pesquisa e conclusões com todos vocês.\nAs histórias da Sra. Yvonne são conhecidas por serem \"verdadeiras\", pois você sempre pode encontrar algumas \"verdades\" nelas. Por exemplo, a guilda de traficantes de armas de Umbraton—Para ser preciso, Umbraton tem muitas dessas guildas, mas algumas também negociam outros itens. Este romance foi escrito dez anos atrás, e é difícil determinar se havia uma guilda presidindo todo o comércio naquela época. Afinal, perseverança suficiente não é a única para desvendar as complexidades de Umbraton.\nQuanto ao caso de assassinato de Lumopolis, é de fato atestado nos arquivos e é muito conhecido em Lumopolis. O filho mais velho da família Hermes, assim como o do Ancião Lachon, foi assassinado e, por acaso, o ferimento fatal foi causado por uma arma de aço fina, o que facilmente lembra aquela arma empunhada pela Sra. luz prateada\" que matou o cativo no Poço é uma combinação perfeita para esse detalhe. O que não foi encontrado nos arquivos, no entanto, foi o verdadeiro autor do assassinato. Eles foram claramente condenados à morte, mas Lumopolis continua relutante em divulgar os detalhes para o mundo exterior, muito menos mostrar o rosto do assassino. Nem mesmo os servos da família Hermes que testemunharam o assassinato puderam dizer como era o assassino. Ainda assim, não há necessidade de frustração, este é simplesmente o caminho de Lumopolis e sua nobreza. No entanto, a verdade virá à tona um dia. Afinal, ninguém vive para sempre, certo?",
  str_dispatch_book_chaptercont_15000_12 = "O que nós leitores estamos preocupados acima de tudo é a verdadeira identidade da Sra. Red Mercury, estou certo? No entanto, de acordo com minha pesquisa, a Sra. Red Mercury é de fato um personagem fictício. Sua beleza exagerada é a prova. Dez anos atrás, os romances eram especialmente populares (e continuam a vender bem até hoje, é claro), e suas protagonistas femininas sempre foram incrivelmente bonitas. A Sra. Yvonne concedeu à Sra. Red Mercury uma beleza \"perturbadora\" puramente como uma sátira inexpressiva da tendência do dia. Afinal, os romances estão cheios de casais que se unem apesar dos grilhões do status.\nEntão, nesta história, a que destino a Sra. Yvonne deixou a Sra. Red Mercury? É como a pergunta que ela faz no final – ela foi para Lumopolis para se vingar ou para ver um amigo? Combinado com os rumores de Lumopolis nos últimos anos – muitos nobres foram executados ou exilados (nem sabemos ao certo por que) – podemos absolutamente adivinhar que, no cenário da Sra. Red Mercury casado em Umbraton foi para refúgio. Afinal, nós, leitores do trabalho da Sra. Yvonne, conhecemos bem seus hábitos de escrita - ela se destaca em usar mentiras para mascarar \"o indizível\".\nSendo esse o caso, há alguma maneira de determinarmos se a Sra. Red Mercury acabou de ir a Lumopolis para ver um amigo? A resposta é não, não há. No capítulo sobre o encontro no hotel, a Sra. Yvonne é mesquinha nas informações autênticas e eficazes que ela transmite, como se um rio passasse por ela e ela apenas se inclinasse para pegar um punhado de água - esse punhado sozinho não pode definir todo o rio. Na história, talvez aquela pobre vítima fosse de fato o inimigo que a Sra. Red Mercury queria morto, ou talvez ela simplesmente sentisse falta de seu amigo de infância, ou talvez ambos fossem verdade, mas ela só contou a \"me\" metade disso.\nCaros leitores, vocês devem achar minha conclusão frustrante. No entanto, \"Mrs. Red Mercury\" não é uma história de detetive, nem a Sra. Yvonne pretendia escrever uma história sobre \"a verdade\". O que ela quer nos oferecer é a \"realidade\", as histórias da vida de pessoas reais escondidas por lendas. Ao dar à Sra. Mercúrio Vermelho os lírios frescos, a espada afiada e a beleza estonteante, seu objetivo é apenas focar nossa atenção para que não percamos o momento em que os personagens se encontram, aquele momento de \"realidade\" - nesse um punhado de água é algo mais valioso do que todas as lendas juntas.",
